export let animalAffectionTools = safeLSJSON(localStorage.getItem("hl_animal_affection_tools"), {
  pettingHand: false,
  brush: false,
  musicBox: false
});

function sanitizeAffectionCounts(raw) {
  const out = {};
  if (!raw || typeof raw !== "object") return out;
  Object.keys(ANIMAL_DATA).forEach(type => {
    const perType = raw[type];
    if (!perType || typeof perType !== "object") return;
    Object.keys(ANIMAL_LOVE_ITEM_XP).forEach(key => {
      const v = perType[key];
      const n = Number(v);
      if (v !== null && v !== undefined && v !== "" && isFinite(n) && n >= 0) {
        if (!out[type]) out[type] = {};
        out[type][key] = Math.round(n * 100) / 100;
      }
    });
  });
  return out;
}

export let animalAffectionCounts = sanitizeAffectionCounts(safeLSJSON(localStorage.getItem("hl_animal_affection_counts"), {}));

export function setAnimalAffectionCount(type, key, val) {
  if (!(type in ANIMAL_DATA) || !(key in ANIMAL_LOVE_ITEM_XP)) return;
  const n = typeof val === "number" ? val : parseFloat(val);
  if (!isFinite(n) || n < 0) {
    if (animalAffectionCounts[type]) {
      delete animalAffectionCounts[type][key];
      if (!Object.keys(animalAffectionCounts[type]).length) delete animalAffectionCounts[type];
    }
  } else {
    if (!animalAffectionCounts[type]) animalAffectionCounts[type] = {};
    animalAffectionCounts[type][key] = Math.round(n * 100) / 100;
  }
  saveAnimalAffectionCounts();
}

function setAnimalAffectionTool(key, val) {
  if (!(key in ANIMAL_LOVE_ITEM_XP)) return;
  animalAffectionTools[key] = !!val;
  saveAnimalAffectionTools();
}

function getFavouriteFoodKeyAtLevel(fromLevel) {
  const table = ANIMAL_FOOD_XP_BY_LEVEL[Math.min(15, Math.max(0, fromLevel))];
  let best = "kernelBlend";
  [ "kernelBlend", "hay", "nutriBarley", "mixedGrain" ].forEach(k => {
    if (table[k] > table[best]) best = k;
  });
  return best;
}

function getAnimalXpModifiers(type) {
  const active = getActiveAnimalBoosts(type);
  let xpMultTotal = 1;
  let affectionXpMultTotal = 1;
  let loveFlatXpAddTotal = 0;
  active.forEach(b => {
    if (b.xpMult) xpMultTotal *= b.xpMult;
    if (b.affectionXpMult) affectionXpMultTotal += b.affectionXpMult;
    if (b.loveFlatXpAdd) loveFlatXpAddTotal += b.loveFlatXpAdd;
  });
  return {
    xpMultTotal: xpMultTotal,
    affectionXpMultTotal: affectionXpMultTotal,
    loveFlatXpAddTotal: loveFlatXpAddTotal
  };
}

function getConfiguredAnimalHeads() {
  const heads = [];
  Object.keys(ANIMAL_DATA).forEach(type => {
    const counts = getAnimalCount(type);
    const qty = Math.max(0, parseFloat(counts.qty) || 0);
    if (qty <= 0) return;
    heads.push({
      type: type,
      qty: qty,
      level: Math.min(15, Math.max(1, parseInt(counts.level) || 1))
    });
  });
  return heads;
}

function getAffectionScales(type) {
  const counts = animalAffectionCounts[type];
  if (!counts) return null;
  const keys = Object.keys(ANIMAL_LOVE_ITEM_XP).filter(k => animalAffectionTools[k] && counts[k] !== undefined);
  if (!keys.length) return null;
  const head = getConfiguredAnimalHeads().find(h => h.type === type);
  if (!head || head.qty <= 0) return null;
  const defaults = computeAnimalAffectionFigures(type, head.level - 1, null);
  const scales = {};
  keys.forEach(k => {
    const tool = defaults.tools.find(t => t.key === k);
    const defaultTotal = head.qty * (tool ? tool.uses : 0);
    const n = counts[k];
    scales[k] = defaultTotal > 1e-9 ? {
      scale: n / defaultTotal
    } : {
      perHead: n / head.qty
    };
  });
  return scales;
}

export function computeAnimalAffectionFigures(type, fromLevel, scales, modsIn) {
  const effectiveScales = scales === undefined ? getAffectionScales(type) : scales;
  const mods = modsIn || getAnimalXpModifiers(type);
  const chances = ANIMAL_LOVE_CHANCES[Math.min(15, Math.max(0, fromLevel))];
  const totalWeight = chances.pettingHand + chances.brush + chances.musicBox;
  const opportunities = ANIMAL_LOVE_OPPORTUNITIES_PER_CYCLE;
  const tools = Object.keys(ANIMAL_LOVE_ITEM_XP).map(key => {
    const chance = totalWeight ? (chances[key] || 0) / totalWeight : 0;
    const owned = !!animalAffectionTools[key];
    const xpEach = (ANIMAL_LOVE_ITEM_XP[key] + mods.loveFlatXpAddTotal) * mods.affectionXpMultTotal;
    let uses = owned ? opportunities * chance : 0;
    const override = owned && effectiveScales ? effectiveScales[key] : null;
    if (override) uses = override.scale !== undefined ? uses * override.scale : override.perHead;
    return {
      key: key,
      owned: owned,
      chance: chance,
      xpEach: xpEach,
      uses: uses,
      overridden: !!override
    };
  });
  const fixedUses = tools.reduce((sum, t) => sum + (t.overridden ? t.uses : 0), 0);
  const autoUses = tools.reduce((sum, t) => sum + (t.overridden ? 0 : t.uses), 0);
  if (fixedUses > opportunities) {
    const factor = opportunities / fixedUses;
    tools.forEach(t => {
      t.uses = t.overridden ? t.uses * factor : 0;
    });
  } else if (fixedUses + autoUses > opportunities) {
    const factor = (opportunities - fixedUses) / autoUses;
    tools.forEach(t => {
      if (!t.overridden) t.uses *= factor;
    });
  }
  let avgPerCycle = 0;
  tools.forEach(t => {
    t.contribution = t.uses * t.xpEach / opportunities;
    avgPerCycle += t.uses * t.xpEach;
  });
  return {
    tools: tools,
    avgPerOpportunity: avgPerCycle / opportunities,
    opportunities: opportunities,
    avgPerCycle: avgPerCycle,
    multiplier: mods.affectionXpMultTotal,
    flatAdd: mods.loveFlatXpAddTotal
  };
}

export function computeAnimalAffectionSummary(type) {
  const head = getConfiguredAnimalHeads().find(h => h.type === type);
  const qty = head ? head.qty : 0;
  const mods = getAnimalXpModifiers(type);
  const overrides = animalAffectionCounts[type] || {};
  const tools = {};
  Object.keys(ANIMAL_LOVE_ITEM_XP).forEach(k => {
    tools[k] = {
      key: k,
      owned: !!animalAffectionTools[k],
      hasOverride: overrides[k] !== undefined,
      xpEach: (ANIMAL_LOVE_ITEM_XP[k] + mods.loveFlatXpAddTotal) * mods.affectionXpMultTotal,
      defaultCount: 0,
      count: 0,
      xp: 0
    };
  });
  if (head) {
    const scales = getAffectionScales(type);
    computeAnimalAffectionFigures(type, head.level - 1, null, mods).tools.forEach(t => {
      tools[t.key].defaultCount = qty * t.uses;
    });
    computeAnimalAffectionFigures(type, head.level - 1, scales, mods).tools.forEach(t => {
      tools[t.key].count = qty * t.uses;
      tools[t.key].xp = qty * t.uses * t.xpEach;
    });
  }
  return {
    tools: tools,
    qty: qty,
    capacity: qty * ANIMAL_LOVE_OPPORTUNITIES_PER_CYCLE,
    opportunities: ANIMAL_LOVE_OPPORTUNITIES_PER_CYCLE
  };
}

function runAnimalCycleSim(type, scales) {
  const thresholds = ANIMAL_XP_THRESHOLDS[type];
  const mods = getAnimalXpModifiers(type);
  const maxXp = thresholds[15];
  const maxCycleXp = maxXp - thresholds[14];
  const levelOf = xp => getAnimalLevelFromXp(type, xp, true);
  const cycles = [];
  let xp = 0;
  let maxCycles = 0;
  for (let i = 0; i < 160 && maxCycles < 16; i++) {
    const startXp = xp;
    const startLevel = levelOf(startXp);
    const startsAtMax = startXp >= maxXp;
    const favouriteFoodKey = getFavouriteFoodKeyAtLevel(startLevel);
    const feedKeyUsed = omnifeedEnabled ? "omnifeed" : favouriteFoodKey;
    const baseFoodXp = ANIMAL_FOOD_XP_BY_LEVEL[startLevel][feedKeyUsed];
    const boostedFoodXp = Math.max(1e-9, baseFoodXp * mods.xpMultTotal);
    let loveXp = 0;
    if (i > 0) {
      loveXp = computeAnimalAffectionFigures(type, startLevel, scales, mods).avgPerCycle;
      xp += loveXp;
    }
    let ready = !startsAtMax && levelOf(xp) !== startLevel;
    let feeds = 0;
    while (!ready && feeds < 500) {
      const before = xp;
      xp += boostedFoodXp;
      feeds++;
      if (before >= maxXp) ready = Math.max(before - maxXp, 0) % maxCycleXp + boostedFoodXp >= maxCycleXp; else ready = levelOf(before) !== levelOf(xp);
    }
    cycles.push({
      startLevel: startLevel,
      claimLevel: levelOf(xp),
      feeds: feeds,
      loveXp: loveXp,
      xpStart: startXp,
      xpEnd: xp,
      favouriteFoodKey: favouriteFoodKey,
      feedKeyUsed: feedKeyUsed,
      baseFoodXp: baseFoodXp,
      boostedFoodXp: boostedFoodXp,
      isMax: startsAtMax
    });
    if (startsAtMax) maxCycles++;
  }
  return cycles;
}

export function getAnimalCycleRecord(type, level, scales) {
  const target = Math.min(15, Math.max(1, parseInt(level) || 1));
  const cycles = runAnimalCycleSim(type, scales === undefined ? getAffectionScales(type) : scales);
  if (target >= 15) {
    const steady = cycles.filter(c => c.isMax).slice(-12);
    const last = steady[steady.length - 1] || cycles[cycles.length - 1];
    const meanFeeds = steady.reduce((sum, c) => sum + c.feeds, 0) / Math.max(1, steady.length);
    const meanLove = steady.reduce((sum, c) => sum + c.loveXp, 0) / Math.max(1, steady.length);
    const th = ANIMAL_XP_THRESHOLDS[type];
    const exactFeeds = last && last.boostedFoodXp > 0 ? Math.max(0, th[15] - th[14] - meanLove) / last.boostedFoodXp : meanFeeds;
    return Object.assign({}, last, {
      feeds: exactFeeds,
      loveXp: meanLove
    });
  }
  return cycles.find(c => c.claimLevel >= target) || cycles[cycles.length - 1];
}

export function computeAnimalFeedFigures(type, level) {
  const displayLevel = Math.min(15, Math.max(1, parseInt(level) || 1));
  const thresholds = ANIMAL_XP_THRESHOLDS[type];
  const mods = getAnimalXpModifiers(type);
  const scales = getAffectionScales(type);
  const record = getAnimalCycleRecord(type, displayLevel, scales);
  const affection = computeAnimalAffectionFigures(type, record.startLevel, scales, mods);
  return {
    favouriteFoodKey: record.favouriteFoodKey,
    feedKeyUsed: record.feedKeyUsed,
    noOfFeeds: record.feeds,
    baseFoodXp: record.baseFoodXp,
    xpMultTotal: mods.xpMultTotal,
    boostedFoodXp: record.boostedFoodXp,
    avgLoveXpPerCycle: record.loveXp,
    affection: affection,
    xpGap: Math.max(0, thresholds[Math.min(15, record.startLevel + 1)] - record.xpStart),
    carryIn: Math.max(0, record.xpStart - thresholds[record.startLevel]),
    expNeeded: record.isMax ? Math.max(0, thresholds[15] - thresholds[14] - record.loveXp) : Math.max(0, thresholds[Math.min(15, record.startLevel + 1)] - record.xpStart - record.loveXp)
  };
}

const ANIMAL_LOVE_ITEM_KEYS = {
  "Petting Hand": "pettingHand",
  Brush: "brush",
  "Music Box": "musicBox"
};

export function computeAnimalRemainingLoveSlots(asleepAt, lovedAt, readyAt, now) {
  if (!isFinite(asleepAt) || !isFinite(readyAt) || readyAt <= asleepAt || now >= readyAt) return 0;
  const third = (readyAt - asleepAt) / 3;
  const nextAt = Math.max(asleepAt + third, (isFinite(lovedAt) ? lovedAt : 0) + third);
  const first = Math.max(now, nextAt);
  let slots = 0;
  for (let k = 0; k < 3; k++) {
    if (first + k * third < readyAt) slots++;
  }
  return slots;
}

export function computeAnimalRealLoveXp(type, level, animal, now, readyAt) {
  const slots = computeAnimalRemainingLoveSlots(animal.asleepAt, animal.lovedAt, readyAt, now);
  if (!slots) return {
    slots: 0,
    xp: 0
  };
  const affection = computeAnimalAffectionFigures(type, level);
  const itemKey = ANIMAL_LOVE_ITEM_KEYS[animal.item];
  let xp;
  if (itemKey) {
    const tool = affection.tools.find(t => t.key === itemKey);
    if (!tool || !tool.owned) return {
      slots: slots,
      xp: 0
    };
    xp = tool.xpEach;
  } else {
    xp = affection.avgPerOpportunity;
  }
  xp += (slots - 1) * affection.avgPerOpportunity;
  return {
    slots: slots,
    xp: xp
  };
}

export function computeAnimalRealProgress(type, animal, now, readyAt) {
  const thresholds = ANIMAL_XP_THRESHOLDS[type];
  const hasXp = typeof animal.xp === "number" && !isNaN(animal.xp);
  const level = hasXp ? getAnimalLevelFromXp(type, animal.xp, true) : 1;
  const xp = hasXp ? animal.xp : thresholds[level];
  const isReadyState = animal.state === "ready";
  const isMax = level >= 15;
  let xpGap, nextThreshold, nextLevelLabel, isMaxCycle;
  if (!isMax) {
    nextThreshold = thresholds[level + 1];
    xpGap = Math.max(0, nextThreshold - xp);
    nextLevelLabel = "Lv" + (level + 1);
    isMaxCycle = false;
  } else {
    const maxLevelXp = thresholds[15];
    const cycleXP = maxLevelXp - thresholds[14];
    const progress = Math.max(0, xp - maxLevelXp) % cycleXP;
    xpGap = Math.max(0, cycleXP - progress);
    nextThreshold = maxLevelXp + cycleXP;
    nextLevelLabel = "next cycle";
    isMaxCycle = true;
  }
  if (isReadyState) xpGap = 0;
  const favouriteFoodKey = getFavouriteFoodKeyAtLevel(level);
  const feedKeyUsed = omnifeedEnabled ? "omnifeed" : favouriteFoodKey;
  const baseFoodXp = ANIMAL_FOOD_XP_BY_LEVEL[Math.min(15, Math.max(0, level))][feedKeyUsed];
  const mods = getAnimalXpModifiers(type);
  const boostedFoodXp = Math.max(1e-9, baseFoodXp * mods.xpMultTotal);
  const love = xpGap > 0 ? computeAnimalRealLoveXp(type, level, animal, now, readyAt) : {
    slots: 0,
    xp: 0
  };
  const noOfFeeds = Math.ceil(Math.max(0, xpGap - love.xp) / boostedFoodXp);
  let claimLevel;
  if (isReadyState) {
    claimLevel = Math.max(1, level);
  } else if (isMax) {
    claimLevel = 15;
  } else {
    const xpAfter = xp + love.xp + noOfFeeds * boostedFoodXp;
    claimLevel = Math.min(15, Math.max(level + 1, getAnimalLevelFromXp(type, xpAfter, true)));
  }
  let costFeeds = noOfFeeds;
  let costFeedKey = feedKeyUsed;
  if (isReadyState || animal.state === "happy" || animal.state === "sad") {
    const cycle = getAnimalCycleRecord(type, claimLevel);
    const cycleFeeds = Math.round(cycle.feeds);
    if (isReadyState || cycleFeeds > noOfFeeds) {
      costFeeds = cycleFeeds;
      costFeedKey = cycle.feedKeyUsed;
    }
  }
  return {
    level: level,
    xp: xp,
    isReadyState: isReadyState,
    costFeeds: costFeeds,
    costFeedKey: costFeedKey,
    claimLevel: claimLevel,
    xpGap: xpGap,
    nextThreshold: nextThreshold,
    nextLevelLabel: nextLevelLabel,
    isMaxCycle: isMaxCycle,
    favouriteFoodKey: favouriteFoodKey,
    feedKeyUsed: feedKeyUsed,
    boostedFoodXp: boostedFoodXp,
    loveSlots: love.slots,
    expectedLoveXp: love.xp,
    noOfFeeds: noOfFeeds
  };
}

export function computeAnimalYieldsForLevel(type, level, realFeedBuffName) {
  const cfg = ANIMAL_DATA[type];
  const lvl = Math.min(15, Math.max(1, parseInt(level) || 1));
  const lvlData = cfg.levels[lvl - 1];
  const active = getActiveAnimalBoosts(type);
  let yieldMultAllTotal = 1;
  const yieldAdd = [ 0, 0 ];
  const budAddSum = [ {}, {} ];
  active.forEach(b => {
    if (b.yieldMultAll) yieldMultAllTotal *= b.yieldMultAll;
    if (b.yieldAddAll) {
      yieldAdd[0] += b.yieldAddAll;
      yieldAdd[1] += b.yieldAddAll;
    }
    if (b.productIndex != null && b.yieldAdd) {
      const budKey = b.isBud && b.budId ? b.budId : null;
      if (budKey) {
        budAddSum[b.productIndex][budKey] = (budAddSum[b.productIndex][budKey] || 0) + b.yieldAdd;
      } else {
        yieldAdd[b.productIndex] += b.yieldAdd;
      }
    }
  });
  budAddSum.forEach((sums, idx) => {
    const vals = Object.values(sums);
    if (vals.length) yieldAdd[idx] += Math.max(...vals);
  });
  const spice = realFeedBuffName !== undefined ? {
    yieldMultAll: realFeedBuffName === "Salt Lick" ? 1.05 : 1
  } : typeof getSpiceEffectForAnimalType === "function" ? getSpiceEffectForAnimalType(type) : {
    yieldMultAll: 1
  };
  yieldMultAllTotal *= spice.yieldMultAll;
  const yields = [ Math.max(0, (lvlData.y[0] + yieldAdd[0]) * yieldMultAllTotal), Math.max(0, (lvlData.y[1] + yieldAdd[1]) * yieldMultAllTotal) ];
  return {
    yields: yields,
    products: cfg.products
  };
}

