export function getCropMachineOilCap() {
  let mult = 1;
  try {
    if (isSkillActive("skill_leak_proof_tank")) {
      const s = SKILL_BOOSTS.find(sk => sk.id === "skill_leak_proof_tank");
      mult = s && s.oilTankMult || 1;
    }
  } catch (e) {}
  return CROP_MACHINE_OIL_CAP_BASE * mult;
}

export const RESTOCK_GEM_COST = {
  seeds: 15,
  tools: 10,
  all: 20
};

export function isBuildingBoostActive(id) {
  return typeof isBoostActive === "function" ? isBoostActive(id) : false;
}

export function computeBoostedStock(baseStock, kind, itemName) {
  let stock = baseStock;
  if (kind === "seed" && isBuildingBoostActive("warehouse_stock")) stock = Math.ceil(stock * 1.2);
  if (kind === "tool" && isBuildingBoostActive("toolshed_stock")) stock = Math.ceil(stock * 1.5);
  let flatAdd = 0;
  if (kind === "tool" && itemName && typeof BOOSTS !== "undefined") {
    BOOSTS.forEach(b => {
      if (b.category === "tools" && b.scope === "tool" && b.target === itemName && b.stockAdd && typeof isBoostActive === "function" && isBoostActive(b.id)) {
        flatAdd += b.stockAdd;
      }
    });
  }
  if (kind === "seed" && itemName && typeof BOOSTS !== "undefined" && isFullMoonToday()) {
    BOOSTS.forEach(b => {
      if (b.scope === "fruitList" && b.fruits && b.fruits.includes(itemName) && b.stockAdd && typeof isBoostActive === "function" && isBoostActive(b.id)) {
        flatAdd += b.stockAdd;
      }
    });
  }
  return stock + flatAdd;
}

export const SYNODIC_MONTH_DAYS = 29.530588853;

export function isFullMoonToday(date) {
  date = date || new Date;
  const knownFullMoonUTC = Date.UTC(2024, 0, 25, 17, 54, 0);
  const synodicMonthMs = SYNODIC_MONTH_DAYS * 864e5;
  const diffMs = date.getTime() - knownFullMoonUTC;
  const cycles = diffMs / synodicMonthMs;
  const frac = cycles - Math.floor(cycles);
  const daysFromFull = Math.min(frac, 1 - frac) * SYNODIC_MONTH_DAYS;
  return daysFromFull <= 1;
}

export function fullMoonSeedStockQty(name) {
  const baseStock = BASE_STOCK_FRUITS[name];
  if (baseStock == null) return baseStock;
  return computeBoostedStock(baseStock, "seed", name);
}

