(function migratePlotCounts() {
  const old = localStorage.getItem("hl_plot_counts");
  if (old && !localStorage.getItem("hl_plot_count")) {
    try {
      const vals = Object.values(JSON.parse(old)).map(v => parseFloat(v) || 0);
      if (vals.length) globalPlotCount = Math.max(...vals);
    } catch (e) {}
    localStorage.setItem("hl_plot_count", String(globalPlotCount));
    localStorage.removeItem("hl_plot_counts");
  }
})();

