export let ascensionRanks = safeLSJSON(localStorage.getItem("hl_ascension_ranks"), {});

export let syncedSkillLevels = safeLSJSON(localStorage.getItem("hl_synced_skill_levels"), {});

function ascensionGetPath(obj, path) {
  return path.split(".").reduce((o, k) => o == null ? undefined : o[k], obj);
}

function ascensionSetPath(obj, path, val) {
  const parts = path.split(".");
  const last = parts.pop();
  let node = obj;
  parts.forEach(k => {
    if (node[k] === undefined) node[k] = {};
    node = node[k];
  });
  node[last] = val;
}

export function getAscensionRank(id) {
  return ascensionRanks[id] || 1;
}

export function getSkillRankMult(id) {
  if (!isSkillActive(id)) return 1;
  const data = ASCENSION_RANK_DATA[id];
  if (!data || !Array.isArray(data.values)) return 1;
  const v = data.values[Math.min(Math.max(getAscensionRank(id), 1), data.values.length) - 1];
  return typeof v === "number" && v > 0 ? v : 1;
}

function setAscensionRank(id, rank) {
  if (rank <= 1) delete ascensionRanks[id]; else ascensionRanks[id] = rank;
  saveAscensionState();
  applyAscensionRanks();
  refreshAfterSkillChange();
}

function applyAscensionRanks() {
  Object.keys(ASCENSION_RANK_DATA).forEach(id => {
    const data = ASCENSION_RANK_DATA[id];
    const owned = isSkillActive(id);
    const rank = getAscensionRank(id);
    SKILL_BOOSTS.filter(s => s.id === id).forEach(entry => {
      if (!entry._ascBase) entry._ascBase = {};
      if (data.byTarget) {
        const f = data.field;
        if (!f) return;
        const valuesForTarget = data.values[entry.target];
        if (!valuesForTarget) return;
        if (!Object.prototype.hasOwnProperty.call(entry._ascBase, f)) entry._ascBase[f] = ascensionGetPath(entry, f);
        if (owned) {
          ascensionSetPath(entry, f, valuesForTarget[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
        return;
      }
      if (data.byScope) {
        const cfg = data.byScope[entry.scope];
        if (!cfg) return;
        const f = cfg.field;
        if (!Object.prototype.hasOwnProperty.call(entry._ascBase, f)) entry._ascBase[f] = ascensionGetPath(entry, f);
        if (owned) {
          ascensionSetPath(entry, f, cfg.values[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
        return;
      }
      if (data.byRole) {
        const cfg = data.byRole[entry._ascRole];
        if (!cfg) return;
        const f = cfg.field;
        if (!Object.prototype.hasOwnProperty.call(entry._ascBase, f)) entry._ascBase[f] = ascensionGetPath(entry, f);
        if (owned) {
          ascensionSetPath(entry, f, cfg.values[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
        return;
      }
      if (!data.field) return;
      const fields = Array.isArray(data.field) ? data.field : [ data.field ];
      fields.forEach(f => {
        if (!Object.prototype.hasOwnProperty.call(entry._ascBase, f)) entry._ascBase[f] = ascensionGetPath(entry, f);
        const valuesForField = Array.isArray(data.values) ? data.values : data.values[f];
        if (!valuesForField) return;
        if (owned) {
          ascensionSetPath(entry, f, valuesForField[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
      });
    });
  });
}

function getAscensionTotals() {
  let points = 0, shards = 0;
  Object.keys(ASCENSION_RANK_DATA).forEach(id => {
    if (!isSkillActive(id)) return;
    const rank = getAscensionRank(id);
    if (rank <= 1) return;
    const skill = SKILL_BOOSTS.find(s => s.id === id);
    const cost = ASCENSION_UPGRADE_COST[skill && skill.skillTier || 1];
    const steps = rank - 1;
    points += cost.points * steps;
    shards += cost.shards * steps;
  });
  return {
    points: points,
    shards: shards
  };
}

