export let greenhouseBuds = [];

try {
  greenhouseBuds = safeLSJSON(localStorage.getItem("hl_greenhouse_buds"), []);
  if (!Array.isArray(greenhouseBuds)) greenhouseBuds = [];
} catch (e) {
  greenhouseBuds = [];
}

function allBudBoostEntries() {
  let all = [];
  greenhouseBuds.forEach(bud => {
    all = all.concat(buildBudBoostEntries(bud.id, bud.typeId, bud.stemId, bud.auraId));
  });
  return all;
}

