export let spiceUsage = function() {
  const dflt = {
    saltLick: {
      active: false,
      chicken: false,
      sheep: false,
      cow: false
    },
    honeyTreat: {
      active: false,
      chicken: false,
      sheep: false,
      cow: false
    }
  };
  try {
    const saved = safeLSJSON(localStorage.getItem("hl_spice_usage"), null);
    if (!saved) return dflt;
    return {
      saltLick: {
        ...dflt.saltLick,
        ...saved.saltLick
      },
      honeyTreat: {
        ...dflt.honeyTreat,
        ...saved.honeyTreat
      }
    };
  } catch (e) {
    return dflt;
  }
}();

