let _cascadeScheduled = false;

let _cascadeFn = null;

export function scheduleCascade(fn) {
  _cascadeFn = fn;
  if (_cascadeScheduled) return;
  _cascadeScheduled = true;
  const runner = () => {
    _cascadeScheduled = false;
    const toRun = _cascadeFn;
    _cascadeFn = null;
    if (toRun) toRun();
  };
  if (typeof requestIdleCallback === "function") {
    requestIdleCallback(runner, {
      timeout: 120
    });
  } else {
    setTimeout(runner, 0);
  }
}

function applySkillModifiers() {
  SKILL_BOOSTS.filter(s => s.modifiesId).forEach(s => {
    const target = BOOSTS.find(b => b.id === s.modifiesId);
    if (!target) return;
    if (!Object.prototype.hasOwnProperty.call(target, "_baseAoE")) target._baseAoE = target.plotCap;
    if (!Object.prototype.hasOwnProperty.call(target, "_baseTimeMult")) target._baseTimeMult = target.timeMult;
    if (!Object.prototype.hasOwnProperty.call(target, "_baseYieldAdd")) target._baseYieldAdd = target.yieldAdd;
    if (!Object.prototype.hasOwnProperty.call(target, "_baseHarvestAdd")) target._baseHarvestAdd = target.harvestAdd;
    const active = isSkillActive(s.id);
    let rankPlotCap = s.aoePlotCap;
    let ascensionAoeApplied = false;
    if (active && s.aoeSizeByRank) {
      const rank = getAscensionRank(s.id);
      if (rank > 1) {
        const size = s.aoeSizeByRank[Math.min(Math.max(rank, 1), 3) - 1];
        rankPlotCap = size * size;
        ascensionAoeApplied = true;
      }
    }
    target.plotCap = active && rankPlotCap ? rankPlotCap : target._baseAoE;
    target._ascensionAoeApplied = ascensionAoeApplied;
    target.timeMult = active && s.overrideTimeMult ? s.overrideTimeMult : target._baseTimeMult;
    target.yieldAdd = active && s.extraYieldAdd ? +((target._baseYieldAdd || 0) + s.extraYieldAdd).toFixed(4) : target._baseYieldAdd;
    target.harvestAdd = active && s.extraHarvestAdd ? +((target._baseHarvestAdd || 0) + s.extraHarvestAdd).toFixed(4) : target._baseHarvestAdd;
  });
}

setTimeout(applySkillModifiers, 0);

(function ensureBudsActive() {
  let changed = false;
  BOOSTS.filter(b => b.isBud).forEach(b => {
    if (!selectedBoosts.includes(b.id)) {
      selectedBoosts.push(b.id);
      changed = true;
    }
  });
  if (changed) localStorage.setItem("hl_selected_boosts", JSON.stringify(selectedBoosts));
})();

(function dedupeExclusiveGroups() {
  const seenGroup = {};
  const keep = [];
  for (let i = selectedBoosts.length - 1; i >= 0; i--) {
    const id = selectedBoosts[i];
    const boost = BOOSTS.find(b => b.id === id);
    if (boost && boost.group) {
      if (seenGroup[boost.group]) continue;
      seenGroup[boost.group] = true;
    }
    keep.unshift(id);
  }
  if (keep.length !== selectedBoosts.length) {
    selectedBoosts = keep;
    localStorage.setItem("hl_selected_boosts", JSON.stringify(selectedBoosts));
  }
})();

(function dedupeExclusivePairs() {
  const keep = [];
  const dropped = new Set;
  for (const id of selectedBoosts) {
    if (dropped.has(id)) continue;
    const boost = BOOSTS.find(b => b.id === id);
    const exList = boost && boost.exclusiveWith ? Array.isArray(boost.exclusiveWith) ? boost.exclusiveWith : [ boost.exclusiveWith ] : [];
    if (exList.some(exId => keep.includes(exId))) {
      dropped.add(id);
      continue;
    }
    keep.push(id);
  }
  if (keep.length !== selectedBoosts.length) {
    selectedBoosts = keep;
    localStorage.setItem("hl_selected_boosts", JSON.stringify(selectedBoosts));
  }
})();

export let fertilizerTierScope = safeLSJSON(localStorage.getItem("hl_fert_tier_scope"), [ "Medium", "Advanced" ]);

export function isFertilizerTierEnabled(tier) {
  return fertilizerTierScope.includes(tier);
}

export function isSeasonLocked(boost) {
  if (!boost) return false;
  if (simWeatherMode && (boost.guardianSeason || SIM_WEATHER_BOOST_NAMES.has(boost.limitedBoostName))) return false;
  if (boost.seasons && boost.seasons.length) return !boost.seasons.includes(previewSeason);
  return !!(boost.season && boost.season !== previewSeason);
}

let __boostIdMap = null;

let __boostIdMapLen = -1;

function boostById(id) {
  if (!__boostIdMap || __boostIdMapLen !== BOOSTS.length) {
    __boostIdMap = new Map;
    for (let i = BOOSTS.length - 1; i >= 0; i--) __boostIdMap.set(BOOSTS[i].id, BOOSTS[i]);
    __boostIdMapLen = BOOSTS.length;
  }
  return __boostIdMap.get(id);
}

export function isBoostActive(id) {
  if (id === "gnome" && farmPanelGameState && !farmPanelGnomeComboPresent()) return false;
  if ((id === "power_hour" || id === "power_hour_greenhouse") && isPowerHourExpiredSinceSync()) return false;
  if (ALWAYS_ON_BOOST_IDS.has(id)) return true;
  if (id === "bee_swarm") return beeSwarmActiveCount > 0;
  if (!selectedSkills.includes(id) && !selectedBoosts.includes(id)) return false;
  const boost = boostById(id);
  if (boost && boost.source === "skill") {
    if (!selectedSkills.includes(id)) return false;
    if (isSeasonLocked(boost)) return false;
    return true;
  }
  if (!selectedBoosts.includes(id)) return false;
  if (isSeasonLocked(boost)) return false;
  return true;
}

export let boostDraftSelectedBoosts = selectedBoosts.slice();

export function isBoostDraftActive(id) {
  if (id === "gnome" && farmPanelGameState && !farmPanelGnomeComboPresent()) return false;
  if (ALWAYS_ON_BOOST_IDS.has(id)) return true;
  if (id === "bee_swarm") return beeSwarmActiveCount > 0;
  if (!selectedSkills.includes(id) && !boostDraftSelectedBoosts.includes(id)) return false;
  const boost = BOOSTS.find(b => b.id === id);
  if (boost && boost.source === "skill") {
    if (!selectedSkills.includes(id)) return false;
    if (isSeasonLocked(boost)) return false;
    return true;
  }
  if (!boostDraftSelectedBoosts.includes(id)) return false;
  if (isSeasonLocked(boost)) return false;
  return true;
}

function resetBoostDraftFromSaved() {
  boostDraftSelectedBoosts = selectedBoosts.slice();
  if (typeof renderBoostPanel === "function") renderBoostPanel();
  updateBoostSaveBarState();
}

export function isBoostDraftDirty() {
  const a = selectedBoosts.slice().sort();
  const b = boostDraftSelectedBoosts.slice().sort();
  return JSON.stringify(a) !== JSON.stringify(b);
}

export function updateBoostSaveBarState() {
  updateSkillSaveBarState();
}

function commitBoostDraft() {
  commitSkillDraft();
}

const SEASON_GUARDIAN_IDS = {
  Spring: "spring_guardian",
  Summer: "summer_guardian",
  Autumn: "autumn_guardian",
  Winter: "winter_guardian"
};

function isSeasonGuardianActive() {
  const id = SEASON_GUARDIAN_IDS[previewSeason];
  return !!id && isBoostActive(id);
}

function isSimWeatherBoost(b) {
  return !!b && SIM_WEATHER_BOOST_NAMES.has(b.limitedBoostName);
}

function simWeatherEligibleSeasons(b, itemName, kind) {
  const itemSeasons = kind === "fruit" ? getFruitSeasons(itemName) : kind === "crop" ? getCropSeasons(itemName) : SEASON_ORDER;
  return (b.seasons || []).filter(s => itemSeasons.includes(s));
}

export function weatherBoostAppliesToItem(b, itemName, kind) {
  if (!simWeatherMode || !isSimWeatherBoost(b)) return true;
  return simWeatherEligibleSeasons(b, itemName, kind).length > 0;
}

function weatherGuardianDoubles(b, ctx) {
  if (!simWeatherMode) return isSeasonGuardianActive();
  if (!ctx || !isSimWeatherBoost(b)) return false;
  return simWeatherEligibleSeasons(b, ctx.name, ctx.kind).some(s => isBoostActive(SEASON_GUARDIAN_IDS[s]));
}

export function getActiveSeasonGuardianName() {
  const id = SEASON_GUARDIAN_IDS[currentSeason];
  return id && isBoostActive(id) ? id : null;
}

export function getCropPlotSunshowerSpeedMultiplier() {
  if (!isBoostActive("sunshower")) return 1;
  return getActiveSeasonGuardianName() ? 4 : 2;
}

export function getActiveBoostsForCrop(cropName) {
  const base = BASE_CROPS[cropName];
  const tier = base ? base.tier : null;
  return BOOSTS.filter(b => (b.category || "crops") === "crops" && isBoostActive(b.id) && (b.scope === "global" && (!b.composterFertilizer || isFertilizerTierEnabled(tier)) || b.scope === "skillGlobal" || b.scope === "tier" && b.target === tier || b.scope === "tierEffects" || b.scope === "crop" && (b.target || "").toLowerCase() === (cropName || "").toLowerCase())).filter(b => b.id !== "hoot" || isOvernightGroundCrop(cropName)).filter(b => b.id !== "blossom_ward" || currentSeason === "Spring" && isCropInSeason(cropName, "Spring")).filter(b => b.id !== "frozen_heart" || currentSeason === "Winter" && isCropInSeason(cropName, "Winter")).filter(b => b.id !== "solflare_aegis" || isCropInSeason(cropName, "Summer")).filter(b => b.id !== "autumns_embrace" || isCropInSeason(cropName, "Autumn")).filter(b => weatherBoostAppliesToItem(b, cropName, "crop"));
}

function getFertilizerPotencyMult(fertName) {
  let mult = 1;
  BOOSTS.forEach(b => {
    if (b.category !== "composter" || !b.fertPotencyMult || !isBoostActive(b.id)) return;
    const applies = Array.isArray(b.appliesFertilizer) ? b.appliesFertilizer : [ b.appliesFertilizer ];
    if (applies.includes(fertName)) mult *= b.fertPotencyMult;
  });
  return mult;
}

export function getBeeSwarmPerSwarmYield() {
  let perSwarm = .2;
  const beeSwarmBoost = BOOSTS.find(x => x.id === "bee_swarm");
  if (beeSwarmBoost && beeSwarmBoost.yieldAdd) perSwarm = beeSwarmBoost.yieldAdd;
  if (isSkillActive("skill_pollen_power_up")) {
    const pollenSkill = BOOSTS.find(x => x.id === "skill_pollen_power_up");
    perSwarm += pollenSkill && pollenSkill.beeSwarmPerSwarmAdd || 0;
  }
  return perSwarm;
}

export function getEffectiveYieldAdd(b, tier, cropName, ctx) {
  let add = b.resourceEffects ? b.resourceEffects[cropName] || 0 : b.yieldAdd || 0;
  if (b.beeSwarmStack) {
    const stats = getBeeSwarmStatsForCrop(cropName);
    const plots = stats.affectedPlots || 0;
    if (plots <= 0) return 0;
    return getBeeSwarmPerSwarmYield() * ((stats.totalCount || 0) / plots);
  }
  if (b.tierEffects) {
    add = tier && b.tierEffects[tier] != null ? b.tierEffects[tier] : 0;
  }
  if (b.comboWith && isBoostActive(b.comboWith)) {
    add = b.comboYieldAdd != null ? b.comboYieldAdd : add;
  }
  if (b.composterFertilizer && b.fertilizer) {
    add *= getFertilizerPotencyMult(b.fertilizer);
  }
  if (b.limitedBoostName === "Bountiful Harvest" && weatherGuardianDoubles(b, ctx || {
    name: cropName,
    kind: "crop"
  })) {
    add *= 2;
  }
  return add;
}

export function boostAffectsYieldOrTime(b, itemName) {
  if (!b) return false;
  const itemTier = (BASE_CROPS[itemName] || {}).tier;
  if (getEffectiveYieldAdd(b, itemTier, itemName)) return true;
  if (b.yieldAddAll) return true;
  if (b.yieldMult) return true;
  if (b.yieldMultAll) return true;
  if (b.harvestAdd) return true;
  if (b.flowerExtraChance) return true;
  if (b.flowerExtraFlat) return true;
  if (b.timeMult) return true;
  if (b.timeMultAll) return true;
  if (b.flowerTimeMult) return true;
  return false;
}

function computeBoostedCropStatsUncached(cropName, baseYield, baseTimeSec, plotCountOverride, windowSec, includeBeeSwarm) {
  windowSec = windowSec || 86400;
  const active = getActiveBoostsForCrop(cropName).filter(b => includeBeeSwarm || !b.beeSwarmStack && !b.debuffStack);
  const cropTier = (BASE_CROPS[cropName] || {}).tier;
  let addSum = 0;
  let multBonusSum = 0;
  let globalTimeMult = 1;
  let debuffLossFraction = 0;
  const aoeTimeBoosts = [];
  const limitedTimeFactors = [];
  const totalPlots = plotCountOverride != null ? plotCountOverride : getPlotCount(cropName);
  const haveSyncData = hasLimitedBoostSyncData();
  const budAddSum = {};
  active.forEach(b => {
    const coverageFraction = getBoostCoverageFraction(b, windowSec, haveSyncData);
    if (b.debuffLossMult && !(b.isDebuff && isSeasonGuardianActive())) {
      const exactCropDestruction = b.calendarKey && b.calendarKey !== "insectPlague" && weatherDestructionSync.activeEvent === b.calendarKey ? weatherDestructionSync.byCrop[cropName] : null;
      if (!exactCropDestruction) {
        debuffLossFraction = Math.max(debuffLossFraction, b.debuffLossMult * coverageFraction);
      }
    }
    const add = getEffectiveYieldAdd(b, cropTier, cropName);
    const budKey = b.isBud && b.budId ? b.budId : null;
    if (add) {
      if (b.plotCap) {
        const fraction = totalPlots > 0 ? Math.min(totalPlots, b.plotCap) / totalPlots : 0;
        const contribution = add * fraction * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
      } else {
        const contribution = add * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
      }
    }
    if (b.yieldMult) multBonusSum += (b.yieldMult - 1) * coverageFraction;
    if (b.timeMult) {
      const effectiveTimeMult = b.limitedBoostName === "Sunshower" && weatherGuardianDoubles(b, {
        name: cropName,
        kind: "crop"
      }) ? b.timeMult * .5 : b.timeMult;
      if (b.plotCap) {
        aoeTimeBoosts.push(b);
      } else if (b.limitedBoostName && haveSyncData && getLimitedBoostRemainingSec(b.limitedBoostName) > 0) {
        limitedTimeFactors.push({
          timeMult: effectiveTimeMult,
          remainingSec: getLimitedBoostRemainingSec(b.limitedBoostName)
        });
      } else {
        globalTimeMult *= effectiveTimeMult;
      }
    }
  });
  const budAddValues = Object.values(budAddSum);
  if (budAddValues.length) addSum += Math.max(...budAddValues);
  const totalBonusFraction = addSum / baseYield + multBonusSum;
  const yieldVal = baseYield * (1 + totalBonusFraction) * (1 - Math.min(1, debuffLossFraction));
  const cyclesForFactor = extraMult => {
    const normalTimeVal = Math.max(1, baseTimeSec * globalTimeMult * extraMult);
    if (aoeTimeBoosts.length && totalPlots > 0) {
      const boostedPlots = Math.min(totalPlots, Math.min(...aoeTimeBoosts.map(b => b.plotCap)));
      const boostedTimeMult = aoeTimeBoosts.reduce((m, b) => m * b.timeMult, 1);
      const boostedTimeVal = Math.max(1, normalTimeVal * boostedTimeMult);
      const normalPlots = totalPlots - boostedPlots;
      return (boostedPlots * (86400 / boostedTimeVal) + normalPlots * (86400 / normalTimeVal)) / totalPlots;
    }
    return 86400 / normalTimeVal;
  };
  const blendedCyclesPerDay = blendCyclesPerDayForExpiry(cyclesForFactor, limitedTimeFactors, windowSec);
  const timeVal = blendedCyclesPerDay > 0 ? 86400 / blendedCyclesPerDay : Math.max(1, baseTimeSec * globalTimeMult);
  return {
    yieldVal: Math.max(1e-4, yieldVal),
    timeVal: Math.max(1, timeVal),
    activeBoosts: active
  };
}

export function formatDuration(sec) {
  sec = Math.round(sec);
  const d = Math.floor(sec / 86400);
  sec -= d * 86400;
  const h = Math.floor(sec / 3600);
  sec -= h * 3600;
  const m = Math.floor(sec / 60);
  sec -= m * 60;
  const s = sec;
  let out = "";
  if (d) out += d + "d ";
  if (h) out += h + "h ";
  if (m) out += m + "m ";
  if (s || !d && !h && !m) out += s + "s ";
  return out.trim() || "0s";
}

function isAoeManuallyUpgraded(b) {
  return !!b._ascensionAoeApplied;
}

export function getBoostAoeInfo(b, itemName) {
  if (!b.plotCap) return null;
  if (b.category === "crops") {
    const totalNodes = getPlotCount();
    const manualAoeUpgrade = AOE_SYNCED_CROW_IDS.includes(b.id) && isAoeManuallyUpgraded(b);
    if (AOE_SYNCED_CROW_IDS.includes(b.id) && aoeSyncOverrides[b.id] != null && !manualAoeUpgrade) {
      const synced = Math.min(b.plotCap, aoeSyncOverrides[b.id]);
      return {
        totalNodes: totalNodes,
        affectedNodes: Math.min(totalNodes, synced),
        perTier: null,
        resourceName: null,
        isSyncedOverride: true
      };
    }
    return {
      totalNodes: totalNodes,
      affectedNodes: Math.min(totalNodes, b.plotCap),
      perTier: null,
      resourceName: null,
      isManualAoeOverride: manualAoeUpgrade
    };
  }
  if (b.category === "resources") {
    const resourceName = b.scope === "resource" ? b.target : itemName;
    if (!resourceName) return {
      totalNodes: 0,
      affectedNodes: 0,
      perTier: null,
      resourceName: null
    };
    const basis = getAoeNodeBasis(b, resourceName);
    return Object.assign({
      resourceName: resourceName
    }, basis);
  }
  if (b.category === "fruits") {
    const totalNodes = getFruitCount(b.scope === "fruit" ? b.target : itemName);
    return {
      totalNodes: totalNodes,
      affectedNodes: Math.min(totalNodes, b.plotCap),
      perTier: null,
      resourceName: null
    };
  }
  if (b.category === "greenhouse") {
    const totalNodes = getGreenhouseCount(b.scope === "greenhouse" ? b.target : itemName);
    return {
      totalNodes: totalNodes,
      affectedNodes: Math.min(totalNodes, b.plotCap),
      perTier: null,
      resourceName: null
    };
  }
  return null;
}

export function describeAoeTierAllocation(resourceName, perTier) {
  if (!perTier) return "";
  const tiers = RESOURCE_NODE_TIERS[resourceName] || [];
  const parts = [];
  for (let i = tiers.length - 1; i >= 0; i--) {
    const tier = tiers[i];
    const a = perTier[tier.key];
    if (a && a.affectedNodes > 0) parts.push(`${fmt(a.affectedNodes)} ${tier.label}`);
  }
  return parts.join(" + ");
}

export function skillRankUsageHtml(s, rank) {
  const tier = s.skillTier || 1;
  const cost = ASCENSION_UPGRADE_COST[tier] || ASCENSION_UPGRADE_COST[1];
  const baseSkillPoints = tier;
  const steps = Math.max(0, rank - 1);
  const stepShards = steps > 0 ? cost.shards : 0;
  const stepPoints = steps > 0 ? cost.points : baseSkillPoints;
  const shardsUsed = cost.shards * steps;
  const pointsUsed = cost.points * steps + baseSkillPoints;
  const rankList = [];
  for (let r = 2; r <= rank; r++) rankList.push(r);
  const stepCaption = `USED FOR RANK ${rank}`;
  const totalCaption = rankList.length ? `USED FOR RANK 1 & ${rankList.join(" & ")}` : `USED FOR RANK ${rank}`;
  return `<div class="skill-rank-usage" data-skill-id="${s.id}">\n    <div class="skill-rank-usage-group-wrap">\n      <div class="skill-rank-usage-label-row">\n        <img class="skill-rank-usage-mini-icon" src="${IMAGE_ICONS["Ascension Shard"]}" alt="Ascension Shard">\n        <span class="skill-rank-usage-mini-badge">SP</span>\n        <span class="skill-rank-usage-caption">${stepCaption}</span>\n      </div>\n      <div class="skill-rank-usage-group">\n        <div class="skill-rank-usage-row"><img class="skill-rank-usage-icon" src="${IMAGE_ICONS["Ascension Shard"]}" alt="Ascension Shard"><span class="skill-rank-usage-val">${Math.round(stepShards)}</span></div>\n        <div class="skill-rank-usage-row"><span class="skill-rank-usage-label">SP</span><span class="skill-rank-usage-val">${Math.round(stepPoints)}</span></div>\n      </div>\n    </div>\n    <div class="skill-rank-usage-group-wrap skill-rank-usage-total">\n      <div class="skill-rank-usage-label-row">\n        <span class="skill-rank-usage-caption skill-rank-usage-caption-total">TOTAL</span>\n        <img class="skill-rank-usage-mini-icon" src="${IMAGE_ICONS["Ascension Shard"]}" alt="Ascension Shard">\n        <span class="skill-rank-usage-mini-badge">SP</span>\n        <span class="skill-rank-usage-caption">${totalCaption}</span>\n      </div>\n      <div class="skill-rank-usage-group">\n        <div class="skill-rank-usage-row"><img class="skill-rank-usage-icon" src="${IMAGE_ICONS["Ascension Shard"]}" alt="Ascension Shard"><span class="skill-rank-usage-val">${Math.round(shardsUsed)}</span></div>\n        <div class="skill-rank-usage-row"><span class="skill-rank-usage-label">SP</span><span class="skill-rank-usage-val">${Math.round(pointsUsed)}</span></div>\n      </div>\n    </div>\n  </div>`;
}

export function skillSyncedLevel(s) {
  const synced = syncedSkillLevels[s.id];
  if (Number.isFinite(synced)) return Math.min(Math.max(Math.round(synced), 1), 3);
  return 1;
}

export function skillSyncedBoostText(s, level) {
  const ascData = ASCENSION_RANK_DATA[s.id];
  if (ascData) return ascensionDescribeRank(s.id, level);
  return `Skill Level [${level}]`;
}

