export let toolRecipes;

{
  const existingToolData = localStorage.getItem("hl_tool_recipes");
  if (existingToolData) {
    toolRecipes = JSON.parse(existingToolData);
  } else {
    const rawLibrary = safeLSJSON(localStorage.getItem("hl_library"), []);
    const byOldId = {};
    rawLibrary.forEach(it => {
      byOldId[String(it.id)] = it;
    });
    function resolveOldProducedName(oldItem) {
      if (!oldItem) return null;
      if (oldItem.kind === "cropSeed") return oldItem.cropSeed && oldItem.cropSeed.producesName || oldItem.name;
      if (oldItem.kind === "fruitSeed") return oldItem.fruitSeed && oldItem.fruitSeed.producesName || oldItem.name;
      if (oldItem.kind === "tool") return oldItem.tool && oldItem.tool.producesName || oldItem.name;
      return oldItem.name;
    }
    toolRecipes = rawLibrary.filter(it => it.kind === "tool").map(it => {
      const t = it.tool || {};
      return {
        id: it.id,
        name: it.name,
        materials: (t.materials || []).map(m => ({
          name: m.name || resolveOldProducedName(byOldId[String(m.libId)]) || m.name || "",
          qty: m.qty || 0
        })),
        coinCost: t.coinCost || 0,
        producesName: t.producesName || it.name,
        producesQty: t.producesQty || 1,
        manualPrice: it.manualPrice != null ? it.manualPrice : null
      };
    });
  }
  TOOL_DEFAULTS.forEach(def => {
    const existing = toolRecipes.find(t => String(t.id) === String(def.id));
    if (existing) {
      existing.locked = true;
    } else {
      toolRecipes.push({
        ...def,
        materials: def.materials.map(m => ({
          ...m
        })),
        manualPrice: null,
        locked: true
      });
    }
  });
  localStorage.setItem("hl_tool_recipes", JSON.stringify(toolRecipes));
}

