(function migrateMarketToConstants() {
  const seen = new Set;
  const migrated = [];
  marketItems.forEach(m => {
    const nameLower = (m.name || "").toLowerCase();
    let id;
    if (m.isAutoAnimal) {
      id = m.id;
    } else {
      const cropKey = Object.keys(BASE_CROPS).find(k => k.toLowerCase() === nameLower);
      const fruitKey = Object.keys(BASE_FRUITS).find(k => k.toLowerCase() === nameLower);
      if (cropKey) id = "crop_" + cropKey; else if (fruitKey) id = "fruit_" + fruitKey; else if (m.sourceLibId != null && toolRecipes.some(t => String(t.id) === String(m.sourceLibId))) id = m.sourceLibId; else return;
    }
    if (seen.has(String(id))) return;
    seen.add(String(id));
    migrated.push({
      id: id,
      name: m.name,
      flowerPrice: m.flowerPrice || 0,
      isAutoAnimal: !!m.isAutoAnimal
    });
  });
  __set_marketItems(migrated);
  localStorage.setItem("hl_market", JSON.stringify(marketItems));
})();

