function formatRateText(raw) {
  const cleaned = String(raw).replace(/[^0-9.]/g, "");
  const dot = cleaned.indexOf(".");
  const intPart = (dot === -1 ? cleaned : cleaned.slice(0, dot)).replace(/^0+(?=\d)/, "");
  const decPart = dot === -1 ? null : cleaned.slice(dot + 1).replace(/\./g, "");
  const grouped = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return decPart === null ? grouped : `${grouped || "0"}.${decPart}`;
}

export function setRateInputValue(n) {
  const el = $("rateInput");
  if (!el) return;
  el.value = formatRateText(String(Math.round(n * 1e6) / 1e6));
}

$("rateInput").addEventListener("input", e => {
  const el = e.target;
  const caret = el.selectionStart;
  const digitsBefore = el.value.slice(0, caret == null ? el.value.length : caret).replace(/[^0-9.]/g, "").length;
  const text = formatRateText(el.value);
  if (text !== el.value) {
    el.value = text;
    let seen = 0;
    let pos = 0;
    while (pos < text.length && seen < digitsBefore) {
      if (/[0-9.]/.test(text[pos])) seen++;
      pos++;
    }
    try { el.setSelectionRange(pos, pos); } catch (err) {}
  }
  const v = parseFloat(el.value.replace(/,/g, ""));
  coinPerFlower = isNaN(v) || v <= 0 ? 1 : v;
  saveState();
  updateSettingsSummary();
  updateCalcSummary();
  renderLibraryLists();
  renderCropMachinePanel();
  if (typeof renderFarmPanelTabContent === "function") renderFarmPanelTabContent();
});

