export function farmSyncFindBagByNameHeuristic(root, nameRegex, maxDepth) {
  if (maxDepth == null) maxDepth = 3;
  const seen = new Set;
  const queue = [ {
    obj: root,
    depth: 0
  } ];
  while (queue.length) {
    const {obj: obj, depth: depth} = queue.shift();
    if (!obj || typeof obj !== "object" || seen.has(obj)) continue;
    seen.add(obj);
    const keys = Object.keys(obj);
    for (const key of keys) {
      if (nameRegex.test(key)) {
        const val = obj[key];
        if (val && typeof val === "object" && !Array.isArray(val)) return {
          path: key,
          value: val
        };
      }
    }
    if (depth < maxDepth) {
      for (const key of keys) {
        const val = obj[key];
        if (val && typeof val === "object" && !Array.isArray(val)) queue.push({
          obj: val,
          depth: depth + 1
        });
      }
    }
  }
  return null;
}

const ANIMAL_HOUSE_KEY = {
  chicken: "henHouse",
  sheep: "barn",
  cow: "barn"
};

export function farmSyncGetAnimalRecords(g, type) {
  const houseKey = ANIMAL_HOUSE_KEY[type];
  const house = farmPanelField(g, houseKey);
  if (!house || typeof house !== "object") return {};
  let bag = null;
  if (house.animals && typeof house.animals === "object" && !Array.isArray(house.animals)) {
    bag = house.animals;
  } else {
    const direct = house[type] || house[type + "s"] || house.livestock;
    if (direct && typeof direct === "object" && !Array.isArray(direct)) bag = direct; else {
      const found = farmSyncFindBagByNameHeuristic(house, /animal|livestock/i, 1);
      bag = found ? found.value : null;
    }
  }
  if (!bag || typeof bag !== "object") return {};
  if (houseKey === "henHouse") return bag;
  const wantType = type === "sheep" ? /sheep/i : /cow/i;
  const filtered = {};
  Object.entries(bag).forEach(([id, animal]) => {
    const t = animal && (animal.type || animal.animalType);
    if (typeof t === "string" && wantType.test(t)) filtered[id] = animal;
  });
  return filtered;
}

