export function getCurrentChapterName() {
  const now = Date.now();
  const hit = CHAPTER_DATE_RANGES.find(c => now >= c.start && now < c.end);
  if (hit) return hit.name;
  return CHAPTER_DATE_RANGES[CHAPTER_DATE_RANGES.length - 1].name;
}

export function getCurrentChapterMutantSet() {
  const chapter = getCurrentChapterName();
  return CHAPTER_MUTANTS[chapter] || null;
}

function sflStringToInteger(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = hash * 31 + str.charCodeAt(i) >>> 0;
  }
  return hash;
}

function sflPrng({farmId: farmId, itemId: itemId, counter: counter, criticalHitName: criticalHitName}) {
  const criticalHitNameHash = sflStringToInteger(criticalHitName);
  const seed = Math.imul(farmId, 2246822507) + Math.imul(itemId, 2654435769) + Math.imul(counter, 668265263) + Math.imul(criticalHitNameHash, 1367130551) >>> 0;
  let t = seed ^ seed >>> 16;
  t = Math.imul(t, 569420461);
  t = t ^ t >>> 15;
  t = Math.imul(t, 1935289751);
  t = t ^ t >>> 15;
  return (t >>> 0) / 2 ** 32;
}

export function sflPrngChance({farmId: farmId, itemId: itemId, counter: counter, chance: chance, criticalHitName: criticalHitName}) {
  return sflPrng({
    farmId: farmId,
    itemId: itemId,
    counter: counter,
    criticalHitName: criticalHitName
  }) * 100 < chance;
}

