export const GAMESTATE_SECTION_KEYS = [ "crops", "trees", "stones", "iron", "gold", "crimstones", "oilReserves", "lavaPits", "saltFarm", "sculptures", "stock", "flowers", "fruitPatches", "greenhouse", "henHouse", "barn", "buds", "bumpkin", "inventory", "collectibles", "home" ];

export let __gameStateSectionLenSigs = {};

export let __farmPanelSaveGameStateHandle = null;

function farmSyncNormalizeName(s) {
  return (s == null ? "" : String(s)).trim().toLowerCase();
}

function farmSyncFindIdByName(list, name) {
  if (!name || !Array.isArray(list)) return "none";
  const norm = farmSyncNormalizeName(name);
  const found = list.find(x => farmSyncNormalizeName(x.name) === norm);
  return found ? found.id : "none";
}

export function farmSyncExtractBudTraits(bud) {
  if (!bud || typeof bud !== "object") return null;
  let type = bud.type || bud.Type || null;
  let stem = bud.stem || bud.Stem || null;
  let aura = bud.aura || bud.Aura || null;
  const attrs = Array.isArray(bud.attributes) ? bud.attributes : Array.isArray(bud.traits) ? bud.traits : null;
  if (attrs) {
    attrs.forEach(a => {
      if (!a) return;
      const key = farmSyncNormalizeName(a.trait_type || a.type || a.key);
      const val = a.value != null ? a.value : a.val;
      if (val == null) return;
      if (key === "type" && !type) type = val; else if (key === "stem" && !stem) stem = val; else if (key === "aura" && !aura) aura = val;
    });
  }
  return {
    type: type,
    stem: stem,
    aura: aura
  };
}

const BUD_SYNC_CATEGORIES = [ {
  prefix: "bud_sync_",
  types: () => BUD_GREENHOUSE_TYPES,
  stems: () => BUD_GREENHOUSE_STEMS,
  build: buildBudBoostEntries,
  get: () => greenhouseBuds,
  set: v => {
    greenhouseBuds = v;
  },
  save: () => saveGreenhouseBuds()
}, {
  prefix: "abud_sync_",
  types: () => BUD_ANIMAL_TYPES,
  stems: () => BUD_ANIMAL_STEMS,
  build: buildAnimalBudBoostEntries,
  get: () => animalBuds,
  set: v => {
    animalBuds = v;
  },
  save: () => saveAnimalBuds()
}, {
  prefix: "fbud_sync_",
  types: () => BUD_FRUIT_TYPES,
  stems: () => BUD_FRUIT_STEMS,
  build: buildFruitBudBoostEntries,
  get: () => fruitBuds,
  set: v => {
    fruitBuds = v;
  },
  save: () => saveFruitBuds()
}, {
  prefix: "cbud_sync_",
  types: () => BUD_CROP_TYPES,
  stems: () => BUD_CROP_STEMS,
  build: buildCropBudBoostEntries,
  get: () => cropBuds,
  set: v => {
    cropBuds = v;
  },
  save: () => saveCropBuds()
}, {
  prefix: "rbud_sync_",
  types: () => BUD_RESOURCE_TYPES,
  stems: () => BUD_RESOURCE_STEMS,
  build: buildResourceBudBoostEntries,
  get: () => resourceBuds,
  set: v => {
    resourceBuds = v;
  },
  save: () => saveResourceBuds()
} ];

function clearManualBudsAndPets() {
  BUD_SYNC_CATEGORIES.forEach(cat => {
    const manualIds = [];
    const kept = [];
    cat.get().forEach(b => {
      if (b && typeof b.id === "string" && b.id.indexOf(cat.prefix) === 0) {
        kept.push(b);
      } else if (b) {
        manualIds.push(b.id);
      }
    });
    if (!manualIds.length) return;
    const removeSet = new Set(manualIds);
    const dropBoostIds = new Set;
    BOOSTS = BOOSTS.filter(x => {
      if (x.budId && removeSet.has(x.budId)) {
        dropBoostIds.add(x.id);
        return false;
      }
      return true;
    });
    if (dropBoostIds.size) selectedBoosts = selectedBoosts.filter(id => !dropBoostIds.has(id));
    cat.set(kept);
    cat.save();
  });
  if (typeof petsData !== "undefined" && Array.isArray(petsData)) {
    const keptPets = petsData.filter(p => p && typeof p.id === "string" && p.id.indexOf(PET_SYNC_PREFIX) === 0);
    if (keptPets.length !== petsData.length) {
      petsData = keptPets;
      savePetsData();
      if (typeof __petCardMemo !== "undefined") __petCardMemo.clear();
    }
  }
}

function syncBudsFromFarmData(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const budsBag = asObj(farmPanelField(g, "buds")) || {};
  const realBudIds = Object.keys(budsBag);
  const touched = {
    greenhouse: false,
    animal: false,
    fruit: false,
    crop: false,
    resource: false
  };
  const catKeyByPrefix = {
    bud_sync_: "greenhouse",
    abud_sync_: "animal",
    fbud_sync_: "fruit",
    cbud_sync_: "crop",
    rbud_sync_: "resource"
  };
  const budsSig = realBudIds.length + "|" + JSON.stringify(budsBag);
  if (budsSig === __lastBudsSig && __lastBudsResult) {
    return {
      matched: __lastBudsResult.matched,
      budCount: __lastBudsResult.budCount,
      touched: touched
    };
  }
  __lastBudsSig = budsSig;
  let matched = 0;
  const sameTraits = (a, b) => a.typeId === b.typeId && a.stemId === b.stemId && a.auraId === b.auraId;
  BUD_SYNC_CATEGORIES.forEach(cat => {
    const catKey = catKeyByPrefix[cat.prefix];
    const existingSynced = new Map;
    const keptManual = [];
    cat.get().forEach(b => {
      if (b && typeof b.id === "string" && b.id.indexOf(cat.prefix) === 0) {
        existingSynced.set(b.id, b);
      } else {
        keptManual.push(b);
      }
    });
    const freshEntries = new Map;
    realBudIds.forEach(realId => {
      const traits = farmSyncExtractBudTraits(budsBag[realId]);
      if (!traits) return;
      const typeId = farmSyncFindIdByName(cat.types(), traits.type);
      const stemId = farmSyncFindIdByName(cat.stems(), traits.stem);
      const auraId = farmSyncFindIdByName(BUD_AURAS, traits.aura);
      if (typeId === "none" && stemId === "none") return;
      const budUID = cat.prefix + realId;
      freshEntries.set(budUID, {
        id: budUID,
        typeId: typeId,
        stemId: stemId,
        auraId: auraId,
        synced: true
      });
    });
    matched += freshEntries.size;
    const toRemove = [];
    existingSynced.forEach((old, id) => {
      const fresh = freshEntries.get(id);
      if (!fresh || !sameTraits(old, fresh)) toRemove.push(id);
    });
    const toAdd = [];
    freshEntries.forEach((fresh, id) => {
      const old = existingSynced.get(id);
      if (!old || !sameTraits(old, fresh)) toAdd.push(fresh);
    });
    if (!toRemove.length && !toAdd.length) return;
    touched[catKey] = true;
    if (toRemove.length) {
      const removeSet = new Set(toRemove);
      const dropBoostIds = new Set;
      BOOSTS = BOOSTS.filter(x => {
        if (x.budId && removeSet.has(x.budId)) {
          dropBoostIds.add(x.id);
          return false;
        }
        return true;
      });
      if (dropBoostIds.size) {
        selectedBoosts = selectedBoosts.filter(id => !dropBoostIds.has(id));
      }
      toRemove.forEach(id => existingSynced.delete(id));
    }
    toAdd.forEach(fresh => {
      const entries = cat.build(fresh.id, fresh.typeId, fresh.stemId, fresh.auraId);
      if (!entries.length) return;
      existingSynced.set(fresh.id, fresh);
      entries.forEach(e => {
        BOOSTS.push(e);
        if (!selectedBoosts.includes(e.id)) selectedBoosts.push(e.id);
      });
    });
    cat.set(keptManual.concat(Array.from(existingSynced.values())));
    cat.save();
  });
  if (matched || realBudIds.length) saveBoostState();
  __lastBudsResult = {
    matched: matched,
    budCount: realBudIds.length
  };
  __saveSyncSigs();
  return {
    matched: matched,
    budCount: realBudIds.length,
    touched: touched
  };
}

const FERTILIZER_SYNC_MAP = {
  "sprout mix": "apply_sprout_mix",
  "rapid root": "apply_rapid_root",
  "sproutroot surprise": "apply_sproutroot_surprise",
  "fruitful blend": "apply_fruitful_blend",
  "turbofruit mix": "apply_turbofruit_mix"
};

function farmSyncExtractFertName(v) {
  if (!v) return null;
  if (typeof v === "string") return v;
  if (typeof v === "object") {
    if (typeof v.name === "string") return v.name;
    if (typeof v.type === "string") return v.type;
  }
  return null;
}

function farmSyncGetPlotFertName(plot, subKey) {
  if (!plot || typeof plot !== "object") return null;
  const job = plot[subKey];
  const candidates = [ job && job.fertiliser, job && job.fertilizer, plot.fertiliser, plot.fertilizer ];
  for (const c of candidates) {
    const name = farmSyncExtractFertName(c);
    if (name) return name;
  }
  return null;
}

function syncFertilizersFromFarmData(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const foundIds = new Set;
  const scanBag = (bag, subKey) => {
    const obj = asObj(bag);
    if (!obj) return;
    Object.values(obj).forEach(plot => {
      const fertName = farmSyncGetPlotFertName(plot, subKey);
      if (!fertName) return;
      const boostId = FERTILIZER_SYNC_MAP[farmSyncNormalizeName(fertName)];
      if (boostId) foundIds.add(boostId);
    });
  };
  scanBag(farmPanelField(g, "crops"), "crop");
  scanBag(farmPanelField(g, "fruitPatches"), "fruit");
  let matched = 0;
  foundIds.forEach(id => {
    const boost = BOOSTS.find(b => b.id === id);
    if (!boost) return;
    if (selectedBoosts.includes(id)) {
      matched++;
      return;
    }
    if (boost.exclusiveWith) {
      const exList = Array.isArray(boost.exclusiveWith) ? boost.exclusiveWith : [ boost.exclusiveWith ];
      selectedBoosts = selectedBoosts.filter(x => !exList.includes(x));
    }
    selectedBoosts.push(id);
    matched++;
  });
  if (matched) saveBoostState();
  return {
    matched: matched
  };
}

function farmSyncFindConsumableName(obj, targets, depth, seen) {
  if (!obj || typeof obj !== "object" || depth > 3) return null;
  if (seen.has(obj)) return null;
  seen.add(obj);
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (typeof v === "string") {
      const norm = farmSyncNormalizeName(v);
      if (targets.includes(norm)) return v;
    } else if (v && typeof v === "object") {
      const nameField = typeof v.name === "string" ? v.name : typeof v.type === "string" ? v.type : null;
      if (nameField && targets.includes(farmSyncNormalizeName(nameField))) return nameField;
      const found = farmSyncFindConsumableName(v, targets, depth + 1, seen);
      if (found) return found;
    }
  }
  return null;
}

const SPICE_SYNC_ANIMAL_BAGS = {
  chicken: "chickens",
  sheep: "sheep",
  cow: "cows"
};

const SPICE_SYNC_TARGETS = [ "salt lick", "honey treat" ];

function syncSpiceFromFarmData(g, gFallback) {
  let matched = 0;
  let touched = false;
  SPICE_ANIMAL_TYPES.forEach(type => {
    let bag = farmSyncGetAnimalRecords(g, type);
    const bagHasAnyFeedBuff = Object.values(bag || {}).some(a => a && typeof a === "object" && a.feedBuff && a.feedBuff.name);
    if (!bagHasAnyFeedBuff && gFallback) {
      const fallbackBag = farmSyncGetAnimalRecords(gFallback, type);
      const fallbackHasAnyFeedBuff = Object.values(fallbackBag || {}).some(a => a && typeof a === "object" && a.feedBuff && a.feedBuff.name);
      if (fallbackHasAnyFeedBuff || (!bag || !Object.keys(bag).length)) bag = fallbackBag;
    }
    let hasSaltLick = false;
    let hasHoneyTreat = false;
    Object.values(bag || {}).forEach(animal => {
      if (!animal || typeof animal !== "object") return;
      const buff = animal.feedBuff;
      if (!buff || typeof buff !== "object" || !buff.name) return;
      const stillActive = typeof buff.harvestsRemaining !== "number" || buff.harvestsRemaining > 0;
      if (!stillActive) return;
      if (buff.name === "Salt Lick") {
        hasSaltLick = true;
        matched++;
      } else if (buff.name === "Honey Treat") {
        hasHoneyTreat = true;
        matched++;
      }
    });
    if (hasSaltLick !== !!spiceUsage.saltLick[type]) {
      spiceUsage.saltLick[type] = hasSaltLick;
      touched = true;
    }
    if (hasSaltLick && !spiceUsage.saltLick.active) {
      spiceUsage.saltLick.active = true;
      touched = true;
    }
    if (hasHoneyTreat !== !!spiceUsage.honeyTreat[type]) {
      spiceUsage.honeyTreat[type] = hasHoneyTreat;
      touched = true;
    }
    if (hasHoneyTreat && !spiceUsage.honeyTreat.active) {
      spiceUsage.honeyTreat.active = true;
      touched = true;
    }
    if (hasSaltLick && spiceUsage.honeyTreat[type]) {
      spiceUsage.honeyTreat[type] = false;
      touched = true;
    }
  });
  if (touched) saveSpiceUsage();
  return {
    matched: matched
  };
}

const CROW_AOE_DEFS = {
  basic_scarecrow: {
    collectibleName: "Basic Scarecrow",
    tier: "Basic",
    skillName: "Chonky Scarecrow"
  },
  scary_mike: {
    collectibleName: "Scary Mike",
    tier: "Medium",
    skillName: "Horror Mike"
  },
  laurie_chuckle_crow: {
    collectibleName: "Laurie the Chuckle Crow",
    tier: "Advanced",
    skillName: "Laurie's Gains"
  }
};

export function farmSyncGetCoords(obj) {
  if (!obj || typeof obj !== "object") return null;
  const c = obj.coordinates && typeof obj.coordinates === "object" ? obj.coordinates : obj;
  const x = typeof c.x === "number" ? c.x : typeof c.x === "string" && c.x.trim() !== "" ? parseFloat(c.x) : NaN;
  const y = typeof c.y === "number" ? c.y : typeof c.y === "string" && c.y.trim() !== "" ? parseFloat(c.y) : NaN;
  if (isNaN(x) || isNaN(y)) return null;
  return {
    x: x,
    y: y
  };
}

function syncCrowAoeOverrides(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const mainCollectibles = asObj(farmPanelField(g, "collectibles")) || {};
  const home = asObj(g && g.home);
  const homeCollectibles = farmSyncGetInteriorCollectiblesMerged(g);
  const cropsBag = asObj(farmPanelField(g, "crops")) || {};
  const skills = asObj(g && g.bumpkin && g.bumpkin.skills) || {};
  const hasSkill = name => Object.keys(skills).some(sn => sn.trim().toLowerCase() === name.trim().toLowerCase());
  let anyChange = false;
  Object.entries(CROW_AOE_DEFS).forEach(([boostId, def]) => {
    const a = mainCollectibles[def.collectibleName];
    const b = homeCollectibles[def.collectibleName];
    const instances = farmSyncPickActivePlacedInstances([ ...Array.isArray(a) ? a : [], ...Array.isArray(b) ? b : [] ]);
    if (!instances.length) {
      if (aoeSyncOverrides[boostId] !== undefined) {
        delete aoeSyncOverrides[boostId];
        anyChange = true;
      }
      return;
    }
    const crowCoords = instances.map(farmSyncGetCoords).filter(Boolean);
    if (!crowCoords.length) return;
    const radius = hasSkill(def.skillName) ? 3 : 1;
    const size = radius * 2 + 1;
    const {destroyedIds: destroyedIds} = computeDestroyedCropPlotIds(g);
    let count = 0;
    Object.entries(cropsBag).forEach(([plotId, plot]) => {
      if (!plot || typeof plot !== "object") return;
      if (destroyedIds.has(plotId)) return;
      const cropName = plot.crop && plot.crop.name;
      if (!cropName) return;
      const cropDef = BASE_CROPS[cropName];
      if (!cropDef || cropDef.tier !== def.tier) return;
      const plotCoords = farmSyncGetCoords(plot);
      if (!plotCoords) return;
      const inRange = crowCoords.some(c => {
        const dx = plotCoords.x - c.x;
        const dy = plotCoords.y - c.y;
        return Math.abs(dx) <= radius && dy <= -1 && dy >= -size;
      });
      if (inRange) count++;
    });
    if (aoeSyncOverrides[boostId] !== count) {
      aoeSyncOverrides[boostId] = count;
      anyChange = true;
    }
  });
  if (anyChange) saveAoeSyncOverrides();
  return {
    changed: anyChange
  };
}

export let __lastSyncTiming = null;

let __syncMark = null;

export function __markSub(label) {
  if (typeof __syncMark === "function") __syncMark(label);
}

export let __syncTimingPanelOpen = false;

async function performFarmPanelSync(farmId) {
  if (farmPanelSyncInFlight) return null;
  __set_farmPanelSyncInFlight(true);
  const btn = $("farmPanelSyncBtn");
  const originalLabel = btn.textContent;
  btn.textContent = "…";
  $("farmPanelStatus").textContent = "Syncing…";
  const __t0 = performance.now();
  const __marks = [];
  const __mark = label => __marks.push({
    label: label,
    at: performance.now() - __t0
  });
  let __syncErrorMsg = null;
  try {
    __mark("sync start");
    const communityData = await fetchCommunityFarmData(farmId);
    const json = communityData;
    const communityResult = {
      ok: true,
      data: communityData
    };
    const apiUsername = farmSyncGetUsernameFromState(communityData);
    __mark("network fetch done");
    __syncMark = __mark;
    const prevSelectedBoostsSig = JSON.stringify(selectedBoosts);
    const prevSelectedSkillsSig = JSON.stringify(selectedSkills);
    const prevFeePercent = feePercent;
    const boostSourceState = communityResult.ok ? communityResult.data : json;
    const mergedFreshState = farmPanelMergeAuthoritativeResourceData(json, boostSourceState, communityResult.ok);
    const result = applyFarmSkillsOnly(boostSourceState, json);
    __mark("  applyFarmSkillsOnly");
    const boostResult = applyFarmBoostsOnly(mergedFreshState);
    __mark("  applyFarmBoostsOnly");
    const affectionToolsResult = applyFarmAnimalAffectionToolsOnly(boostSourceState);
    __mark("  applyFarmAnimalAffectionToolsOnly");
    const greenThumbLegacyResult = applyFarmGreenThumbLegacyOnly(boostSourceState);
    __mark("  applyFarmGreenThumbLegacyOnly");
    const plotsResult = applyFarmPlotsNodesOnly(boostSourceState, communityResult.ok);
    __mark("  applyFarmPlotsNodesOnly");
    const feeResult = applyFarmFeeOnly(boostSourceState);
    __mark("  applyFarmFeeOnly");
    let budResult = {
      matched: 0,
      budCount: 0
    };
    let fertResult = {
      matched: 0
    };
    let spiceResult = {
      matched: 0
    };
    let crowAoeResult = {
      changed: false
    };
    let petSyncResult = {
      matched: 0,
      petCount: 0,
      changed: false
    };
    let touchGreenhouse = false, touchAnimals = false, touchFruits = false, touchCrops = false, touchResource = false;
    if (communityResult.ok) {
      const gExtra = farmSyncExtractGameState(boostSourceState);
      const gOfficialFallback = boostSourceState === json ? null : farmSyncExtractGameState(json);
      clearManualBudsAndPets();
      budResult = syncBudsFromFarmData(gExtra);
      fertResult = syncFertilizersFromFarmData(gExtra);
      spiceResult = syncSpiceFromFarmData(gExtra, gOfficialFallback);
      crowAoeResult = syncCrowAoeOverrides(gExtra);
      syncWeatherDestructionFromFarmData(gExtra);
      if (typeof syncPetsFromFarmData === "function") petSyncResult = syncPetsFromFarmData(gExtra);
      __mark("buds/fert/spice/crow/weather sync done");
      if (budResult.matched || fertResult.matched || spiceResult.matched || crowAoeResult.changed) {
        const budTouched = budResult.touched || {};
        touchGreenhouse = budTouched.greenhouse;
        touchAnimals = budTouched.animal || spiceResult.matched || affectionToolsResult.changed;
        touchFruits = budTouched.fruit || fertResult.matched;
        touchCrops = budTouched.crop || fertResult.matched || crowAoeResult.changed;
        touchResource = budTouched.resource;
      }
    }
    if (affectionToolsResult.changed) touchAnimals = true;
    const budFertSpiceCrowMatched = !!(budResult.matched || fertResult.matched || spiceResult.matched || crowAoeResult.changed);
    const anythingChanged = JSON.stringify(selectedBoosts) !== prevSelectedBoostsSig || JSON.stringify(selectedSkills) !== prevSelectedSkillsSig || feePercent !== prevFeePercent || plotsResult.touched || !!budResult.matched || !!fertResult.matched || !!spiceResult.matched || !!crowAoeResult.changed;
    farmPanelSaveGameState(mergedFreshState, true);
    if (typeof invalidateCostCache === "function") invalidateCostCache();
    if (typeof syncCookingCountsFromInventory === "function") syncCookingCountsFromInventory(farmPanelGameState);
    __mark("  state prep");
    const boostsChanged = !!boostResult.changed;
    const plotsTouched = !!plotsResult.touched;
    const feeChanged = !!feeResult.changed;
    const libraryListsWillRender = boostsChanged || plotsTouched || feeChanged || budFertSpiceCrowMatched;
    if (boostsChanged || plotsTouched || budFertSpiceCrowMatched) {
      if (typeof renderBoostPanel === "function") renderBoostPanel();
    }
    __mark("  renderBoostPanel");
    if (libraryListsWillRender) {
      if (typeof renderLibraryLists === "function") renderLibraryLists();
    }
    __mark("  renderLibraryLists");
    if (plotsTouched) {
      if (typeof renderPlotNodeInputs === "function") renderPlotNodeInputs();
    }
    __mark("  renderPlotNodeInputs");
    if (plotsTouched) {
      if (typeof renderHoneyList === "function") renderHoneyList();
    }
    __mark("  renderHoneyList");
    if (!libraryListsWillRender && (plotsTouched || touchGreenhouse || feeChanged)) {
      if (typeof renderGreenhouseList === "function") renderGreenhouseList();
    }
    __mark("  renderGreenhouseList");
    if (plotsTouched || touchAnimals) {
      if (typeof renderAnimalsList === "function") renderAnimalsList();
      if (typeof refreshAnimalAffectionToolToggleUI === "function") refreshAnimalAffectionToolToggleUI();
    }
    __mark("  renderAnimalsList");
    if (!libraryListsWillRender && (plotsTouched || touchFruits || feeChanged)) {
      if (typeof renderFruitsList === "function") renderFruitsList();
    }
    __mark("  renderFruitsList");
    if (!libraryListsWillRender && (touchCrops || feeChanged)) {
      if (typeof renderCropsList === "function") renderCropsList();
    }
    __mark("  renderCropsList");
    if (plotsTouched || touchResource || feeChanged) {
      if (typeof renderResourceList === "function") renderResourceList();
    }
    __mark("  renderResourceList");
    if (boostsChanged || feeChanged || budFertSpiceCrowMatched) {
      if (typeof renderCropMachinePanel === "function") renderCropMachinePanel();
    }
    __mark("  renderCropMachinePanel");
    if (petSyncResult.changed && $("petProfitList")) {
      if (typeof renderPetsPanel === "function") renderPetsPanel();
    }
    __mark("  renderPetsPanel");
    __mark("render cascade done");
    if (anythingChanged) {
      if (typeof renderSaltList === "function") renderSaltList();
    }
    __mark("  renderSaltList");
    if (typeof updateCalcSummary === "function") updateCalcSummary();
    __mark("salt list + calc summary done");
    const factionInfo = farmSyncGetFactionPetInfo(farmSyncExtractGameState(boostSourceState));
    farmSyncSetApiUsername(farmId, apiUsername);
    farmPanelSaveLastInfo(farmId, result.level, boostResult.vipStatus, factionInfo, result.experience, result.ascensionLevel);
    if (boostResult.vipStatus) {
      localStorage.setItem("hl_ticket_vip_enabled", boostResult.vipStatus.active ? "1" : "0");
      if (typeof refreshTicketCalcVipFromSync === "function") refreshTicketCalcVipFromSync();
    }
    if (!anythingChanged) {
      if (typeof renderCookingPanel === "function") renderCookingPanel();
    }
    __mark("cooking render done");
    if (typeof renderBoostPanel === "function" && typeof boostCategory !== "undefined" && boostCategory === "limitedtime") renderBoostPanel();
    gunterMutantSyncAutoBoosts();
    if ($("chapterFishMutantsOverlay") && $("chapterFishMutantsOverlay").classList.contains("show")) renderChapterFishMutants();
    if ($("factionPanel") && $("factionPanel").classList.contains("open") && typeof renderFactionDeliveryPanel === "function") renderFactionDeliveryPanel();
    if ($("craftingBoxPanel") && $("craftingBoxPanel").classList.contains("open") && typeof renderCraftingBoxPanel === "function") renderCraftingBoxPanel();
    if ($("workbenchPanel") && $("workbenchPanel").classList.contains("open") && typeof renderWorkbenchPanel === "function") renderWorkbenchPanel();
    syncBeginnerPanel();
    renderFarmPanelInfo();
    renderFarmPanelTabContent();
    __mark("info panel + tab content done");
    if ($("mapPanel") && $("mapPanel").classList.contains("open")) renderMapPanel();
    if (typeof profileCaptureSyncSnapshot === "function") profileCaptureSyncSnapshot(farmId);
    __syncMark = null;
    const nameNote = apiUsername ? ` · 👤 ${apiUsername}` : "";
    const dataNote = communityResult.ok ? " · 📦 full data synced" : ` · ⚠️ full sync failed (${communityResult.error})`;
    const boostNote = boostResult.matched ? ` · ⚡ ${boostResult.matched} boost(s) auto-applied` : "";
    const plotsNote = plotsResult.touched ? " · 🌾 plots/nodes auto-filled" : "";
    const budNote = budResult.matched ? ` · 🌱 ${budResult.matched} BUD boost(s) auto-applied` : "";
    const fertNote = fertResult.matched ? ` · 🧪 ${fertResult.matched} fertiliser boost(s) auto-applied` : "";
    const spiceNote = spiceResult.matched ? ` · 🧂 ${spiceResult.matched} spice rack boost(s) auto-applied` : "";
    const feeNote = feeResult.applied ? ` · 💰 sell fee set to ${feeResult.feePercent}%` : "";
    const crowNote = crowAoeResult.changed ? " · 🐦 crow AoE plot counts auto-detected" : "";
    const petNote = petSyncResult.matched ? ` · 🐾 ${petSyncResult.matched} pet(s) auto-synced to Pet House` : "";
    return {
      ok: true,
      message: `✅ Synced Farm #${farmId} · 🎓 ${result.matched} skill(s) matched${boostNote}${plotsNote}${budNote}${fertNote}${spiceNote}${feeNote}${crowNote}${petNote}${nameNote}${dataNote}`
    };
  } catch (e) {
    console.error("Farm panel sync failed:", e);
    __syncErrorMsg = e.message;
    $("farmPanelStatus").textContent = "⚠️ Sync failed — check the Farm ID and try again";
    return {
      ok: false,
      error: e.message
    };
  } finally {
    __set_farmPanelSyncInFlight(false);
    btn.textContent = originalLabel;
    if (__syncErrorMsg && typeof renderFarmPanelTabContent === "function") renderFarmPanelTabContent();
    __mark("sync end (total)");
    showSyncTimingPanel(farmId, __marks, __syncErrorMsg);
    __syncMark = null;
  }
}

$("farmPanelSyncBtn").onclick = async () => {
  if (farmPanelSyncInFlight) return;
  const farmId = ($("farmPanelIdInput").value || "").trim();
  if (!farmId) {
    toast("Enter a Farm ID first 🔢");
    return;
  }
  showSyncProgressModal();
  const res = await performFarmPanelSync(farmId);
  if (!res) {
    hideSyncProgressModal();
    return;
  }
  hideSyncProgressModal(res.ok ? "Synced!" : "Sync failed");
  setTimeout(() => {
    if (res.ok) showSyncCompleteModal(res.message, {
      title: "SYNC COMPLETE"
    }); else showSyncCompleteModal("⚠️ Couldn't reach the farm data. Check the Farm ID and try again.", {
      title: "SYNC FAILED"
    });
  }, 280);
};

