export function withPreservedResourceScroll(wrap, cardKey, renderFn) {
  const wrapScrollTop = wrap ? wrap.scrollTop : 0;
  let detailsScrollTop = 0, obScrollLeft = 0;
  const cardEl = wrap && cardKey ? wrap.querySelector(`.card[data-search="${cardKey}"]`) : null;
  if (cardEl) {
    const detailsEl = cardEl.querySelector(".card-details");
    if (detailsEl) detailsScrollTop = detailsEl.scrollTop;
    const obEl = cardEl.querySelector(".ob-season-scroll");
    if (obEl) obScrollLeft = obEl.scrollLeft;
  }
  renderFn();
  if (wrap) wrap.scrollTop = wrapScrollTop;
  const newCardEl = wrap && cardKey ? wrap.querySelector(`.card[data-search="${cardKey}"]`) : null;
  if (newCardEl) {
    const newDetailsEl = newCardEl.querySelector(".card-details");
    if (newDetailsEl) newDetailsEl.scrollTop = detailsScrollTop;
    const newObEl = newCardEl.querySelector(".ob-season-scroll");
    if (newObEl) newObEl.scrollLeft = obScrollLeft;
  }
}

