export let bettySortMode = "rate";

function bettyItemCategory(name) {
  if (BASE_FRUITS[name]) return "Fruit";
  if (BASE_GREENHOUSE[name]) return "Greenhouse";
  return "Crop";
}

export function bettyGatherItems() {
  const names = [ ...Object.keys(BASE_CROPS), ...Object.keys(BASE_FRUITS), ...Object.keys(BASE_GREENHOUSE) ];
  return names.map(name => {
    const baseCoin = BETTY_BASE_COIN_SELL[name] || 0;
    const marketPrice = bettyMarketPrice(name);
    const baseRate = baseCoin > 0 && marketPrice > 0 ? baseCoin / marketPrice : 0;
    const category = bettyItemCategory(name);
    const boostMult = bettyGreenThumbOn && category === "Crop" ? 1.05 : 1;
    const qty = marketPrice > 0 ? 1 / marketPrice : 0;
    return {
      name: name,
      category: category,
      baseCoin: baseCoin,
      marketPrice: marketPrice,
      qty: qty,
      baseRate: baseRate,
      boostedRate: baseRate * boostMult
    };
  }).filter(it => it.baseCoin > 0 && it.marketPrice > 0);
}

export function bettySortItems(items) {
  const sorted = items.slice();
  if (bettySortMode === "name") sorted.sort((a, b) => a.name.localeCompare(b.name)); else if (bettySortMode === "price") sorted.sort((a, b) => a.marketPrice - b.marketPrice); else sorted.sort((a, b) => b.boostedRate - a.boostedRate);
  return sorted;
}

export function bettyHighestRate(items) {
  if (!items.length) return null;
  return items.reduce((max, it) => it.boostedRate > max.boostedRate ? it : max, items[0]);
}

