export function bettySetSwindler(on, rank) {
  const id = "skill_coin_swindler";
  const apply = arr => {
    const has = arr.includes(id);
    if (on && !has) return arr.concat(id);
    if (!on && has) return arr.filter(x => x !== id);
    return arr;
  };
  selectedSkills = apply(selectedSkills);
  skillDraftSelectedSkills = apply(skillDraftSelectedSkills);
  saveSkillState();
  if (rank) {
    const r = Math.min(3, Math.max(1, Math.floor(rank)));
    [ ascensionRanks, skillDraftAscensionRanks ].forEach(o => {
      if (r <= 1) delete o[id]; else o[id] = r;
    });
    saveAscensionState();
  }
  applyAscensionRanks();
  applySkillModifiers();
  renderBettyShop();
  refreshAfterSkillChange();
}

$("bettySwindlerCheck").onchange = e => bettySetSwindler(!!e.target.checked);

