export function formatTrade12h(ts) {
  if (!ts) return "—";
  const d = new Date(ts);
  const datePart = d.toLocaleDateString(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric"
  });
  let h = d.getHours();
  const m = d.getMinutes();
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12;
  if (h === 0) h = 12;
  const timePart = `${h}:${String(m).padStart(2, "0")} ${ampm}`;
  return `${datePart} · ${timePart}`;
}

function computeTradeFigures(t) {
  const marketPrice = tradeMarketPrice(t.itemName);
  const grossMarketValue = t.remainingQty * marketPrice;
  const feeAmount = grossMarketValue * (feePercent / 100);
  const marketValue = grossMarketValue - feeAmount;
  const costBasis = t.remainingQty * t.buyPrice;
  const pl = marketValue - costBasis;
  const plPct = costBasis > 0 ? pl / costBasis * 100 : 0;
  const originalCapital = t.qty * t.buyPrice;
  return {
    marketPrice: marketPrice,
    grossMarketValue: grossMarketValue,
    feeAmount: feeAmount,
    marketValue: marketValue,
    costBasis: costBasis,
    pl: pl,
    plPct: plPct,
    originalCapital: originalCapital,
    feePercent: feePercent
  };
}

export function tradeGatherActiveSorted() {
  const withFigures = tradeActive.map(t => ({
    t: t,
    fig: computeTradeFigures(t)
  }));
  if (tradeSortMode === "name") {
    withFigures.sort((a, b) => a.t.itemName.localeCompare(b.t.itemName));
  } else if (tradeSortMode === "date") {
    withFigures.sort((a, b) => b.t.createdAt - a.t.createdAt);
  } else {
    withFigures.sort((a, b) => b.fig.pl - a.fig.pl);
  }
  return withFigures;
}

