export function safeParse(raw, fallback) {
  try {
    const v = JSON.parse(raw || "null");
    return v && typeof v === "object" ? v : fallback;
  } catch (e) {
    return fallback;
  }
}

export function computeAll() {
  const activeBoostCount = BOOST_TIERS.filter(t => ticketBoosts[t].enabled).length;
  const vipBonus = ticketBoosts.vip.enabled ? 2 : 0;
  const totalBoostBonus = activeBoostCount + vipBonus;
  const boostCostTotal = BOOST_TIERS.reduce((sum, t) => {
    const b = ticketBoosts[t];
    return sum + (b.enabled && b.costMode === "cost" ? parseFloat(b.cost) || 0 : 0);
  }, 0);
  const firstWeekDeduction = Math.min(7, seasonDays);
  const remainingDeliveryDays = Math.max(0, seasonDays - firstWeekDeduction);
  const doubleDeliveryWeeks = Math.floor(remainingDeliveryDays / 7);
  const totalSeasonWeeks = Math.floor(seasonDays / 7);
  const animalBountyEligibleWeeks = Math.max(0, totalSeasonWeeks - 2);
  let npcTotal = 0;
  let npcDoubleBonus = 0;
  let npcFlowerTotal = 0;
  const npcRows = NPC_KEYS.map(npc => {
    const base = TICKET_REWARDS_APP[npc];
    const perDelivery = base + totalBoostBonus;
    const on = !!npcDeliverToggle[npc];
    const skip = Math.min(remainingDeliveryDays, npcSkipDays[npc] || 0);
    const days = on ? Math.max(0, remainingDeliveryDays - skip) : 0;
    const doubleWeeksForThis = on ? Math.floor(days / 7) : 0;
    const total = perDelivery * days + perDelivery * doubleWeeksForThis;
    const flowerCost = npcFlowerCost[npc] || 0;
    const flowerTotal = flowerCost * days;
    npcTotal += total;
    npcDoubleBonus += perDelivery * doubleWeeksForThis;
    npcFlowerTotal += flowerTotal;
    return {
      npc: npc,
      base: base,
      perDelivery: perDelivery,
      on: on,
      skip: skip,
      days: days,
      total: total,
      flowerCost: flowerCost,
      flowerTotal: flowerTotal
    };
  });
  const animalTotal = animalWeekly * animalBountyEligibleWeeks;
  const bountyItemTotal = bountyWeekly * animalBountyEligibleWeeks;
  const bountyCompletionBonus = bountyToggle ? BOUNTY_WEEKLY_BONUS * animalBountyEligibleWeeks : 0;
  const bountyTotal = bountyItemTotal + bountyCompletionBonus;
  const choresTotal = choresWeekly * animalBountyEligibleWeeks;
  const animalFlowerTotal = animalFlowerCost * animalBountyEligibleWeeks;
  const bountyFlowerTotal = bountyFlowerCost * animalBountyEligibleWeeks;
  const choresFlowerTotal = choresFlowerCost * animalBountyEligibleWeeks;
  const grandFlowerTotal = npcFlowerTotal + animalFlowerTotal + bountyFlowerTotal + choresFlowerTotal;
  const dailyRewardTotal = getEffectiveDailyReward();
  const grandTotal = npcTotal + undeliveredLastSeason + animalTotal + bountyTotal + choresTotal + megastoreTickets + dailyRewardTotal - boostCostTotal;
  return {
    activeBoostCount: activeBoostCount,
    vipBonus: vipBonus,
    totalBoostBonus: totalBoostBonus,
    boostCostTotal: boostCostTotal,
    firstWeekDeduction: firstWeekDeduction,
    remainingDeliveryDays: remainingDeliveryDays,
    doubleDeliveryWeeks: doubleDeliveryWeeks,
    totalSeasonWeeks: totalSeasonWeeks,
    animalBountyEligibleWeeks: animalBountyEligibleWeeks,
    npcRows: npcRows,
    npcTotal: npcTotal,
    npcDoubleBonus: npcDoubleBonus,
    npcFlowerTotal: npcFlowerTotal,
    animalTotal: animalTotal,
    bountyTotal: bountyTotal,
    bountyItemTotal: bountyItemTotal,
    bountyCompletionBonus: bountyCompletionBonus,
    choresTotal: choresTotal,
    animalFlowerTotal: animalFlowerTotal,
    bountyFlowerTotal: bountyFlowerTotal,
    choresFlowerTotal: choresFlowerTotal,
    grandFlowerTotal: grandFlowerTotal,
    dailyRewardTotal: dailyRewardTotal,
    grandTotal: grandTotal
  };
}

function updateDynamicValues() {
  const c = computeAll();
  setText("bd-firstweek", `−${fmt(c.firstWeekDeduction)} days`);
  setText("bd-remaining", `${fmt(c.remainingDeliveryDays)} days`);
  setText("bd-doubleweeks", `${fmt(c.doubleDeliveryWeeks)} days`);
  setText("bd-eligibleweeks", `${fmt(c.animalBountyEligibleWeeks)} wk`);
  setText("chores-note", `Off during the season's first week and during Auction Week — only ${fmt(c.animalBountyEligibleWeeks)} of the ${fmt(c.totalSeasonWeeks)} weeks in a ${fmt(seasonDays)}-day season actually pay out.`);
  c.npcRows.forEach(r => {
    const s = slug(r.npc);
    setText(`npcMeta-${s}`, `base ${fmt(r.base)} → ${fmt(r.perDelivery)}/delivery${c.totalBoostBonus ? ` (+${c.totalBoostBonus} boost)` : ""}${r.skip ? ` − ${fmt(r.skip)} skipped` : ""}`);
    setText(`npcTotal-${s}`, fmt(r.total));
  });
  setText("sum-npc", fmt(c.npcTotal));
  setText("sum-npc-note", ` (incl. +${fmt(c.npcDoubleBonus)} from Double Delivery)`);
  setText("sum-undelivered", fmt(undeliveredLastSeason));
  setText("sum-animal", fmt(c.animalTotal));
  setText("sum-bounty", fmt(c.bountyTotal));
  setText("sum-bounty-note", bountyToggle ? ` (incl. +${fmt(c.bountyCompletionBonus)} completion bonus)` : "");
  setText("sum-chores", fmt(c.choresTotal));
  setText("sum-megastore", fmt(megastoreTickets));
  setText("sum-dailyreward", fmt(c.dailyRewardTotal));
  const dailyRewardInp = $("dailyRewardInput");
  if (dailyRewardInp && !dailyRewardManual) dailyRewardInp.value = getEffectiveDailyReward();
  const boostCostLine = $("sum-boostcost-line");
  if (boostCostLine) boostCostLine.style.display = c.boostCostTotal > 0 ? "" : "none";
  setText("sum-boostcost", `−${fmt(c.boostCostTotal)}`);
  setText("sum-total-label", `🎟️ TOTAL / ${fmt(seasonDays)} DAYS`);
  setText("sum-total", fmt(c.grandTotal));
  setText("sum-flower-total", fmt(c.grandFlowerTotal));
}

export function wireEvents() {
  document.querySelectorAll(".boost-enable-btn").forEach(btn => {
    btn.onclick = () => {
      const t = btn.dataset.tier;
      ticketBoosts[t].enabled = !ticketBoosts[t].enabled;
      saveBoosts();
      renderTicketCalc();
    };
  });
  document.querySelectorAll(".cost-mode-btn").forEach(btn => {
    btn.onclick = () => {
      const t = btn.dataset.tier;
      ticketBoosts[t].costMode = btn.dataset.mode;
      saveBoosts();
      renderTicketCalc();
    };
  });
  document.querySelectorAll(".npc-deliver-btn").forEach(btn => {
    btn.onclick = () => {
      setNpcDeliver(btn.dataset.npc, btn.dataset.val === "1");
      renderTicketCalc();
    };
  });
  const bountyBtn = $("bountyToggleBtn");
  if (bountyBtn) bountyBtn.onclick = () => {
    setBountyToggle(!bountyToggle);
    renderTicketCalc();
  };
  document.querySelectorAll(".npc-skip-input").forEach(inp => {
    inp.oninput = () => {
      setNpcSkip(inp.dataset.npc, inp.value);
      updateDynamicValues();
    };
  });
  document.querySelectorAll(".boost-cost-input").forEach(inp => {
    inp.oninput = () => {
      const t = inp.dataset.tier;
      ticketBoosts[t].cost = Math.max(0, parseFloat(inp.value) || 0);
      saveBoosts();
      updateDynamicValues();
    };
  });
  const undeliveredInp = $("undeliveredInput");
  if (undeliveredInp) undeliveredInp.oninput = () => {
    setUndelivered(undeliveredInp.value);
    updateDynamicValues();
  };
  const seasonDaysInp = $("seasonDaysInput");
  if (seasonDaysInp) seasonDaysInp.oninput = () => {
    setSeasonDays(seasonDaysInp.value);
    updateDynamicValues();
  };
  const animalInp = $("animalWeeklyInput");
  if (animalInp) animalInp.oninput = () => {
    setAnimalWeekly(animalInp.value);
    updateDynamicValues();
  };
  const bountyWeeklyInp = $("bountyWeeklyInput");
  if (bountyWeeklyInp) bountyWeeklyInp.oninput = () => {
    setBountyWeekly(bountyWeeklyInp.value);
    updateDynamicValues();
  };
  const megastoreInp = $("megastoreInput");
  if (megastoreInp) megastoreInp.oninput = () => {
    setMegastore(megastoreInp.value);
    updateDynamicValues();
  };
  const dailyRewardInp = $("dailyRewardInput");
  if (dailyRewardInp) dailyRewardInp.oninput = () => {
    setDailyReward(dailyRewardInp.value);
    updateDynamicValues();
  };
  const choresWeeklyInp = $("choresWeeklyInput");
  if (choresWeeklyInp) choresWeeklyInp.oninput = () => {
    setChoresWeekly(choresWeeklyInp.value);
    updateDynamicValues();
  };
  document.querySelectorAll(".npc-flower-input").forEach(inp => {
    inp.oninput = () => {
      setNpcFlower(inp.dataset.npc, inp.value);
      updateDynamicValues();
    };
  });
  const animalFlowerInp = $("animalFlowerInput");
  if (animalFlowerInp) animalFlowerInp.oninput = () => {
    setAnimalFlower(animalFlowerInp.value);
    updateDynamicValues();
  };
  const bountyFlowerInp = $("bountyFlowerInput");
  if (bountyFlowerInp) bountyFlowerInp.oninput = () => {
    setBountyFlower(bountyFlowerInp.value);
    updateDynamicValues();
  };
  const choresFlowerInp = $("choresFlowerInput");
  if (choresFlowerInp) choresFlowerInp.oninput = () => {
    setChoresFlower(choresFlowerInp.value);
    updateDynamicValues();
  };
}

