export const GUNTER_FLOWER_COST_MODE_LS_KEY = "hl_gunter_flower_cost_mode";

const GUNTER_MUTANT_BOOST_LS_KEY = "hl_gunter_mutant_boosts";

const GUNTER_MUTANT_BOOSTS = [ "Deep Sea Helm", "Full Moon", "Guardians", "Navigation Table" ];

let gunterMutantBoosts = safeParse(localStorage.getItem(GUNTER_MUTANT_BOOST_LS_KEY), {});

if (!gunterMutantBoosts || typeof gunterMutantBoosts !== "object") gunterMutantBoosts = {};

function gunterMutantBoostMultiplier() {
  let mult = 1;
  if (gunterMutantBoosts["Deep Sea Helm"]) mult += 1;
  if (gunterMutantBoosts["Navigation Table"]) mult += 1;
  if (gunterMutantBoosts["Full Moon"]) mult += gunterMutantBoosts["Guardians"] ? 2 : 1;
  return mult;
}

function gunterMutantSaveBoosts() {
  localStorage.setItem(GUNTER_MUTANT_BOOST_LS_KEY, JSON.stringify(gunterMutantBoosts));
}

function gunterMutantDetectItemActive(name) {
  if (!farmPanelGameState || typeof farmSyncExtractGameState !== "function" || typeof farmSyncCollectEquippedAndPlacedNames !== "function") return false;
  const g = farmSyncExtractGameState(farmPanelGameState);
  const names = farmSyncCollectEquippedAndPlacedNames(g);
  const target = name.trim().toLowerCase();
  return Array.from(names).some(n => n.trim().toLowerCase() === target);
}

function gunterMutantDetectBoostStatus() {
  return {
    "Deep Sea Helm": gunterMutantDetectItemActive("Deep Sea Helm"),
    "Navigation Table": gunterMutantDetectItemActive("Navigation Table"),
    "Full Moon": isFullMoonToday(),
    Guardians: !!getActiveSeasonGuardianName()
  };
}

export function gunterMutantSyncAutoBoosts() {
  if (!farmPanelGameState) return false;
  const status = gunterMutantDetectBoostStatus();
  let changed = false;
  GUNTER_MUTANT_BOOSTS.forEach(name => {
    const detected = !!status[name];
    if (gunterMutantBoosts[name] !== detected) {
      gunterMutantBoosts[name] = detected;
      changed = true;
    }
  });
  if (changed) gunterMutantSaveBoosts();
  return changed;
}

function gunterMutantFarmActivityCount(key) {
  if (!farmPanelGameState || typeof farmSyncExtractGameState !== "function") return 0;
  const g = farmSyncExtractGameState(farmPanelGameState);
  const activity = typeof farmPanelField === "function" ? farmPanelField(g, "farmActivity") : g && g.farmActivity;
  if (!activity || typeof activity !== "object") return 0;
  const v = activity[key];
  return typeof v === "number" && isFinite(v) ? v : 0;
}

function formatCompactNum(n) {
  if (n >= 1e6) return (n % 1e6 === 0 ? n / 1e6 : (n / 1e6).toFixed(1)) + "M";
  if (n >= 1e3) return (n % 1e3 === 0 ? n / 1e3 : (n / 1e3).toFixed(1)) + "K";
  return String(n);
}

function gunterOrdinal(n) {
  const rem100 = n % 100;
  if (rem100 >= 11 && rem100 <= 13) return `${n}th`;
  const rem10 = n % 10;
  if (rem10 === 1) return `${n}st`;
  if (rem10 === 2) return `${n}nd`;
  if (rem10 === 3) return `${n}rd`;
  return `${n}th`;
}

function gunterAlreadyBought(nodeName) {
  const g = farmPanelGameState ? farmSyncExtractGameState(farmPanelGameState) : null;
  const farmActivity = g ? farmPanelField(g, "farmActivity") : null;
  if (!farmActivity || typeof farmActivity !== "object") return 0;
  const key = `${nodeName} Bought`;
  return typeof farmActivity[key] === "number" ? farmActivity[key] : 0;
}

function gunterFormatOdds(odds) {
  if (!odds && odds !== 0) return "—";
  const pct = odds * 100;
  const rounded = pct >= 10 ? Math.round(pct * 10) / 10 : Math.round(pct * 100) / 100;
  return `${rounded}%`;
}

function gunterMutantSeasonBadges(seasons) {
  if (!seasons || !seasons.length) return "—";
  return `<span class="mutant-map-season-badges">${seasons.map(s => `<img src="${MUTANT_SEASON_ICON[s] || MUTANT_FALLBACK_ICON}" alt="${escapeHtml(s)}" title="${escapeHtml(s)}" style="width:13px;height:13px;image-rendering:pixelated;">`).join("")}</span>`;
}

export function renderChapterMutantFishTop() {
  const el = $("cfmMutantTop");
  if (!el) return;
  const existingScrollEl = el.querySelector(".mutant-map-hscroll");
  const preservedScrollLeft = existingScrollEl ? existingScrollEl.scrollLeft : 0;
  const chapter = getCurrentChapterName();
  const mutants = getCurrentChapterMutantFish();
  if (!mutants.length) {
    el.innerHTML = `<div class="gunter-empty-note">🐟 Chapter Mutant Fish Map<br>No drop-rate data tracked yet for this chapter.</div>`;
    return;
  }
  const mult = gunterMutantBoostMultiplier();
  const groupsHtml = mutants.map((name, gi) => {
    const color = MUTANT_GROUP_COLORS[gi % MUTANT_GROUP_COLORS.length];
    const catchData = MUTANT_FISH_CATCH_DATA[name];
    const triggers = catchData && catchData.triggers ? catchData.triggers : [];
    const boostLabel = MUTANT_FISH_BOOST_LABEL[name];
    const badgeHtml = boostLabel ? `<span class="mutant-map-boost-badge is-boost">${escapeHtml(boostLabel)}</span>` : `<span class="mutant-map-boost-badge is-cosmetic">Cosmetic</span>`;
    const rowsHtml = triggers.length ? triggers.map(trig => {
      const info = MUTANT_TRIGGER_FISH_INFO[trig.fish] || {
        likes: [],
        baits: [],
        seasons: []
      };
      const chumHtml = info.likes.length ? info.likes.map(c => `<span class="mutant-map-pill">${getIcon(c)}${escapeHtml(c)}</span>`).join("") : "—";
      const guaranteedItem = getGuaranteedCatchItemForFish(trig.fish);
      const randomBaitHtml = info.baits.length ? info.baits.map(b => `<span class="mutant-map-pill">${getIcon(b)}${escapeHtml(b)}</span>`).join("") : "";
      const guaranteedBaitHtml = guaranteedItem ? `<span class="mutant-map-pill is-guaranteed" title="Guaranteed catch via ${escapeHtml(guaranteedItem)}">${getIcon(guaranteedItem)}${escapeHtml(guaranteedItem)}</span>` : "";
      const baitHtml = randomBaitHtml + guaranteedBaitHtml || "—";
      const baseOdds = trig.odds;
      const boostOdds = baseOdds * mult;
      return `\n        <div class="mutant-map-table-row">\n          <div class="mutant-map-table-cell is-fish-cell">${getIcon(trig.fish)}<span>${escapeHtml(trig.fish)}</span></div>\n          <div class="mutant-map-table-cell">${chumHtml}</div>\n          <div class="mutant-map-table-cell">${baitHtml}</div>\n          <div class="mutant-map-table-cell">${gunterMutantSeasonBadges(info.seasons)}</div>\n          <div class="mutant-map-table-cell is-pct-cell">${gunterFormatOdds(baseOdds)}</div>\n          <div class="mutant-map-table-cell is-pct-cell${mult > 1 ? " is-boosted" : ""}">${gunterFormatOdds(boostOdds)}</div>\n        </div>`;
    }).join("") : `\n        <div class="mutant-map-table-row">\n          <div class="mutant-map-table-cell" style="grid-column:1 / -1;">No drop-rate data tracked yet.</div>\n        </div>`;
    const mapsFound = Math.min(9, gunterMutantFarmActivityCount(`${name} Map Piece Found`));
    const caughtCount = gunterMutantFarmActivityCount(`${name} Caught`);
    return `\n      <div class="mutant-group-card" style="--group-bg:${color.bg};--group-border:${color.border};--group-head:${color.head};">\n        <div class="mutant-group-header">\n          <span class="mutant-group-header-icon">${getMutantFishIcon(name, 18)}</span>\n          <span class="mutant-group-header-name">${escapeHtml(name)}</span>\n          ${badgeHtml}\n        </div>\n        <div class="mutant-group-progress">\n          <span class="mutant-group-progress-item">🗺️ Find Maps [${mapsFound}/9]</span>\n          <span class="mutant-group-progress-item">🎣 Catched [${caughtCount}]</span>\n        </div>\n        <div class="mutant-map-table">\n          <div class="mutant-map-table-header">\n            <div class="mutant-map-table-cell">Fish</div>\n            <div class="mutant-map-table-cell">Chum</div>\n            <div class="mutant-map-table-cell">Bait</div>\n            <div class="mutant-map-table-cell">Season</div>\n            <div class="mutant-map-table-cell is-pct-cell">Base %</div>\n            <div class="mutant-map-table-cell is-pct-cell">Boost %</div>\n          </div>\n          ${rowsHtml}\n        </div>\n      </div>`;
  }).join("");
  el.innerHTML = `\n    <div class="mutant-map-chapter-title">🐟 ${escapeHtml(chapter)} — Mutant Fish</div>\n    <div class="mutant-map-hscroll">${groupsHtml}</div>\n  `;
  const newScrollEl = el.querySelector(".mutant-map-hscroll");
  if (newScrollEl) newScrollEl.scrollLeft = preservedScrollLeft;
}

export function gunterRenderTop() {
  const el = $("gunterShopTop");
  if (!el) return;
  const nodesRows = GUNTER_BUY_NODES.map(n => `\n      <div class="gunter-top-row">\n        <span class="gunter-top-row-name">${getIcon(n.name)} ${escapeHtml(n.name)}</span>\n        <span class="gunter-top-row-val">${n.price}${getIcon("Sunstone")}</span>\n        <span class="gunter-top-row-inc">+${n.increase}</span>\n      </div>`).join("");
  const upgradeRows = GUNTER_UPGRADE_NODES.map(n => `\n      <div class="gunter-top-row">\n        <span class="gunter-top-row-name">${escapeHtml(n.name)}</span>\n        <span class="gunter-top-row-div"></span>\n        <span class="gunter-top-row-cost">${getIcon("Obsidian")}${n.obsidian}</span>\n        <span class="gunter-top-row-div"></span>\n        <span class="gunter-top-row-cost">${getIcon(n.node)}${n.nodeCount}x</span>\n        <span class="gunter-top-row-div"></span>\n        <span class="gunter-top-row-cost">${COIN_ICON}${formatCompactNum(n.coins)}</span>\n      </div>`).join("");
  el.innerHTML = `\n    <div class="gunter-top-col is-nodes${gunterTopNodesOpen ? " is-open" : ""}">\n      <div class="gunter-top-col-title">🧱 Nodes Cost<button type="button" class="gunter-top-col-toggle" data-gunter-top-toggle="nodes">›</button></div>\n      <div class="gunter-top-table">\n        <div class="gunter-top-header-row"><span>Node</span><span>Cost</span><span>Incr.</span></div>\n        ${nodesRows}\n      </div>\n    </div>\n    <div class="gunter-top-col is-upgrade${gunterTopUpgradeOpen ? " is-open" : ""}">\n      <div class="gunter-top-col-title">⚒️ Upgrade Cost<button type="button" class="gunter-top-col-toggle" data-gunter-top-toggle="upgrade">›</button></div>\n      <div class="gunter-top-table is-upgrade-table">\n        <div class="gunter-top-header-row"><span>Node</span><span></span><span>${getIcon("Obsidian")}</span><span></span><span>⛏️</span><span></span><span>${COIN_ICON}</span></div>\n        ${upgradeRows}\n      </div>\n    </div>\n  `;
}

function gunterSunstoneDays(totalSunstone) {
  const rocks = gunterSunstoneRockCount;
  if (!rocks || rocks < 1) return null;
  const cycles = Math.ceil(totalSunstone / rocks);
  return Math.max(0, cycles - 1) * SUNSTONE_RECOVERY_DAYS;
}

export function gunterRenderMid() {
  const el = $("gunterShopMidContent");
  const inputWrap = $("gunterSunstoneInputWrap");
  const flowerCostWrap = $("gunterFlowerCostWrap");
  if (!el) return;
  const showInput = gunterActiveTab === "buy";
  const showFlowerCost = gunterActiveTab === "upgrade";
  if (inputWrap) inputWrap.style.display = showInput ? "flex" : "none";
  if (flowerCostWrap) flowerCostWrap.style.display = showFlowerCost ? "flex" : "none";
  if (showFlowerCost) gunterRenderFlowerCost();
  el.classList.toggle("has-sunstone-input", showInput);
  el.classList.toggle("has-flower-cost", showFlowerCost);
  const midWrap = $("gunterShopMid");
  if (midWrap) {
    midWrap.classList.toggle("is-buy-tab", gunterActiveTab === "buy");
    midWrap.classList.toggle("is-upgrade-tab", gunterActiveTab === "upgrade");
  }
  if (gunterActiveTab === "buy" && gunterSelectedBuy) {
    const node = GUNTER_BUY_NODES.find(n => n.name === gunterSelectedBuy);
    if (!node) {
      el.innerHTML = `<div class="gunter-mid-empty">Tap a node below to calculate its Sunstone cost.</div>`;
      return;
    }
    const count = gunterBuyCounts[node.name] || 1;
    const alreadyBought = gunterAlreadyBought(node.name);
    const totalSunstone = gunterBuyCost(node, count, alreadyBought);
    const grandTotalSunstone = gunterBuyTotalCost(node, count, alreadyBought);
    const days = gunterSunstoneDays(grandTotalSunstone);
    const daysLabel = days === null ? "—" : `${days} Days`;
    const rocks = gunterSunstoneRockCount || 0;
    const cycleLabel = rocks > 0 ? `${rocks}${getIcon("Sunstone")} / ${SUNSTONE_RECOVERY_DAYS}d` : "—";
    el.innerHTML = `\n      <div class="gunter-mid-head">\n        <div class="gunter-mid-icon">${getIcon(node.name)}</div>\n        <div class="gunter-mid-name">${escapeHtml(node.name)}</div>\n      </div>\n      <div class="gunter-mid-stats">\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Count</div>\n          <div class="gunter-mid-stat-value">${count}</div>\n        </div>\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Node Price</div>\n          <div class="gunter-mid-stat-value">${getIcon("Sunstone")} ${totalSunstone}</div>\n        </div>\n        <div class="gunter-mid-stat is-total-stat">\n          <div class="gunter-mid-stat-label">Total Sunstone Cost</div>\n          <div class="gunter-mid-stat-value">${getIcon("Sunstone")} ${grandTotalSunstone}</div>\n        </div>\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Yield / Cycle</div>\n          <div class="gunter-mid-stat-value">${cycleLabel}</div>\n        </div>\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Days Needed</div>\n          <div class="gunter-mid-stat-value">${daysLabel}</div>\n        </div>\n      </div>\n      <div class="gunter-mid-note">Based on ${alreadyBought} ${escapeHtml(node.name)}${alreadyBought === 1 ? "" : "s"} already bought${farmPanelGameState ? " (synced from your farm)" : ""}. Node Price is the price of the ${gunterOrdinal(alreadyBought + count)} ${escapeHtml(node.name)} alone; Total Sunstone Cost is the sum of all ${count} crafts from the ${gunterOrdinal(alreadyBought + 1)} to the ${gunterOrdinal(alreadyBought + count)}. ${rocks} owned Sunstone Node${rocks === 1 ? "" : "s"} yield ${rocks} Sunstone immediately, then ${rocks} more every ${SUNSTONE_RECOVERY_DAYS} days after (1 per node per dig, each node holds up to ${SUNSTONE_MINES_PER_ROCK} Sunstone before it's depleted).</div>\n    `;
    return;
  }
  if (gunterActiveTab === "upgrade" && gunterSelectedUpgrade) {
    const node = GUNTER_UPGRADE_NODES.find(n => n.name === gunterSelectedUpgrade);
    if (!node) {
      el.innerHTML = `<div class="gunter-mid-empty">Tap an upgrade below to calculate its cost.</div>`;
      return;
    }
    const count = gunterUpgradeCounts[node.name] || 1;
    const totalObsidian = node.obsidian * count;
    const totalCoins = node.coins * count;
    const totalNodes = node.nodeCount * count;
    el.innerHTML = `\n      <div class="gunter-mid-head">\n        <div class="gunter-mid-icon">${getIcon(node.name)}</div>\n        <div class="gunter-mid-name">${escapeHtml(node.name)}</div>\n      </div>\n      <div class="gunter-mid-stats">\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Count</div>\n          <div class="gunter-mid-stat-value">${count}</div>\n        </div>\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Obsidian Cost</div>\n          <div class="gunter-mid-stat-value">${getIcon("Obsidian")} ${totalObsidian}</div>\n        </div>\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Coin Cost</div>\n          <div class="gunter-mid-stat-value">${COIN_ICON} ${totalCoins.toLocaleString()}</div>\n        </div>\n        <div class="gunter-mid-stat">\n          <div class="gunter-mid-stat-label">Node Cost</div>\n          <div class="gunter-mid-stat-value">${getIcon(node.node)} ${totalNodes}x ${escapeHtml(node.node)}</div>\n        </div>\n      </div>\n      <div class="gunter-mid-note">Each ${escapeHtml(node.name)} consumes ${node.nodeCount} placed ${escapeHtml(node.node)}${node.nodeCount === 1 ? "" : "s"}, ${node.obsidian}${" "}Obsidian and ${node.coins.toLocaleString()} Coins.</div>\n    `;
    return;
  }
  el.innerHTML = `<div class="gunter-mid-empty">Tap a node below to calculate its cost.</div>`;
}

export function gunterRenderSunstoneInput() {
  const input = $("gunterSunstoneRockInput");
  const label = $("gunterSunstoneInputLabel");
  if (label) label.innerHTML = `${getIcon("Sunstone Rock")} Sunstone Node`;
  if (input && document.activeElement !== input) input.value = String(gunterSunstoneRockCount);
}

export const gunterGridEntranceShown = {};

export function renderChapterMutantFishBottom() {
  const el = $("cfmMutantBottom");
  if (!el) return;
  const rows = GUNTER_MUTANT_BOOSTS.map(name => {
    const checked = !!gunterMutantBoosts[name];
    const iconName = name === "Guardians" ? currentSeason + " Guardian" : name;
    return `\n      <label class="mutant-map-boost-row${checked ? " is-checked" : ""}" data-mutant-boost="${escapeHtml(name)}">\n        <span class="mutant-map-boost-icon">${getMutantFishIcon(iconName, 18)}</span>\n        <span class="mutant-map-boost-name">${escapeHtml(iconName)}</span>\n        <input type="checkbox" class="mutant-map-boost-check" data-mutant-boost-check="${escapeHtml(name)}"${checked ? " checked" : ""}>\n      </label>`;
  }).join("");
  const mult = gunterMutantBoostMultiplier();
  const multLabel = mult > 1 ? `Current multiplier: ${mult}x (+${(mult - 1) * 100}%)` : "No boosts active — showing base drop rates.";
  el.innerHTML = `\n    <div class="mutant-map-boost-list">\n      <div class="mutant-map-boost-list-title">⚓ Catch-Rate Boosts</div>\n      <div class="mutant-map-boost-rows">${rows}</div>\n      <div class="mutant-map-boost-mult">${escapeHtml(multLabel)}</div>\n    </div>\n  `;
}

export function renderMarineMarvelsTop() {
  const el = $("cfmMarvelsTop");
  if (!el) return;
  const existingScrollEl = el.querySelector(".mutant-map-hscroll");
  const preservedScrollLeft = existingScrollEl ? existingScrollEl.scrollLeft : 0;
  const marvels = BASE_MARINE_MARVELS;
  const mult = gunterMutantBoostMultiplier();
  const groupsHtml = marvels.map((name, gi) => {
    const color = MUTANT_GROUP_COLORS[gi % MUTANT_GROUP_COLORS.length];
    const catchData = MARVEL_FISH_CATCH_DATA[name];
    const triggers = catchData && catchData.triggers ? catchData.triggers : [];
    const boostLabel = MARVEL_BOOST_LABEL[name];
    const badgeHtml = boostLabel ? `<span class="mutant-map-boost-badge is-boost">${escapeHtml(boostLabel)}</span>` : `<span class="mutant-map-boost-badge is-cosmetic">Cosmetic</span>`;
    const rowsHtml = triggers.length ? triggers.map(trig => {
      const info = MARVEL_TRIGGER_FISH_INFO[trig.fish] || {
        likes: [],
        baits: [],
        seasons: []
      };
      const chumHtml = info.likes.length ? info.likes.map(c => `<span class="mutant-map-pill">${getIcon(c)}${escapeHtml(c)}</span>`).join("") : "—";
      const guaranteedItem = getGuaranteedCatchItemForFish(trig.fish);
      const randomBaitHtml = info.baits.length ? info.baits.map(b => `<span class="mutant-map-pill">${getIcon(b)}${escapeHtml(b)}</span>`).join("") : "";
      const guaranteedBaitHtml = guaranteedItem ? `<span class="mutant-map-pill is-guaranteed" title="Guaranteed catch via ${escapeHtml(guaranteedItem)}">${getIcon(guaranteedItem)}${escapeHtml(guaranteedItem)}</span>` : "";
      const baitHtml = randomBaitHtml + guaranteedBaitHtml || "—";
      const baseOdds = trig.odds;
      const boostOdds = baseOdds * mult;
      return `\n        <div class="mutant-map-table-row">\n          <div class="mutant-map-table-cell is-fish-cell">${getIcon(trig.fish)}<span>${escapeHtml(trig.fish)}</span></div>\n          <div class="mutant-map-table-cell">${chumHtml}</div>\n          <div class="mutant-map-table-cell">${baitHtml}</div>\n          <div class="mutant-map-table-cell">${gunterMutantSeasonBadges(info.seasons)}</div>\n          <div class="mutant-map-table-cell is-pct-cell">${gunterFormatOdds(baseOdds)}</div>\n          <div class="mutant-map-table-cell is-pct-cell${mult > 1 ? " is-boosted" : ""}">${gunterFormatOdds(boostOdds)}</div>\n        </div>`;
    }).join("") : `\n        <div class="mutant-map-table-row">\n          <div class="mutant-map-table-cell" style="grid-column:1 / -1;">No drop-rate data tracked yet.</div>\n        </div>`;
    const mapsFound = Math.min(9, gunterMutantFarmActivityCount(`${name} Map Piece Found`));
    const caughtCount = gunterMutantFarmActivityCount(`${name} Caught`);
    return `\n      <div class="mutant-group-card" style="--group-bg:${color.bg};--group-border:${color.border};--group-head:${color.head};">\n        <div class="mutant-group-header">\n          <span class="mutant-group-header-icon">${getMutantFishIcon(name, 18)}</span>\n          <span class="mutant-group-header-name">${escapeHtml(name)}</span>\n          ${badgeHtml}\n        </div>\n        <div class="mutant-group-progress">\n          <span class="mutant-group-progress-item">🗺️ Find Maps [${mapsFound}/9]</span>\n          <span class="mutant-group-progress-item">🎣 Catched [${caughtCount}]</span>\n        </div>\n        <div class="mutant-map-table">\n          <div class="mutant-map-table-header">\n            <div class="mutant-map-table-cell">Fish</div>\n            <div class="mutant-map-table-cell">Chum</div>\n            <div class="mutant-map-table-cell">Bait</div>\n            <div class="mutant-map-table-cell">Season</div>\n            <div class="mutant-map-table-cell is-pct-cell">Base %</div>\n            <div class="mutant-map-table-cell is-pct-cell">Boost %</div>\n          </div>\n          ${rowsHtml}\n        </div>\n      </div>`;
  }).join("");
  el.innerHTML = `\n    <div class="mutant-map-chapter-title">🌊 Marine Marvels</div>\n    <div class="mutant-map-hscroll">${groupsHtml}</div>\n  `;
  const newScrollEl = el.querySelector(".mutant-map-hscroll");
  if (newScrollEl) newScrollEl.scrollLeft = preservedScrollLeft;
}

