let tradePendingDeleteId = null;

let tradePendingDeleteType = "active";

export function deleteActiveTrade(id) {
  const t = tradeActive.find(x => x.id === id);
  if (!t) return;
  tradePendingDeleteId = id;
  tradePendingDeleteType = "active";
  const fig = computeTradeFigures(t);
  $("deleteTradeConfirmItem").innerHTML = `\n    <span class="trade-card-icon" style="font-size:21.6px;">${getIcon(t.itemName)}</span>\n    <div>\n      <div class="name">${escapeHtml(t.itemName)}</div>\n      <div class="meta">${fmt(t.remainingQty)}× held · ${fmt(fig.costBasis)} ${FLOWER_ICON} FLOWER capital</div>\n    </div>`;
  $("deleteTradeConfirmOverlay").classList.add("show");
}

export function deleteHistoryTrade(id) {
  const t = tradeHistory.find(x => x.id === id);
  if (!t) return;
  tradePendingDeleteId = id;
  tradePendingDeleteType = "history";
  $("deleteTradeConfirmItem").innerHTML = `\n    <span class="trade-card-icon" style="font-size:21.6px;">${getIcon(t.itemName)}</span>\n    <div>\n      <div class="name">${escapeHtml(t.itemName)}</div>\n      <div class="meta">${fmt(t.qty)}× traded · ${fmt(t.qty * t.buyPrice)} ${FLOWER_ICON} FLOWER capital</div>\n    </div>`;
  $("deleteTradeConfirmOverlay").classList.add("show");
}

$("closeDeleteTradeBtn").onclick = closeDeleteTradeConfirm;

$("cancelDeleteTradeBtn").onclick = closeDeleteTradeConfirm;

$("deleteTradeConfirmOverlay").addEventListener("click", e => {
  if (e.target.id === "deleteTradeConfirmOverlay") closeDeleteTradeConfirm();
});

$("confirmDeleteTradeBtn").onclick = () => {
  const id = tradePendingDeleteId;
  const type = tradePendingDeleteType;
  if (type === "history") {
    const t = tradeHistory.find(x => x.id === id);
    if (!t) {
      closeDeleteTradeConfirm();
      return;
    }
    tradeLifetime.invested = Math.max(0, tradeLifetime.invested - t.qty * t.buyPrice);
    tradeLifetime.sold = Math.max(0, tradeLifetime.sold - t.totalSoldValue);
    tradeHistory = tradeHistory.filter(x => x.id !== id);
    saveTradeState();
    closeDeleteTradeConfirm();
    renderTradeShop();
    toast("🗑 Trade removed");
    return;
  }
  const t = tradeActive.find(x => x.id === id);
  if (!t) {
    closeDeleteTradeConfirm();
    return;
  }
  tradeLifetime.invested = Math.max(0, tradeLifetime.invested - t.qty * t.buyPrice);
  tradeActive = tradeActive.filter(x => x.id !== id);
  saveTradeState();
  closeDeleteTradeConfirm();
  renderTradeShop();
  toast("🗑 Trade removed");
};

