export function updateNewTradeLiveTotal() {
  const qty = parseFloat($("newTradeQtyInput").value) || 0;
  const price = parseFloat($("newTradeBuyPriceInput").value) || 0;
  const total = qty * price;
  $("newTradeLiveTotal").innerHTML = `Total capital: <b>${fmt(total)}</b> FLOWER`;
  $("confirmNewTradeBtn").disabled = !(tradePickedItemName && qty > 0 && price >= 0);
}

