$("confirmNewTradeBtn").onclick = () => {
  const qty = parseFloat($("newTradeQtyInput").value) || 0;
  const buyPrice = parseFloat($("newTradeBuyPriceInput").value) || 0;
  if (!tradePickedItemName || qty <= 0) return;
  const trade = {
    id: tradeGenId(),
    itemName: tradePickedItemName,
    qty: qty,
    buyPrice: buyPrice,
    remainingQty: qty,
    createdAt: Date.now(),
    sells: []
  };
  tradeActive.push(trade);
  tradeLifetime.invested += qty * buyPrice;
  saveTradeState();
  closeNewTradeModal();
  tradeActiveTab = "active";
  renderTradeShop();
  toast(`🛒 Added ${fmt(qty)}× ${tradePickedItemName} to Trade Post`);
};

