export function updateSellTradeLiveTotal() {
  const qty = parseFloat($("sellTradeQtyInput").value) || 0;
  const price = parseFloat($("sellTradePriceInput").value) || 0;
  const gross = qty * price;
  const feeAmount = gross * (feePercent / 100);
  const net = gross - feeAmount;
  $("sellTradeLiveTotal").innerHTML = feePercent > 0 ? `Gross sale value: <b>${fmt(gross)}</b> FLOWER<br>Sell fee (${fmt(feePercent)}%): <b>−${fmt(feeAmount)}</b> FLOWER<br>Net received: <b>${fmt(net)}</b> FLOWER` : `Total sale value: <b>${fmt(gross)}</b> FLOWER`;
}

$("sellTradeQtyInput").addEventListener("input", updateSellTradeLiveTotal);

$("sellTradePriceInput").addEventListener("input", updateSellTradeLiveTotal);

$("confirmSellTradeBtn").onclick = () => {
  const t = tradeActive.find(x => x.id === tradeSellingId);
  if (!t) return;
  let qty = parseFloat($("sellTradeQtyInput").value) || 0;
  const price = parseFloat($("sellTradePriceInput").value) || 0;
  if (qty <= 0) {
    toast("Enter a quantity to sell");
    return;
  }
  qty = Math.min(qty, t.remainingQty);
  const gross = qty * price;
  const feeAmount = gross * (feePercent / 100);
  const net = gross - feeAmount;
  t.sells.push({
    qty: qty,
    price: price,
    total: gross,
    feePercent: feePercent,
    feeAmount: feeAmount,
    net: net,
    timestamp: Date.now()
  });
  t.remainingQty = Math.max(0, t.remainingQty - qty);
  tradeLifetime.sold += net;
  if (t.remainingQty <= 1e-7) {
    const totalSoldValue = t.sells.reduce((s, x) => s + (x.net != null ? x.net : x.total), 0);
    const realizedPl = totalSoldValue - t.qty * t.buyPrice;
    tradeHistory.unshift({
      id: t.id,
      itemName: t.itemName,
      qty: t.qty,
      buyPrice: t.buyPrice,
      createdAt: t.createdAt,
      closedAt: Date.now(),
      totalSoldValue: totalSoldValue,
      realizedPl: realizedPl,
      sells: t.sells
    });
    if (tradeHistory.length > TRADE_HISTORY_CAP) tradeHistory = tradeHistory.slice(0, TRADE_HISTORY_CAP);
    tradeActive = tradeActive.filter(x => x.id !== t.id);
    toast(`✅ ${escapeHtml(t.itemName)} trade closed — moved to History`);
  } else {
    toast(`💰 Sold ${fmt(qty)}× ${escapeHtml(t.itemName)}`);
  }
  saveTradeState();
  closeSellTradeModal();
  renderTradeShop();
};

