if ($("createBudBtn")) {
  $("createBudBtn").onclick = () => {
    const typeId = budSelected.type;
    const stemId = budSelected.stem;
    const auraId = budSelected.aura;
    if (typeId === "none" && stemId === "none") {
      toast("Pick a Type and/or Stem for this BUD 🌱");
      return;
    }
    if (isDuplicateBud(typeId, stemId, auraId)) {
      toast("That exact BUD (Type/Stem/Aura) is already added");
      return;
    }
    const budUID = "bud_" + Date.now() + "_" + Math.random().toString(36).slice(2, 7);
    const entries = buildBudBoostEntries(budUID, typeId, stemId, auraId);
    if (!entries.length) {
      toast("That combo gives no Greenhouse bonus");
      return;
    }
    greenhouseBuds.push({
      id: budUID,
      typeId: typeId,
      stemId: stemId,
      auraId: auraId
    });
    saveGreenhouseBuds();
    entries.forEach(e => {
      BOOSTS.push(e);
      if (!selectedBoosts.includes(e.id)) selectedBoosts.push(e.id);
    });
    saveBoostState();
    renderBoostPanel();
    renderLibraryLists();
    renderGreenhouseList();
    updateCalcSummary();
    updateBudDuplicateState();
    toast("BUD added 🌿");
  };
}

