export function updateLibCraftTotal() {
  const coinCost = parseFloat($("libToolCoinCost").value) || 0;
  const matTotal = craftMaterialRows.reduce((s, r) => s + (r.qty || 0) * getItemCostByName(r.name), 0);
  const total = coinCost + matTotal;
  const yieldQty = Math.max(1e-4, parseFloat($("libProducesQty").value) || 1);
  const perUnit = total / yieldQty;
  $("libCraftTotal").innerHTML = `${fmt(total)} Coins craft cost <span class="eq">→</span> <span class="flower">${fmt(perUnit)} Coins / unit</span>`;
}

