$("saveLibBtn").onclick = () => {
  const name = $("libNameInput").value.trim();
  if (!name) {
    toast("Give it a name 🌱");
    return;
  }
  const producesName = $("libProducesName").value.trim() || name;
  const producesQty = Math.max(1e-4, parseFloat($("libProducesQty").value) || 1);
  const coinCost = parseFloat($("libToolCoinCost").value) || 0;
  const materials = craftMaterialRows.filter(r => r.name).map(r => ({
    name: r.name,
    qty: r.qty || 0
  }));
  let savedItem;
  if (editingLibId) {
    const idx = toolRecipes.findIndex(t => String(t.id) === String(editingLibId));
    const prevManual = toolRecipes[idx].manualPrice ?? null;
    toolRecipes[idx] = {
      ...toolRecipes[idx],
      name: name,
      materials: materials,
      coinCost: coinCost,
      producesName: producesName,
      producesQty: producesQty,
      manualPrice: prevManual
    };
    savedItem = toolRecipes[idx];
  } else {
    savedItem = {
      id: Date.now(),
      name: name,
      materials: materials,
      coinCost: coinCost,
      producesName: producesName,
      producesQty: producesQty,
      manualPrice: null
    };
    toolRecipes.push(savedItem);
  }
  saveToolRecipes();
  syncToolMarketEntry(savedItem);
  renderLibraryLists();
  renderMarketList();
  renderResourceList();
  renderFruitsList();
  updateCalcSummary();
  $("libModal").classList.remove("show");
  toast("Tool saved 🔨");
};

