export const SEA_BLESSED_NODES_PER_PROC = 4;

export function getSeaBlessedRankChances() {
  const data = ASCENSION_RANK_DATA.skill_sea_blessed;
  return data && Array.isArray(data.values) ? data.values.slice() : [];
}

export function computeSeaBlessedAverage(nodeCount, chancePct) {
  const nodes = Math.max(0, Math.floor(nodeCount || 0));
  const chance = Math.max(0, Math.min(100, chancePct || 0));
  const targets = Math.min(SEA_BLESSED_NODES_PER_PROC, nodes);
  const offspring = Math.min(.999, targets * chance / 100);
  const harvestMult = 1 / (1 - offspring);
  return {
    chancePct: chance,
    targets: targets,
    offspring: offspring,
    harvestMult: harvestMult,
    bonusPerHarvest: harvestMult - 1
  };
}

export function computeSeaBlessedRankTable(nodeCount, naturalHarvestsPerDay, yieldPerCharge) {
  return getSeaBlessedRankChances().map((chance, i) => {
    const avg = computeSeaBlessedAverage(nodeCount, chance);
    const bonusHarvestsPerDay = naturalHarvestsPerDay * avg.bonusPerHarvest;
    return {
      rank: i + 1,
      chancePct: chance,
      targets: avg.targets,
      offspring: avg.offspring,
      harvestMult: avg.harvestMult,
      bonusHarvestsPerDay: bonusHarvestsPerDay,
      bonusSaltPerDay: bonusHarvestsPerDay * yieldPerCharge
    };
  });
}

export function computeSaltFarmFigures() {
  const eff = sculptureEffects();
  const nodeCount = Math.min(farmLevelMaxNodes(), getNodeCount("Salt"));
  const timeSec = SALT_BASE_TIME_SEC * eff.chargeTimeMult * getActiveSaltRechargeMult();
  const chargesPerDayPerNode = Math.round(86400 / timeSec);
  const rakeCoinCostBase = getToolCostCoins("default_salt_rake");
  const freeRakeCost = hasFreeSaltRakeCost();
  const rakeCoinCost = freeRakeCost ? 0 : rakeCoinCostBase * eff.rakeCostMult;
  const saltYieldBonus = getActiveSaltYieldBonus();
  const yieldPerCharge = SALT_BASE_YIELD + saltYieldBonus;
  const costPerUnitCoins = rakeCoinCost / yieldPerCharge;
  const costPerUnitFlower = coinsToFlower(costPerUnitCoins);
  const m = marketItems.find(x => (x.name || "").toLowerCase() === "salt");
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const netSell = sellFlower * (1 - feePercent / 100);
  const profitPerUnit = netSell - costPerUnitFlower;
  const naturalHarvestsPerDay = nodeCount * chargesPerDayPerNode;
  const seaBlessedRanks = getSeaBlessedRankChances();
  const seaBlessedActive = isSkillActive("skill_sea_blessed") && seaBlessedRanks.length > 0;
  const seaBlessedRank = seaBlessedActive ? Math.min(Math.max(getAscensionRank("skill_sea_blessed"), 1), seaBlessedRanks.length) : 0;
  const seaBlessedAvg = computeSeaBlessedAverage(nodeCount, seaBlessedActive ? seaBlessedRanks[seaBlessedRank - 1] : 0);
  const harvestsPerDay = naturalHarvestsPerDay * seaBlessedAvg.harvestMult;
  const seaBlessedBonusHarvestsPerDay = harvestsPerDay - naturalHarvestsPerDay;
  const seaBlessed = Object.assign({}, seaBlessedAvg, {
    active: seaBlessedActive,
    rank: seaBlessedRank,
    maxRank: seaBlessedRanks.length,
    naturalHarvestsPerDay: naturalHarvestsPerDay,
    harvestsPerDay: harvestsPerDay,
    harvestsPerDayPerNode: nodeCount > 0 ? harvestsPerDay / nodeCount : 0,
    bonusHarvestsPerDay: seaBlessedBonusHarvestsPerDay,
    bonusSaltPerDay: seaBlessedBonusHarvestsPerDay * yieldPerCharge,
    ranks: computeSeaBlessedRankTable(nodeCount, naturalHarvestsPerDay, yieldPerCharge)
  });
  const saltPerDay = harvestsPerDay * yieldPerCharge;
  const storedChargeCap = eff.storedChargeCap;
  const rakeUsesPerDay = freeRakeCost ? 0 : harvestsPerDay;
  const baseRakeStock = BASE_STOCK_TOOLS["Salt Rake"];
  let restockCost24h = 0, restocksPerDay = 0, boostedRakeStock = 0, restockDetails = null;
  if (baseRakeStock && rakeUsesPerDay > 0) {
    boostedRakeStock = computeBoostedStock(baseRakeStock, "tool", "Salt Rake");
    if (boostedRakeStock > 0) {
      restocksPerDay = restocksForMode(rakeUsesPerDay / boostedRakeStock);
      const gemCostPerRestock = typeof getRestockGemCost === "function" ? getRestockGemCost("tool", "Salt Rake") : RESTOCK_GEM_COST.tools;
      const gemsPerDay = restocksPerDay * gemCostPerRestock;
      restockCost24h = typeof gemsToFlower === "function" ? gemsToFlower(gemsPerDay) : 0;
      restockDetails = {
        flowerCost: restockCost24h,
        boostedStock: boostedRakeStock,
        itemsNeededPerDay: rakeUsesPerDay,
        restocksPerDay: restocksPerDay,
        gemCostPerRestock: gemCostPerRestock,
        gemsPerDay: gemsPerDay,
        stockKind: "tool",
        name: "Salt Rake"
      };
    }
  }
  const activeBoosts = getActiveSaltBoosts("saltGlobal").slice();
  if (seaBlessed.active) {
    activeBoosts.push({
      id: "skill_sea_blessed",
      name: "Sea Blessed",
      note: `Rank ${seaBlessed.rank}/${seaBlessed.maxRank}: ${seaBlessed.chancePct}% chance per harvest to restore 1 charge to ${seaBlessed.targets} node${seaBlessed.targets === 1 ? "" : "s"} → avg ×${seaBlessed.harvestMult.toFixed(4)} harvests (+${seaBlessed.bonusSaltPerDay.toFixed(2)} Salt/day)`
    });
  }
  return {
    nodeCount: nodeCount,
    chargesPerDayPerNode: chargesPerDayPerNode,
    saltPerDay: saltPerDay,
    timeSec: timeSec,
    rakeCoinCost: rakeCoinCost,
    yieldPerCharge: yieldPerCharge,
    saltYieldBonus: saltYieldBonus,
    storedChargeCap: storedChargeCap,
    costPerUnitFlower: costPerUnitFlower,
    costPerUnitCoins: costPerUnitCoins,
    sellFlower: sellFlower,
    netSell: netSell,
    profitPerUnit: profitPerUnit,
    restockCost24h: restockCost24h,
    restocksPerDay: restocksPerDay,
    boostedRakeStock: boostedRakeStock,
    restockDetails: restockDetails,
    rakeUsesPerDay: rakeUsesPerDay,
    harvestsPerDay: harvestsPerDay,
    naturalHarvestsPerDay: naturalHarvestsPerDay,
    seaBlessed: seaBlessed,
    activeBoosts: activeBoosts,
    dailyCost: saltPerDay * costPerUnitFlower,
    dailyRevenue: saltPerDay * netSell,
    dailyProfit: saltPerDay * profitPerUnit - restockCost24h,
    eff: eff
  };
}

export function spiceMaterialMode(matName) {
  return getMaterialMode("SpiceRack", matName);
}

export function setSpiceMaterialMode(matName, mode) {
  setMaterialMode("SpiceRack", matName, mode);
}

export function vegMaterialMode(matName) {
  return getMaterialMode("PickledVeg", matName);
}

export function setVegMaterialMode(matName, mode) {
  setMaterialMode("PickledVeg", matName, mode);
}

function pickledVegCheapest(options) {
  let best = null;
  options.forEach(veg => {
    const entry = pickledVegCost(veg);
    if (!entry) return;
    if (!best || entry.cost < best.cost) best = entry;
  });
  return best;
}

function pickledVegSelected(options, picked) {
  if (picked && options.includes(picked)) return pickledVegCost(picked);
  return pickledVegCheapest(options);
}

function fishCheapest(tierList) {
  let best = tierList[0];
  tierList.forEach(f => {
    if (f.salt < best.salt) best = f;
  });
  return best;
}

function fishSelected(tierList, pickedName) {
  if (pickedName) {
    const found = tierList.find(f => f.name === pickedName);
    if (found) return found;
  }
  return fishCheapest(tierList);
}

export function computeBaitFigures(baitName) {
  const rec = BAIT_RECIPES[baitName];
  const tierList = FISH_SALT_DATA[rec.fishTier];
  const pickedFish = saltUiGet(baitName + "_fish", null);
  const pickedVeg = saltUiGet(baitName + "_veg", null);
  const fish = fishSelected(tierList, pickedFish);
  const veg = pickledVegSelected(rec.vegOptions, pickedVeg);
  const isPrime = saltUiGet(baitName + "_prime", false);
  const primeChancePct = effectivePrimeChancePct();
  const fishCost = fishSaltCostFlower(fish);
  const totalCost = fishCost + (veg ? veg.cost : 0);
  const agingSaltCostMult = typeof getActiveAgingSaltCostMult === "function" ? getActiveAgingSaltCostMult() : 1;
  const fishEffectiveSalt = fish.salt * agingSaltCostMult;
  const bacalhauBonus = typeof isBoostActive === "function" && isBoostActive("skill_bacalhau") ? 1 : 0;
  const astrolabeMult = typeof getActiveFermentationSpiceExpectedMult === "function" ? getActiveFermentationSpiceExpectedMult() : 1;
  const outputAgedBoosted = rec.outputAged * astrolabeMult + bacalhauBonus;
  const outputPrimeBoosted = rec.outputPrime * astrolabeMult + bacalhauBonus;
  const outputSelected = isPrime ? outputPrimeBoosted : outputAgedBoosted;
  const expectedOutput = outputAgedBoosted + (outputPrimeBoosted - outputAgedBoosted) * (primeChancePct / 100);
  const unitCostExpected = totalCost / expectedOutput;
  const unitCostSelected = totalCost / outputSelected;
  const m = marketItems.find(x => (x.name || "").toLowerCase() === baitName.toLowerCase());
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const netSell = sellFlower * (1 - feePercent / 100);
  const profitPerUnitExpected = netSell - unitCostExpected;
  const profitPerUnitSelected = netSell - unitCostSelected;
  const fishOptions = tierList.map(f => ({
    name: f.name,
    salt: f.salt * agingSaltCostMult,
    cost: fishSaltCostFlower(f),
    isCheapest: f.name === fishCheapest(tierList).name,
    isSelected: f.name === fish.name
  })).sort((a, b) => a.cost - b.cost);
  const vegCheapest = pickledVegCheapest(rec.vegOptions);
  const vegOptionsList = rec.vegOptions.map(v => {
    const entry = pickledVegCost(v);
    return {
      name: v,
      cost: entry ? entry.cost : 0,
      isCheapest: !!(vegCheapest && v === vegCheapest.veg),
      isSelected: !!(veg && v === veg.veg)
    };
  }).sort((a, b) => a.cost - b.cost);
  return {
    fish: fish,
    veg: veg,
    fishCost: fishCost,
    fishEffectiveSalt: fishEffectiveSalt,
    totalCost: totalCost,
    outputSelected: outputSelected,
    expectedOutput: expectedOutput,
    unitCostExpected: unitCostExpected,
    unitCostSelected: unitCostSelected,
    isPrime: isPrime,
    sellFlower: sellFlower,
    netSell: netSell,
    profitPerUnitExpected: profitPerUnitExpected,
    profitPerUnitSelected: profitPerUnitSelected,
    primeChancePct: primeChancePct,
    fishOptions: fishOptions,
    vegOptionsList: vegOptionsList,
    outputAgedBoosted: outputAgedBoosted,
    outputPrimeBoosted: outputPrimeBoosted,
    activeBoosts: getActiveSaltBoosts([ "agingGlobal", "fermentationSpiceGlobal" ])
  };
}

export function computeFertilizerFigures(fertName) {
  const rec = SALT_FERTILIZER_DATA[fertName];
  let cost = 0, note = "";
  let vegOptionsList = null;
  if (rec.vegOptions) {
    const pickedVeg = saltUiGet(fertName + "_veg", null);
    const veg = pickledVegSelected(rec.vegOptions, pickedVeg);
    cost = (veg ? veg.cost : 0) + refinedSaltUnitCostFlower() * rec.refinedSalt;
    note = veg ? veg.veg : "";
    const vegCheapest = pickledVegCheapest(rec.vegOptions);
    vegOptionsList = rec.vegOptions.map(v => {
      const entry = pickledVegCost(v);
      return {
        name: v,
        cost: entry ? entry.cost : 0,
        isCheapest: !!(vegCheapest && v === vegCheapest.veg),
        isSelected: !!(veg && v === veg.veg)
      };
    }).sort((a, b) => a.cost - b.cost);
  } else {
    if (rec.sproutMixQty) cost += coinsToFlower(computeComposterFigures("Compost Bin").costPerUnitCoins) * rec.sproutMixQty;
    if (rec.rapidRootQty) cost += coinsToFlower(computeComposterFigures("Premium Composter").costPerUnitCoins) * rec.rapidRootQty;
    if (rec.fruitfulBlendQty) cost += coinsToFlower(computeComposterFigures("Turbo Composter").costPerUnitCoins) * rec.fruitfulBlendQty;
    cost += refinedSaltUnitCostFlower() * rec.refinedSalt;
  }
  const astrolabeMult = typeof getActiveFermentationSpiceExpectedMult === "function" ? getActiveFermentationSpiceExpectedMult() : 1;
  const output = rec.output * astrolabeMult;
  const unitCost = cost / output;
  const applied = isBoostActive("apply_" + fertName.toLowerCase().replace(/\s+/g, "_"));
  return {
    cost: cost,
    unitCost: unitCost,
    note: note,
    output: output,
    effect: rec.effect,
    applied: applied,
    vegOptionsList: vegOptionsList,
    activeBoosts: getActiveSaltBoosts([ "fermentationSpiceGlobal" ])
  };
}

export function computeSpiceFigures(name) {
  const astrolabeMult = typeof getActiveFermentationSpiceExpectedMult === "function" ? getActiveFermentationSpiceExpectedMult() : 1;
  const onesieAdd = typeof getActiveSpiceRackOutputAdd === "function" ? getActiveSpiceRackOutputAdd() : 0;
  const agerMult = getActiveAgerMult();
  const refinerChance = name === "Refined Salt" ? getActiveRefinerChance() : 0;
  const activeBoosts = getActiveSaltBoosts([ "fermentationSpiceGlobal", "spiceRackGlobal" ]);
  const outputFor = r => r.output * agerMult * astrolabeMult + refinerChance + onesieAdd;
  if (name === "Refined Salt") {
    const r = SPICE_RECIPES[name];
    const saltUnit = saltCostFlowerForSpiceRack();
    const saltQty = r.saltQty * agerMult;
    const saltCost = saltUnit * saltQty;
    const output = outputFor(r);
    return {
      cost: saltCost,
      unitCost: saltCost / output,
      output: output,
      ingredients: [ {
        name: "Salt",
        qty: saltQty,
        unitCostFlower: saltUnit,
        cost: saltCost,
        hasToggle: true,
        mode: spiceMaterialMode("Salt")
      } ],
      activeBoosts: activeBoosts
    };
  }
  if (name === "Salt Lick") {
    const r = SPICE_RECIPES[name];
    const rsUnit = refinedSaltUnitCostFlower();
    const rsQty = r.refinedSaltQty * agerMult;
    const rsCost = rsUnit * rsQty;
    const output = outputFor(r);
    return {
      cost: rsCost,
      unitCost: rsCost / output,
      output: output,
      ingredients: [ {
        name: "Refined Salt",
        qty: rsQty,
        unitCostFlower: rsUnit,
        cost: rsCost,
        hasToggle: false
      } ],
      activeBoosts: activeBoosts
    };
  }
  if (name === "Honey Treat") {
    const r = SPICE_RECIPES[name];
    const rsUnit = refinedSaltUnitCostFlower();
    const rsQty = r.refinedSaltQty * agerMult;
    const rsCost = rsUnit * rsQty;
    const honeyUnit = honeyCostFlowerForSpiceRack();
    const honeyQty = r.honeyQty * agerMult;
    const honeyCost = honeyUnit * honeyQty;
    const cost = rsCost + honeyCost;
    const output = outputFor(r);
    return {
      cost: cost,
      unitCost: cost / output,
      output: output,
      ingredients: [ {
        name: "Refined Salt",
        qty: rsQty,
        unitCostFlower: rsUnit,
        cost: rsCost,
        hasToggle: false
      }, {
        name: "Honey",
        qty: honeyQty,
        unitCostFlower: honeyUnit,
        cost: honeyCost,
        hasToggle: true,
        mode: spiceMaterialMode("Honey")
      } ],
      activeBoosts: activeBoosts
    };
  }
  return {
    cost: 0,
    unitCost: 0,
    output: 1,
    ingredients: [],
    activeBoosts: []
  };
}

export function stepperHtml(id, value, min, max) {
  return `<div class="stepper" data-stepper-id="${id}" data-min="${min}" data-max="${max}" style="display:flex;align-items:center;gap:6px;">\n    <button type="button" class="stepper-btn" data-stepper-id="${id}" data-dir="-1" style="width:28px;height:28px;flex:0 0 auto;border-radius:6px;border:1.5px solid var(--line);cursor:pointer;font-size:18px;line-height:1;background:#fff;color:var(--ink);">−</button>\n    <div style="flex:1;text-align:center;font-family:'JetBrains Mono',monospace;font-size:14.4px;font-weight:700;border:1.5px solid var(--line);border-radius:6px;padding:6px 4px;background:#fff;">${fmt(value)}</div>\n    <button type="button" class="stepper-btn" data-stepper-id="${id}" data-dir="1" style="width:28px;height:28px;flex:0 0 auto;border-radius:6px;border:1.5px solid var(--line);cursor:pointer;font-size:18px;line-height:1;background:#fff;color:var(--ink);">+</button>\n  </div>`;
}

export function getIconSmall(name) {
  if (!name) return "";
  const imgSrc = IMAGE_ICONS[name] || Object.entries(IMAGE_ICONS).find(([k]) => k.toLowerCase() === name.trim().toLowerCase())?.[1];
  if (imgSrc) return `<img src="${imgSrc}" alt="${escapeHtml(name)}" style="width:11px;height:11px;image-rendering:pixelated;vertical-align:-2px;">`;
  const emoji = ICONS[name] || Object.entries(ICONS).find(([k]) => k.toLowerCase() === name.trim().toLowerCase())?.[1];
  return `<span style="font-size:13.2px;line-height:1;">${emoji || "🌾"}</span>`;
}

export function runDeferredInitialRender() {
  const steps = [ updateSettingsSummary, renderSeasonToggle, renderBoostPanel, renderLibraryLists, renderMarketList, renderResourceList, renderHoneyList, renderAnimalsList, applyCalcModeVisibility, updateCalcSelectedDisplay, updateCalcSummary, initLivePricesOnLoad, renderBettyShop, farmPanelLoadCachedGameState, renderFarmPanelTabContent ];
  steps.forEach(step => {
    try {
      step();
    } catch (e) {
      console.error("Deferred initial render step failed:", e);
    }
  });
}

let __deferredInitialRenderDone = false;

export const __deferredInitialRenderCallbacks = [];

export function onDeferredInitialRenderDone(cb) {
  if (__deferredInitialRenderDone) {
    cb();
  } else {
    __deferredInitialRenderCallbacks.push(cb);
  }
}

