export async function farmIdPromptStartSync(farmId) {
  if ($("farmPanelIdInput")) $("farmPanelIdInput").value = farmId;
  beginLoadingSequence();
  let res = null;
  try {
    res = await performFarmPanelSync(farmId);
  } catch (e) {
    console.error("Farm panel sync threw unexpectedly:", e);
    __set_farmPanelSyncInFlight(false);
    res = {
      ok: false,
      error: e && e.message ? e.message : String(e)
    };
  } finally {
    finishLoadingSequence();
  }
  if (!res) {
    return;
  }
  setTimeout(() => {
    if (res.ok) showSyncCompleteModal(res.message, {
      title: "SYNC COMPLETE"
    }); else showSyncCompleteModal("⚠️ Couldn't reach the farm data. Check the Farm ID and try again.", {
      title: "SYNC FAILED"
    });
  }, 280);
}

function generateGoblinThought() {
  const A = [ "Me tinkin' 'bout da sunflower price", "Dis whole SFL trade", "Me farm today", "Dat cute farmer gal", "Me lil goblin heart", "Dis harvest season", "Me tradin' strategy", "Dat crush of mine", "Me profit dis week", "Dis loss hit different", "Me lonely goblin nights", "Da market today", "Me crop yield", "Dis farmer life" ];
  const B = [ "make me smile big", "make me cry lil", "make me tinkin' hard", "give me big headache", "make me dance jig", "keep me up all night", "make me heart go boom", "make me wanna quit", "make me rich, heehee", "make me broke, oof", "make me miss someone", "give me butterflies", "make me plan big scheme", "make me laugh like fool" ];
  const C = [ "'bout dat sunflower seed", "'bout gold and gems", "'bout dat pretty farmer", "'bout tomorrow harvest", "'bout me broken heart", "'bout big juicy profit", "'bout dat sneaky trade", "'bout dis lonely night", "'bout SFL to da moon", "'bout me secret crush", "'bout old goblin days", "'bout next big strategy", "'bout dat market crash", "'bout true goblin love" ];
  const D = [ "heehee~", "yaa!", "uh-oh...", "oh no!", "teehee!", "arrr!", "hmm...", "whee!", "oof!", "gyahaha!", "tsk tsk...", "aww~", "woo!", "sigh..." ];
  const E = [ "goblin never give up", "such is farmer life", "dat's just goblin luck", "love hard like farmin'", "profit today, loss tomorrow", "goblin heart forever strong", "SFL life pick me up", "one day she notice me", "goblin gotta keep tradin'", "harvest never sleep", "goblin dream big dream", "market always keep goblin guessin'", "heart want what heart want", "goblin gonna make it big" ];
  const pick = arr => arr[Math.floor(Math.random() * arr.length)];
  return `${pick(A)} ${pick(B)}, ${pick(D)} ${pick(C)}. ${pick(E)}!`;
}

{
  const thoughtEl = document.getElementById("goblinThoughtText");
  if (thoughtEl) thoughtEl.textContent = generateGoblinThought();
}

function beginLoadingSequence() {
  const screen = document.getElementById("appLoadingScreen");
  const fill = document.getElementById("loadingProgressFill");
  const label = document.getElementById("loadingProgressLabel");
  if (!screen || screen.dataset.loadingStarted) {
    window.dispatchEvent(new Event("goblinAppReady"));
    return;
  }
  screen.dataset.loadingStarted = "1";
  screen.classList.remove("show-prompt");
  document.documentElement.style.overflow = "hidden";
  if (fill) fill.style.transform = "scaleX(0)";
  if (label) label.textContent = "SYNCING FARM... 0%";
  if (goblinLoadingProgressTimer) clearInterval(goblinLoadingProgressTimer);
  let i = 0;
  goblinLoadingProgressTimer = setInterval(() => {
    i = Math.min(i + 1, APP_LOADING_STAGES.length - 1);
    const stage = APP_LOADING_STAGES[i];
    if (fill) fill.style.transform = "scaleX(" + stage.pct / 100 + ")";
    if (label) label.textContent = "SYNCING FARM... " + stage.pct + "%";
  }, 550);
}

function finishLoadingSequence() {
  const screen = document.getElementById("appLoadingScreen");
  const fill = document.getElementById("loadingProgressFill");
  const label = document.getElementById("loadingProgressLabel");
  if (goblinLoadingProgressTimer) {
    clearInterval(goblinLoadingProgressTimer);
    goblinLoadingProgressTimer = null;
  }
  if (!screen || !screen.dataset.loadingStarted) return;
  if (fill) fill.style.transform = "scaleX(1)";
  if (label) label.textContent = "SYNCING FARM... 100%";
  screen.classList.add("hide");
  document.documentElement.style.overflow = "";
  setTimeout(() => {
    screen.remove();
  }, 550);
  window.dispatchEvent(new Event("goblinAppReady"));
}

