export function getFishSeasons(name) {
  const d = FISH_CATCH_DATA[name];
  return d && Array.isArray(d.seasons) && d.seasons.length ? d.seasons : SEASON_ORDER.slice();
}

export function isFishInSeason(name, season) {
  season = season || previewSeason;
  return getFishSeasons(name).includes(season);
}

export const FISH_TIER_LABEL = {
  basic: "Basic Fish",
  advanced: "Advance Fish",
  expert: "Expert Fish"
};

export const FISH_CATCH_NAMES = Object.keys(FISH_CATCH_DATA);

export function computeCrabFigures() {
  if (__crabFiguresMemo) return __crabFiguresMemo;
  const rodCost = fishRodCostCoins();
  const yieldMult = typeof fishingCrabYieldMult === "function" ? fishingCrabYieldMult() : 1;
  const costCoins = rodCost / yieldMult;
  __crabFiguresMemo = {
    rodCost: rodCost,
    yieldMult: yieldMult,
    costCoins: costCoins
  };
  return __crabFiguresMemo;
}

export function computeSeaweedFigures() {
  if (__seaweedFiguresMemo) return __seaweedFiguresMemo;
  const rodCost = fishRodCostCoins();
  const yieldMult = typeof fishingCrabYieldMult === "function" ? fishingCrabYieldMult() : 1;
  const costCoins = rodCost / yieldMult;
  __seaweedFiguresMemo = {
    rodCost: rodCost,
    yieldMult: yieldMult,
    costCoins: costCoins
  };
  return __seaweedFiguresMemo;
}

export function fishCatchYieldMult(tier) {
  let mult = 1;
  if (typeof isBoostActive !== "function") return mult;
  if (tier === "basic" && isBoostActive("skill_fishy_chance")) mult += .1;
  if (tier === "advanced" && isBoostActive("skill_fishy_roll")) mult += .1;
  if (tier === "expert" && isBoostActive("skill_fishy_gamble")) mult += .2;
  if (typeof fishingBoostYieldAdd === "function") mult += fishingBoostYieldAdd(tier);
  return mult;
}

