export function fishingBoostsActiveByScope(scope) {
  if (typeof isBoostActive !== "function") return [];
  return FISHING_BOOSTS.filter(b => b.scope === scope && isBoostActive(b.id));
}

function fishingBoostYieldAdd(tier) {
  let add = 0;
  fishingBoostsActiveByScope("fishYield").forEach(b => {
    if (b.tier && b.tier !== tier) return;
    add += b.fishYieldAdd || 0;
  });
  return add;
}

function fishingCrabYieldMult() {
  let mult = 1;
  fishingBoostsActiveByScope("fishCrab").forEach(b => {
    mult += b.crabYieldAdd || 0;
  });
  return mult;
}

export function fishingRodIsFree() {
  return fishingBoostsActiveByScope("fishRod").some(b => b.rodFreeCost);
}

function crustaceanYieldMultBoost() {
  let mult = 1;
  fishingBoostsActiveByScope("crustacean").forEach(b => {
    mult += b.crustaceanYieldAdd || 0;
  });
  return mult;
}

function crustaceanTrapTimeMultBoost() {
  let mult = 1;
  fishingBoostsActiveByScope("crustacean").forEach(b => {
    if (b.crustaceanTrapTimeMult) mult *= b.crustaceanTrapTimeMult;
  });
  return mult;
}

export function crustaceanTrapIsFree() {
  return fishingBoostsActiveByScope("crustacean").some(b => b.crustaceanTrapFreeCost);
}

export let crustaceanChumSelection = safeLSJSON(localStorage.getItem("hl_crustacean_chum_selection"), {});

function getCrustaceanSelectedChum(name) {
  const costs = crustaceanOptionCosts(name);
  if (costs.length <= 1) return costs[0] ? costs[0].chum : null;
  const saved = crustaceanChumSelection[name];
  if (saved && costs.some(c => c.chum === saved)) return saved;
  let cheapest = costs[0];
  costs.forEach(c => {
    if (c.cost < cheapest.cost) cheapest = c;
  });
  return cheapest.chum;
}

export function setCrustaceanSelectedChum(name, chum) {
  crustaceanChumSelection[name] = chum;
  saveCrustaceanChumSelection();
  if (typeof invalidateCostCache === "function") invalidateCostCache();
}

export function computeCrustaceanFigures(name, visited) {
  const d = CRUSTACEAN_CATCH_DATA[name];
  if (!d) return null;
  const trapCost = crustaceanTrapCostCoins(d.trap, visited);
  const options = crustaceanOptionCosts(name, visited);
  const selectedChum = getCrustaceanSelectedChum(name);
  const selected = options.find(o => o.chum === selectedChum) || options[0];
  const chumCost = selected ? selected.cost : 0;
  const yieldMult = typeof crustaceanYieldMultBoost === "function" ? crustaceanYieldMultBoost() : 1;
  const rawCoins = trapCost + chumCost;
  return {
    trap: d.trap,
    trapCost: trapCost,
    options: options,
    selectedChum: selectedChum,
    chumCost: chumCost,
    totalCoins: rawCoins,
    costCoins: rawCoins / yieldMult,
    yieldMult: yieldMult,
    hours: CRUSTACEAN_TRAP_HOURS[d.trap] * (typeof crustaceanTrapTimeMultBoost === "function" ? crustaceanTrapTimeMultBoost() : 1),
    baseHours: CRUSTACEAN_TRAP_HOURS[d.trap]
  };
}

