const PET_SYNC_PREFIX = "pet_sync_";

function farmSyncPickField(obj, keys) {
  if (!obj || typeof obj !== "object") return null;
  for (const k of keys) {
    if (obj[k] != null && obj[k] !== "") return obj[k];
  }
  return null;
}

function farmSyncMapPetAura(raw) {
  const norm = farmSyncNormalizeName(raw);
  if (!norm) return "No Aura";
  if (norm.includes("mythic")) return "Mythic Aura";
  if (norm.includes("rare")) return "Rare Aura";
  if (norm.includes("common")) return "Common Aura";
  return "No Aura";
}

function farmSyncMapPetBib(raw) {
  const norm = farmSyncNormalizeName(raw);
  if (!norm) return "No Bib";
  if (norm.includes("gold")) return "Gold Necklace";
  if (norm.includes("collar")) return "Collar";
  return "No Bib";
}

function petLevelFromXp(xp) {
  const n = Number(xp);
  if (!(n > 0)) return 1;
  if (n < 120) return 1;
  return 1 + Math.floor(Math.sqrt((n - 60) / 60));
}

export function farmSyncExtractPetTraits(pet) {
  if (!pet || typeof pet !== "object") return null;
  const name = farmSyncPickField(pet, [ "name", "nickname", "nickName", "label" ]);
  const traitsObj = pet.traits && typeof pet.traits === "object" && !Array.isArray(pet.traits) ? pet.traits : null;
  let type = farmSyncPickField(pet, [ "type", "petType", "species", "kind", "breed" ]);
  if (!type && traitsObj) type = farmSyncPickField(traitsObj, [ "type", "petType", "species", "kind", "breed" ]);
  if (!type && name) {
    const norm = String(name).trim().toLowerCase();
    const nftMatch = PET_NFT_TYPES.find(t => t.toLowerCase() === norm);
    type = nftMatch || PET_NAME_TO_TYPE[norm] || null;
  }
  if (!type) return null;
  let aura = farmSyncPickField(pet, [ "aura", "Aura" ]);
  let bib = farmSyncPickField(pet, [ "bib", "Bib", "collar", "Collar" ]);
  if (traitsObj) {
    if (!aura) aura = farmSyncPickField(traitsObj, [ "aura", "Aura" ]);
    if (!bib) bib = farmSyncPickField(traitsObj, [ "bib", "Bib", "collar", "Collar" ]);
  }
  const attrs = Array.isArray(pet.attributes) ? pet.attributes : Array.isArray(pet.traits) ? pet.traits : null;
  if (attrs) {
    attrs.forEach(a => {
      if (!a) return;
      const key = farmSyncNormalizeName(a.trait_type || a.type || a.key);
      const val = a.value != null ? a.value : a.val;
      if (val == null) return;
      if (key === "aura" && !aura) aura = val; else if (key === "bib" && !bib) bib = val;
    });
  }
  const levelRaw = farmSyncPickField(pet, [ "level", "lvl" ]);
  const xpRaw = farmSyncPickField(pet, [ "experience", "xp", "exp" ]);
  const level = levelRaw != null ? Math.max(1, parseInt(levelRaw, 10) || 1) : petLevelFromXp(typeof xpRaw === "number" ? xpRaw : parseInt(xpRaw, 10) || 0);
  return {
    type: String(type).trim(),
    name: name != null ? String(name).trim() : null,
    level: level,
    aura: aura,
    bib: bib
  };
}

function farmSyncFlattenPetBag(topBag, merged) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  if (!topBag) return;
  Object.keys(topBag).forEach(catKey => {
    if (catKey !== "common" && catKey !== "nfts") return;
    const cat = asObj(topBag[catKey]);
    if (!cat) return;
    Object.keys(cat).forEach(petKey => {
      const id = catKey + ":" + petKey;
      if (!Object.prototype.hasOwnProperty.call(merged, id)) merged[id] = cat[petKey];
    });
  });
}

export function farmSyncGetPetRecords(g, allowHeuristic) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const merged = {};
  farmSyncFlattenPetBag(asObj(farmPanelField(g, "pets")), merged);
  if (!Object.keys(merged).length) {
    const found = farmSyncFindBagByNameHeuristic(g, /^pets$/i, 4);
    if (found) farmSyncFlattenPetBag(asObj(found.value), merged);
  }
  return merged;
}

let __lastPetsSig = null;

let __lastPetsResult = null;

function syncPetsFromFarmData(g) {
  const records = farmSyncGetPetRecords(g, false);
  const realIds = Object.keys(records);
  const petsSig = realIds.length + "|" + JSON.stringify(records);
  if (petsSig === __lastPetsSig && __lastPetsResult) return __lastPetsResult;
  __lastPetsSig = petsSig;
  const existingSynced = new Map;
  const keptManual = [];
  petsData.forEach(p => {
    if (p && typeof p.id === "string" && p.id.indexOf(PET_SYNC_PREFIX) === 0) {
      existingSynced.set(p.id, p);
    } else {
      keptManual.push(p);
    }
  });
  const freshIds = new Set;
  let matched = 0;
  let changed = false;
  realIds.forEach(realId => {
    const traits = farmSyncExtractPetTraits(records[realId]);
    if (!traits) return;
    const isNFT = PET_NFT_TYPES.includes(traits.type) ? true : PET_COMMON_TYPES.includes(traits.type) ? false : null;
    if (isNFT === null) return;
    const id = PET_SYNC_PREFIX + realId;
    freshIds.add(id);
    matched++;
    const cat = PET_CATEGORIES[traits.type] || {};
    const fallbackName = isNFT ? "Pet #" + realId : (PET_NAMES_BY_TYPE[traits.type] || [ traits.type ])[0];
    const name = traits.name || fallbackName;
    const aura = isNFT ? farmSyncMapPetAura(traits.aura) : "No Aura";
    const bib = isNFT ? farmSyncMapPetBib(traits.bib) : "No Bib";
    const existing = existingSynced.get(id);
    if (!existing) {
      existingSynced.set(id, {
        id: id,
        isNFT: isNFT,
        petType: traits.type,
        name: name,
        level: traits.level,
        categories: cat,
        aura: aura,
        bib: bib,
        synced: true
      });
      changed = true;
    } else {
      if (existing.level !== traits.level) {
        existing.level = traits.level;
        changed = true;
      }
      if (existing.aura !== aura) {
        existing.aura = aura;
        changed = true;
      }
      if (existing.bib !== bib) {
        existing.bib = bib;
        changed = true;
      }
      if (existing.name !== name) {
        existing.name = name;
        changed = true;
      }
      if (existing.petType !== traits.type) {
        existing.petType = traits.type;
        existing.categories = cat;
        existing.isNFT = isNFT;
        changed = true;
      }
      existing.synced = true;
    }
  });
  existingSynced.forEach((pet, id) => {
    if (!freshIds.has(id)) {
      existingSynced.delete(id);
      changed = true;
      if (petOpenId === id) petOpenId = null;
    }
  });
  if (changed) {
    petsData = keptManual.concat(Array.from(existingSynced.values()));
    savePetsData();
    if (typeof __petCardMemo !== "undefined") __petCardMemo.clear();
  }
  const result = {
    matched: matched,
    petCount: realIds.length,
    changed: changed
  };
  __lastPetsResult = result;
  return result;
}

export function isPetFoodChecked(name) {
  return petFoodChecks[name] !== false;
}

function petBoostSum(field) {
  let sum = 0;
  PET_BOOSTS.forEach(b => {
    if (isBoostActive(b.id) && b[field]) sum += b[field];
  });
  return sum;
}

export function petBoostActiveWithField(field) {
  return PET_BOOSTS.some(b => isBoostActive(b.id) && b[field]);
}

function petFetchConfig(petType) {
  const cat = PET_CATEGORIES[petType];
  if (!cat) return [];
  const list = [ {
    name: "Acorn",
    level: 1
  }, {
    name: FETCHES_BY_CATEGORY[cat.primary],
    level: 3
  } ];
  if (cat.secondary) list.push({
    name: FETCHES_BY_CATEGORY[cat.secondary],
    level: 7
  });
  if (cat.tertiary) {
    list.push({
      name: "Moonfur",
      level: 12
    });
    list.push({
      name: FETCHES_BY_CATEGORY[cat.tertiary],
      level: 25
    });
  }
  return list;
}

function petEnergyPerFeed(pet, difficulty) {
  const base = PET_BASE_XP_ENERGY[difficulty];
  let boostEnergy = 0;
  if (pet.level >= 5) boostEnergy += 5;
  if (pet.level >= 35) boostEnergy += 5;
  if (pet.level >= 75) boostEnergy += 5;
  boostEnergy += petBoostSum("petEnergyAdd");
  let energy = base + boostEnergy;
  if (pet.isNFT) energy *= PET_AURA_MULT[pet.aura] || 1;
  return energy;
}

function petXpPerFeed(pet, difficulty) {
  const base = PET_BASE_XP_ENERGY[difficulty];
  let mult = 1;
  if (pet.level >= 27) mult += .1;
  if (pet.level >= 40 && pet.isNFT) mult += .15;
  if (pet.level >= 85 && pet.isNFT) mult += .25;
  let xp = base * mult;
  xp += petBoostSum("petXpAdd");
  if (difficulty === "medium") xp += petBoostSum("petXpAddMedium");
  if (difficulty === "hard") xp += petBoostSum("petXpAddHard");
  if (pet.isNFT) xp += PET_BIB_XP[pet.bib] || 0;
  return xp;
}

function petFetchYieldPerFetch(pet, resource) {
  let amount = 1;
  if (resource !== "Fossil Shell") {
    if (pet.level >= 15) amount += .1;
    if (pet.level >= 50) amount += .05;
    if (pet.level >= 100) amount += .1;
    if (pet.level >= 150 && pet.isNFT && resource === "Moonfur") amount += .25;
  }
  if (resource === "Acorn") {
    if (pet.level >= 18) amount += 1;
    amount += petBoostSum("petFetchAdd");
  }
  if (pet.level >= 60 && pet.isNFT && resource !== "Acorn" && resource !== "Moonfur") amount += 1;
  return amount;
}

function petUnlockedFetches(pet) {
  return petFetchConfig(pet.petType).filter(f => pet.level >= f.level);
}

function petDailyEnergy(pet) {
  let total = 0;
  [ "easy", "medium", "hard" ].forEach(d => {
    total += petEnergyPerFeed(pet, d);
  });
  return total;
}

function petDailyXp(pet) {
  let total = 0;
  [ "easy", "medium", "hard" ].forEach(d => {
    total += petXpPerFeed(pet, d);
  });
  return total;
}

function petComputeCard(pet) {
  const dailyEnergy = petDailyEnergy(pet);
  const dailyXp = petDailyXp(pet);
  const dailyFoodCostFlower = petDailyFoodCostFlower(pet);
  const fee = (typeof feePercent === "number" ? feePercent : 0) / 100;
  const rows = petUnlockedFetches(pet).map(f => {
    const r = f.name;
    const energyCost = PET_RESOURCE_ENERGY[r] || 200;
    const numFetches = energyCost > 0 ? dailyEnergy / energyCost : 0;
    const yieldPerFetch = petFetchYieldPerFetch(pet, r);
    const totalYield = numFetches * yieldPerFetch;
    const tradable = !PET_NOT_TRADABLE.has(r);
    const marketPrice = tradable ? getPetResourceMarket(r) : 0;
    const costPerUnit = totalYield > 0 ? dailyFoodCostFlower / totalYield : 0;
    const gross = tradable ? totalYield * marketPrice : 0;
    const sellFee = tradable ? gross * fee : 0;
    const net = tradable ? gross - sellFee - dailyFoodCostFlower : -dailyFoodCostFlower;
    return {
      name: r,
      energyCost: energyCost,
      numFetches: numFetches,
      totalYield: totalYield,
      tradable: tradable,
      marketPrice: marketPrice,
      costPerUnit: costPerUnit,
      gross: gross,
      sellFee: sellFee,
      net: net
    };
  });
  const bestRow = rows.filter(r => r.tradable).sort((a, b) => b.net - a.net)[0] || null;
  return {
    dailyEnergy: dailyEnergy,
    dailyXp: dailyXp,
    dailyFoodCostFlower: dailyFoodCostFlower,
    rows: rows,
    bestRow: bestRow
  };
}

export function petComputeCardCached(pet) {
  if (__petCardMemo.has(pet.id)) return __petCardMemo.get(pet.id);
  const result = petComputeCard(pet);
  __petCardMemo.set(pet.id, result);
  return result;
}

export function petComputeResourceTotals() {
  const totals = {};
  petsData.forEach(pet => {
    const calc = petComputeCardCached(pet);
    calc.rows.forEach(r => {
      if (!totals[r.name]) {
        totals[r.name] = {
          name: r.name,
          heads: 0,
          nftHeads: 0,
          commonHeads: 0,
          totalYield: 0,
          gross: 0,
          cost: 0,
          sellFee: 0,
          net: 0
        };
      }
      const t = totals[r.name];
      t.heads += 1;
      if (pet.isNFT) t.nftHeads += 1; else t.commonHeads += 1;
      t.totalYield += r.totalYield;
      t.gross += r.gross;
      t.cost += calc.dailyFoodCostFlower;
      t.sellFee += r.sellFee;
      t.net += r.net;
    });
  });
  const order = PET_TRADABLE_RESOURCES;
  return order.map(name => totals[name]).filter(Boolean);
}

