const DIG_COST_CARD_ORDER = [ "Sand Shovel", "Sand Drill", "Oil Drill", "Gold Pickaxe" ];

const DIG_CHAPTER_ARTEFACTS = new Set([ "Scarab", "Cow Skull", "Ancient Clock", "Broken Pillar", "Coprolite", "Moon Crystal", "Ammonite Shell", "Salt Dino Egg", "Otter Pebble" ]);

let digDataState = null;

let digDataWired = false;

let digDataLastSolved = null;

function digDataLoadState() {
  if (digDataState) return digDataState;
  let raw = null;
  try {
    raw = JSON.parse(localStorage.getItem(DIG_DATA_STORE_KEY) || "null");
  } catch (e) {
    raw = null;
  }
  const s = raw && typeof raw === "object" ? raw : {};
  const obj = v => v && typeof v === "object" && !Array.isArray(v) ? v : {};
  digDataState = {
    boosts: obj(s.boosts),
    detected: obj(s.detected),
    mats: obj(s.mats),
    toolsOpen: s.toolsOpen === true
  };
  return digDataState;
}

function digDataSaveState() {
  try {
    localStorage.setItem(DIG_DATA_STORE_KEY, JSON.stringify(digDataLoadState()));
  } catch (e) {}
}

function digBoostOn(id) {
  return digDataLoadState().boosts[id] === true;
}

function digMatMode(owner, name) {
  const v = digDataLoadState().mats[owner + ":" + name];
  if (v === "collect" || v === "buy") return v;
  return name === "Wood" ? "collect" : "buy";
}

function digIconHtml(name) {
  const src = IMAGE_ICONS[name] || IMAGE_ICON_FALLBACK;
  return `<img class="dig-ico" src="${src}" alt="${escapeHtml(name)}" decoding="async">`;
}

function digFmt(n) {
  if (!isFinite(n)) return "—";
  return (Math.round(n * 100) / 100).toLocaleString(undefined, {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2
  });
}

function digToolRecipe(tool) {
  if (tool === "Oil Drill") {
    const rec = esToolRecipeFor("Oil");
    if (!rec) return {
      coins: 100,
      materials: [],
      yieldVal: 0,
      free: false
    };
    return {
      coins: rec.free ? 0 : rec.coins,
      materials: rec.free ? [] : rec.materials,
      yieldVal: rec.yieldVal,
      free: !!rec.free
    };
  }
  if (tool === "Sand Drill") return {
    coins: 40,
    materials: [ {
      name: "Oil",
      qty: 1
    }, {
      name: "Crimstone",
      qty: 1
    }, {
      name: "Wood",
      qty: 3
    }, {
      name: "Leather",
      qty: 1
    } ],
    yieldVal: 1,
    free: false
  };
  return {
    coins: 20,
    materials: [ {
      name: "Wood",
      qty: 2
    }, {
      name: "Stone",
      qty: 1
    } ],
    yieldVal: 1,
    free: false
  };
}

function digCrimstoneRecipe() {
  const rec = esToolRecipeFor("Crimstone");
  if (!rec) return {
    coins: 100,
    materials: [],
    yieldVal: 0,
    free: false
  };
  return {
    coins: rec.free ? 0 : rec.coins,
    materials: rec.free ? [] : rec.materials,
    yieldVal: rec.yieldVal,
    free: !!rec.free
  };
}

function digCrimstoneUseCoins() {
  const r = digCrimstoneRecipe();
  let total = r.coins;
  r.materials.forEach(m => {
    total += m.qty * digMatUnitCoins("Gold Pickaxe", m.name);
  });
  return total;
}

function digCrimstoneUnitCoins() {
  const r = digCrimstoneRecipe();
  if (r.free) return 0;
  if (!(r.yieldVal > 0)) return 0;
  return digCrimstoneUseCoins() / r.yieldVal;
}

function digMatUnitCoins(owner, name) {
  if (name === "Oil") return digOilUnitCoins();
  if (name === "Crimstone" && digMatMode(owner, name) === "collect") return digCrimstoneUnitCoins();
  if (DIG_ALWAYS_BUY_MATS.has(name)) {
    const live = findLivePriceForName(name);
    if (live != null && isFinite(live) && live > 0) return live * coinPerFlower;
    return getMaterialUnitCostCoins(name, "buy");
  }
  if (digMatMode(owner, name) === "collect") {
    return RESOURCE_DATA[name] ? esResourceCollectCoins(name) : getItemCostByName(name);
  }
  return getMaterialUnitCostCoins(name, "buy");
}

function digToolUnitCoins(tool) {
  if (tool === "Sand Shovel" && digBoostOn("ancient_shovel")) return 0;
  const r = digToolRecipe(tool);
  let total = r.coins;
  r.materials.forEach(m => {
    total += m.qty * digMatUnitCoins(tool, m.name);
  });
  return total;
}

function digOilUnitCoins() {
  const r = digToolRecipe("Oil Drill");
  if (!(r.yieldVal > 0)) return 0;
  return digToolUnitCoins("Oil Drill") / r.yieldVal;
}

function digDetectBoosts(g) {
  const placed = farmSyncCollectEquippedAndPlacedNames(g);
  const out = {};
  DIG_BOOST_DEFS.forEach(b => {
    out[b.id] = placed.has(b.name);
  });
  return out;
}

function digApplyDetectedBoosts(g) {
  if (!g || typeof g !== "object" || !(g.bumpkin || g.collectibles || g.inventory)) return;
  const st = digDataLoadState();
  const now = digDetectBoosts(g);
  let changed = false;
  DIG_BOOST_DEFS.forEach(b => {
    const was = st.detected[b.id];
    if (was !== now[b.id]) {
      st.detected[b.id] = now[b.id];
      st.boosts[b.id] = now[b.id];
      changed = true;
    }
  });
  if (changed) digDataSaveState();
}

function digCollectDug(g) {
  const digging = g && g.desert && g.desert.digging || {};
  const grid = Array.isArray(digging.grid) ? digging.grid : [];
  const items = {};
  const toolUses = {};
  const seenDigs = new Set;
  let holes = 0;
  let digs = 0;
  grid.forEach((entry, ei) => {
    const isGroup = Array.isArray(entry);
    (isGroup ? entry : [ entry ]).forEach(h => {
      if (!h || typeof h !== "object") return;
      holes++;
      const tool = typeof h.tool === "string" && h.tool ? h.tool : "Sand Shovel";
      const key = isGroup ? "A" + ei : tool === "Sand Drill" && isFinite(Number(h.dugAt)) ? "D" + Number(h.dugAt) : "H" + ei;
      if (!seenDigs.has(key)) {
        seenDigs.add(key);
        digs++;
        toolUses[tool] = (toolUses[tool] || 0) + 1;
      }
      if (h.items && typeof h.items === "object") {
        Object.keys(h.items).forEach(k => {
          const q = Number(h.items[k]);
          if (isFinite(q) && q > 0) items[k] = (items[k] || 0) + q;
        });
      }
    });
  });
  return {
    items: items,
    toolUses: toolUses,
    holes: holes,
    digs: digs,
    extraDigs: Number(digging.extraDigs) || 0
  };
}

function digPricePct() {
  let pct = 0;
  DIG_BOOST_DEFS.forEach(b => {
    if (b.pricePct && digBoostOn(b.id)) pct += b.pricePct;
  });
  return pct;
}

function digDailyDigLimit() {
  let amount = DIG_BASE_DAILY_DIGS;
  DIG_BOOST_DEFS.forEach(b => {
    if (b.digs && digBoostOn(b.id)) amount += b.digs;
  });
  return amount;
}

function digYieldPerDig(kind) {
  let amount = kind === "Sand" ? DIG_SAND_BASE_YIELD : DIG_CRAB_BASE_YIELD;
  const key = kind === "Sand" ? "sand" : "crab";
  DIG_BOOST_DEFS.forEach(b => {
    if (b[key] && digBoostOn(b.id)) amount += b[key];
  });
  return amount;
}

function digItemPrice(name, pct) {
  const base = SELLABLE_TREASURES[name];
  if (typeof base === "number") {
    return {
      base: base,
      price: base * (1 + pct / 100),
      sellable: true
    };
  }
  const live = findLivePriceForName(name);
  const coins = live != null && isFinite(live) ? live * coinPerFlower : getItemCostByName(name) || 0;
  return {
    base: coins,
    price: coins,
    sellable: false
  };
}

function digBoostGridHtml() {
  return DIG_BOOST_DEFS.map(b => `<div class="betty-boost-row dig-boost-card${digBoostOn(b.id) ? " is-on" : ""}">\n      <span class="dig-boost-icon">${digIconHtml(b.icon)}</span>\n      <div class="betty-boost-row-main dig-boost-main">\n        <div class="betty-boost-row-name dig-boost-name">${escapeHtml(b.name)}</div>\n        <div class="betty-boost-row-desc dig-boost-desc">${escapeHtml(b.desc)}</div>\n      </div>\n      <label class="bg-sim-check"><input type="checkbox" data-dig-boost="${b.id}" aria-label="${escapeHtml(b.name)}"${digBoostOn(b.id) ? " checked" : ""}></label>\n    </div>`).join("");
}

function digMatToggleHtml(owner, name) {
  if (name === "Oil") return '<div class="es-toolcfg-free">Always Collect</div>';
  if (DIG_ALWAYS_BUY_MATS.has(name)) return '<div class="es-toolcfg-free">Always Buy</div>';
  const mode = digMatMode(owner, name);
  const attrs = 'data-dig-mat-owner="' + escapeHtml(owner) + '" data-dig-mat-name="' + escapeHtml(name) + '"';
  return '<div class="es-toolcfg-tog"><button type="button" class="es-mode-btn es-toolcfg-tbtn' + (mode === "collect" ? " active" : "") + '" ' + attrs + ' data-dig-mat-mode="collect">Collect</button><button type="button" class="es-mode-btn es-toolcfg-tbtn' + (mode === "buy" ? " active" : "") + '" ' + attrs + ' data-dig-mat-mode="buy">Buy</button></div>';
}

function digMatRowHtml(owner, m) {
  const cost = m.qty * digMatUnitCoins(owner, m.name);
  return '<div class="es-toolcfg-mat"><div class="es-toolcfg-mat-name"><span class="es-toolcfg-qty">×' + digFmt(m.qty) + "</span>" + digIconHtml(m.name) + '<span class="es-toolcfg-cost dig-coin-val">(' + digFmt(cost) + COIN_ICON + ")</span></div>" + digMatToggleHtml(owner, m.name) + "</div>";
}

function digToolSectionHtml(tool) {
  const isPick = tool === "Gold Pickaxe";
  const r = isPick ? digCrimstoneRecipe() : digToolRecipe(tool);
  const coinRow = r.coins > 0 ? '<div class="es-toolcfg-mat"><div class="es-toolcfg-mat-name"><span class="es-toolcfg-qty">×' + digFmt(r.coins) + "</span>" + COIN_ICON + "</div></div>" : "";
  const matRows = r.materials.map(m => digMatRowHtml(tool, m)).join("");
  const unitRow = (label, val) => '<div class="es-toolcfg-mat dig-tool-unit"><span>' + label + '</span><span class="es-toolcfg-qty dig-coin-val">' + digFmt(val) + COIN_ICON + "</span></div>";
  let head = "";
  if (tool === "Sand Shovel" && digBoostOn("ancient_shovel")) head = '<div class="es-toolcfg-free">Free (Ancient Shovel)</div>';
  if ((tool === "Oil Drill" || isPick) && r.free) head = '<div class="es-toolcfg-free">Free tool</div>';
  const yieldRow = (resource, yieldVal, unit) => '<div class="es-toolcfg-mat dig-tool-unit dig-yield-row"><span>' + resource + ' Yield</span><span class="es-toolcfg-qty dig-coin-val">×' + digFmt(yieldVal) + digIconHtml(resource) + " (" + digFmt(unit) + COIN_ICON + "/Unit)</span></div>";
  let units;
  if (tool === "Oil Drill") units = unitRow("Cost per use", digToolUnitCoins(tool)) + yieldRow("Oil", r.yieldVal, digOilUnitCoins());
  else if (isPick) units = unitRow("Cost per use", digCrimstoneUseCoins()) + yieldRow("Crimstone", r.yieldVal, digCrimstoneUnitCoins());
  else units = unitRow("Cost per tool", digToolUnitCoins(tool));
  return '<div class="es-toolcfg-block"><div class="es-toolcfg-head"><div class="es-toolcfg-name">' + digIconHtml(tool) + "<span>" + escapeHtml(tool) + "</span></div>" + head + '</div><div class="es-toolcfg-mats-label">Materials:</div>' + coinRow + matRows + units + "</div>";
}

function digRenderToolCfg() {
  const btn = $("digToolCfgBtn");
  const panel = $("digToolCfgPanel");
  if (!btn || !panel) return;
  const open = digDataLoadState().toolsOpen;
  btn.innerHTML = digIconHtml("Axe") + " Tool Costs" + '<span class="es-toolcfg-chev"></span>';
  btn.classList.toggle("active", open);
  btn.setAttribute("aria-expanded", open ? "true" : "false");
  panel.style.display = open ? "" : "none";
  panel.innerHTML = open ? '<div class="es-toolcfg">' + DIG_COST_CARD_ORDER.map(digToolSectionHtml).join("") + "</div>" : "";
}

function digTreasurePriceHtml(solved, pct) {
  const artefact = solved && solved.artefactName;
  const names = Object.keys(SELLABLE_TREASURES).filter(n => !DIG_CHAPTER_ARTEFACTS.has(n) || n === artefact);
  return names.map(name => {
    const p = digItemPrice(name, pct);
    const boosted = pct > 0;
    const tag = name === "Sand" || name === "Crab" ? `<span class="dig-yield-tag" title="Yield per dig">×${digYieldPerDig(name)}</span>` : "";
    const vals = boosted ? `<span class="dig-price-base is-struck">${digFmt(p.base)}</span><span class="dig-price-boosted">${digFmt(p.price)}</span>` : `<span class="dig-price-base">${digFmt(p.base)}</span>`;
    return `<div class="dig-price-row">${digIconHtml(name)}<span class="dig-price-name" title="${escapeHtml(name)}">${escapeHtml(name)}${tag}</span><span class="dig-price-vals">${vals}${COIN_ICON}</span></div>`;
  }).join("");
}

function digDugTreasuresHtml(dug, pct) {
  const rows = Object.keys(dug.items).map(name => {
    const p = digItemPrice(name, pct);
    return {
      name: name,
      qty: dug.items[name],
      total: p.price * dug.items[name]
    };
  }).sort((a, b) => b.total - a.total);
  if (!rows.length) return '<div class="dig-empty">Nothing dug yet — sync your farm.</div>';
  return rows.map(r => `<div class="dig-dug-row"><span class="dig-dug-qty">×${digFmt(r.qty)}</span>${digIconHtml(r.name)}<span class="dig-dug-name" title="${escapeHtml(r.name)}">${escapeHtml(r.name)}</span><span class="dig-dug-val">${digFmt(r.total)}${COIN_ICON}</span></div>`).join("");
}

function digRewardIconHtml(name) {
  const src = IMAGE_ICONS[name] || COOKING_FOOD_IMAGES[name] || KEY_ICON_DATA[name] || DIG_EXTRA_ICONS[name] || IMAGE_ICON_FALLBACK;
  return `<img class="dig-ico" src="${src}" alt="${escapeHtml(name)}" decoding="async">`;
}

function digUtcDay(ms) {
  return new Date(ms).toISOString().substring(0, 10);
}

function digStreakTierIndex(count) {
  if (count >= 10) return 2;
  if (count >= 4) return 1;
  return 0;
}

function digStreakCandidates(count) {
  const idx = Array.from(new Set([ digStreakTierIndex(count), digStreakTierIndex(Math.max(0, count - 1)) ]));
  const out = [];
  const seen = new Set;
  idx.forEach(i => DIG_STREAK_TIERS[i].rewards.forEach(r => {
    const key = r.name + ":" + r.qty;
    if (seen.has(key)) return;
    seen.add(key);
    out.push({
      name: r.name,
      qty: r.qty
    });
  }));
  return out;
}

function digStreakLoad() {
  let raw = null;
  try {
    raw = JSON.parse(localStorage.getItem(DIG_STREAK_STORE_KEY) || "null");
  } catch (e) {
    raw = null;
  }
  const s = raw && typeof raw === "object" ? raw : {};
  return {
    snap: s.snap && typeof s.snap === "object" ? s.snap : null,
    rewards: s.rewards && typeof s.rewards === "object" && !Array.isArray(s.rewards) ? s.rewards : {}
  };
}

function digStreakSave(st) {
  const keys = Object.keys(st.rewards).sort((a, b) => Number(a) - Number(b));
  while (keys.length > 7) delete st.rewards[keys.shift()];
  try {
    localStorage.setItem(DIG_STREAK_STORE_KEY, JSON.stringify(st));
  } catch (e) {}
}

function digStreakSnapshot(g, today) {
  const inv = {};
  const act = {};
  const src = g.inventory && typeof g.inventory === "object" ? g.inventory : {};
  const fa = g.farmActivity && typeof g.farmActivity === "object" ? g.farmActivity : {};
  DIG_STREAK_ITEM_NAMES.forEach(name => {
    inv[name] = Number(src[name]) || 0;
    DIG_STREAK_ACTIVITY_SUFFIXES.forEach(sfx => {
      const v = Number(fa[name + " " + sfx]);
      if (isFinite(v) && v) act[name + " " + sfx] = v;
    });
  });
  const dug = digCollectDug(g);
  const streak = g.desert && g.desert.digging && g.desert.digging.streak;
  return {
    ca: streak ? Number(streak.collectedAt) || 0 : 0,
    inv: inv,
    act: act,
    td: today,
    tu: {
      "Sand Shovel": dug.toolUses["Sand Shovel"] || 0,
      "Sand Drill": dug.toolUses["Sand Drill"] || 0
    }
  };
}

function digStreakAdjustedDelta(name, snap, cur, shovelFree) {
  let d = (cur.inv[name] || 0) - (snap.inv && snap.inv[name] || 0);
  DIG_STREAK_ACTIVITY_SUFFIXES.forEach((sfx, i) => {
    const k = name + " " + sfx;
    const diff = Math.max(0, (cur.act[k] || 0) - (snap.act && snap.act[k] || 0));
    d += i < 3 ? -diff : diff;
  });
  if ((name === "Sand Shovel" && !shovelFree) || name === "Sand Drill") {
    const before = snap.td === cur.td && snap.tu ? snap.tu[name] || 0 : 0;
    d += Math.max(0, (cur.tu[name] || 0) - before);
  }
  return Math.round(d * 1000) / 1000;
}

function digStreakResolve(snap, cur, count, shovelFree) {
  const matches = digStreakCandidates(count).filter(c => digStreakAdjustedDelta(c.name, snap, cur, shovelFree) === c.qty);
  if (matches.length !== 1) return null;
  const items = {};
  items[matches[0].name] = matches[0].qty;
  return items;
}

export function digStreakTrackFromState(g) {
  const digging = g && g.desert && g.desert.digging;
  const streak = digging && digging.streak;
  if (!streak || !g.inventory || typeof g.inventory !== "object") return;
  const collectedAt = Number(streak.collectedAt) || 0;
  const today = digUtcDay(Date.now());
  const st = digStreakLoad();
  const cur = digStreakSnapshot(g, today);
  const key = String(collectedAt);
  if (collectedAt > 0 && digUtcDay(collectedAt) === today && !st.rewards[key]) {
    let items = null;
    if (st.snap && st.snap.inv && st.snap.ca !== collectedAt) {
      items = digStreakResolve(st.snap, cur, Number(streak.count) || 0, digBoostOn("ancient_shovel"));
    }
    st.rewards[key] = {
      items: items,
      auto: !!items
    };
  }
  st.snap = cur;
  digStreakSave(st);
}

function digStreakInfo(g) {
  const streak = g && g.desert && g.desert.digging && g.desert.digging.streak;
  if (!streak) return {
    count: 0,
    claimed: false,
    key: "",
    rec: null
  };
  const collectedAt = Number(streak.collectedAt) || 0;
  const today = digUtcDay(Date.now());
  const claimed = collectedAt > 0 && digUtcDay(collectedAt) === today;
  const gap = collectedAt > 0 ? (Date.parse(today) - Date.parse(digUtcDay(collectedAt))) / 864e5 : 2;
  const key = String(collectedAt);
  return {
    count: gap > 1 ? 0 : Number(streak.count) || 0,
    claimed: claimed,
    key: key,
    rec: claimed ? digStreakLoad().rewards[key] || null : null
  };
}

function digStreakArtefactName() {
  const n = digDataLastSolved && digDataLastSolved.artefactName;
  return typeof n === "string" && n ? n : "Otter Pebble";
}

function digStreakBonusItems(info) {
  const items = Object.assign({}, info.rec && info.rec.items || {});
  if (info.claimed && info.rec && info.rec.items) {
    const art = digStreakArtefactName();
    items[art] = (items[art] || 0) + 1;
  }
  return items;
}

function digStreakSetManual(el) {
  const g = farmPanelGameState ? farmSyncExtractGameState(farmPanelGameState) : null;
  const info = digStreakInfo(g);
  if (!info.claimed) return;
  const st = digStreakLoad();
  let items = null;
  const pick = el.getAttribute("data-dig-streak-pick");
  if (pick) {
    const cut = pick.lastIndexOf(":");
    const qty = Number(pick.slice(cut + 1));
    if (cut > 0 && isFinite(qty) && qty > 0) {
      items = {};
      items[pick.slice(0, cut)] = qty;
    }
  }
  st.rewards[info.key] = {
    items: items,
    auto: false
  };
  digStreakSave(st);
}

function digStreakTiersHtml() {
  const total = t => t.rewards.reduce((sum, r) => sum + r.w, 0);
  return DIG_STREAK_TIERS.map(t => {
    const sum = total(t);
    const rows = t.rewards.map((r, i) => ({
      r: r,
      i: i
    })).sort((a, b) => b.r.w - a.r.w || a.i - b.i).map(({ r }) => {
      const pct = Number((r.w / sum * 100).toPrecision(3));
      return `<div class="dig-dug-row dig-streak-row">${digRewardIconHtml(r.name)}<span class="dig-dug-name" title="${escapeHtml(r.name)}">${escapeHtml(r.name)}<span class="dig-streak-qty">×${digFmt(r.qty)}</span></span><span class="dig-dug-val">${pct}%</span></div>`;
    }).join("");
    return `<div class="dig-data-label dig-sublabel">${escapeHtml(t.name)}<span class="dig-streak-days">${escapeHtml(t.days)}</span></div>${rows}`;
  }).join("");
}

function digStreakItemRowHtml(name, qty, pct) {
  const sellable = typeof SELLABLE_TREASURES[name] === "number";
  const val = sellable ? `<span class="dig-dug-val">${digFmt(digItemPrice(name, pct).price * qty)}${COIN_ICON}</span>` : "";
  return `<div class="dig-dug-row"><span class="dig-dug-qty">×${digFmt(qty)}</span>${digRewardIconHtml(name)}<span class="dig-dug-name" title="${escapeHtml(name)}">${escapeHtml(name)}</span>${val}</div>`;
}

function digStreakDugHtml(info, pct) {
  const label = `<div class="dig-data-label dig-sublabel">${digFmt(info.count)} Digging Streak Reward</div>`;
  if (!info.claimed) return label + '<div class="dig-empty">Not claimed today.</div>';
  const detected = info.rec && info.rec.items;
  const art = digStreakArtefactName();
  const artRow = digStreakItemRowHtml(art, 1, pct);
  if (!detected) {
    const picks = digStreakCandidates(info.count).map(c => `<label class="dig-dug-row dig-streak-pick"><span class="dig-dug-qty">×${digFmt(c.qty)}</span>${digRewardIconHtml(c.name)}<span class="dig-dug-name" title="${escapeHtml(c.name)}">${escapeHtml(c.name)}</span><span class="bg-sim-check"><input type="checkbox" data-dig-streak-pick="${escapeHtml(c.name)}:${c.qty}" aria-label="${escapeHtml(c.name)}"></span></label>`).join("");
    return label + '<div class="dig-empty">Reward not detected. Select what you received:</div><div class="dig-streak-picks">' + picks + "</div>";
  }
  const rows = Object.keys(detected).map(name => digStreakItemRowHtml(name, detected[name], pct)).join("");
  return label + rows + artRow + '<div class="dig-streak-change-wrap"><span class="dig-streak-change" role="button" tabindex="0" data-dig-streak-edit="1">Change</span></div>';
}

function digTotalsHtml(dug, pct, reward) {
  const freeShovel = digBoostOn("ancient_shovel");
  const rewardItems = reward || {};
  const uses = Object.assign({}, dug.toolUses);
  const rewardShovel = Number(rewardItems["Sand Shovel"]) || 0;
  const rewardDrill = Number(rewardItems["Sand Drill"]) || 0;
  if (rewardShovel) uses["Sand Shovel"] = Math.max(0, (uses["Sand Shovel"] || 0) - rewardShovel);
  if (rewardDrill) {
    const usedDrill = uses["Sand Drill"] || 0;
    const fromDrill = Math.min(usedDrill, rewardDrill);
    uses["Sand Drill"] = usedDrill - fromDrill;
    const leftover = rewardDrill - fromDrill;
    if (leftover > 0) uses["Sand Shovel"] = Math.max(0, (uses["Sand Shovel"] || 0) - leftover * 4);
  }
  const shownTools = Object.keys(uses).filter(tool => uses[tool] > 0 && !(freeShovel && tool === "Sand Shovel"));
  let totalCoins = 0;
  Object.keys(dug.items).forEach(name => {
    totalCoins += digItemPrice(name, pct).price * dug.items[name];
  });
  Object.keys(rewardItems).forEach(name => {
    if (typeof SELLABLE_TREASURES[name] === "number") totalCoins += digItemPrice(name, pct).price * rewardItems[name];
  });
  let totalCost = 0;
  const parts = [];
  shownTools.forEach(tool => {
    const unit = DIG_TOOL_ORDER.indexOf(tool) !== -1 ? digToolUnitCoins(tool) : 0;
    totalCost += unit * uses[tool];
    parts.push(tool + " ×" + uses[tool]);
  });
  const net = totalCoins - totalCost;
  const limit = digDailyDigLimit();
  const left = Math.max(0, limit - dug.digs) + dug.extraDigs;
  const freeRow = freeShovel && dug.toolUses["Sand Shovel"] ? '<div class="dig-dug-row"><span class="dig-dug-qty"></span>' + digIconHtml("Ancient Shovel") + '<span class="dig-dug-name">Ancient Shovel (Free Digging)</span></div>' : "";
  const toolRows = freeRow + shownTools.sort((a, b) => uses[b] - uses[a]).map(tool => `<div class="dig-dug-row"><span class="dig-dug-qty">×${digFmt(uses[tool])}</span>${digIconHtml(tool)}<span class="dig-dug-name">${escapeHtml(tool)}</span></div>`).join("");
  const usedTools = toolRows ? `<div class="dig-data-label dig-sublabel">Used Tools</div>${toolRows}` : "";
  const row = (label, val, cls, title) => `<div class="dig-total-row${cls ? " " + cls : ""}"${title ? ` title="${escapeHtml(title)}"` : ""}><span class="dig-total-label">${label}</span><span class="dig-total-val">${val}</span></div>`;
  return usedTools + '<div class="dig-totals-sep"></div>' + row("Digs Left", `${digFmt(left)} <small>(${digFmt(dug.digs)}/${digFmt(limit + dug.extraDigs)} used)</small>`, "") + row("Total Coins", digFmt(totalCoins) + COIN_ICON, "") + row("Total Cost", digFmt(totalCost) + COIN_ICON, "", parts.join(", ")) + row("Net", (net > 0 ? "+" : "") + digFmt(net) + COIN_ICON, (net > 0 ? "is-profit" : net < 0 ? "is-loss" : "") + " dig-total-net");
}

export function renderDigDataPanel(solved) {
  const card = $("digDataCard");
  if (!card || !card.isConnected) return;
  if (solved) digDataLastSolved = solved;
  const g = farmPanelGameState ? farmSyncExtractGameState(farmPanelGameState) : null;
  digApplyDetectedBoosts(g);
  digWireDataPanel();
  const dug = digCollectDug(g);
  const pct = digPricePct();
  $("digBoostGrid").innerHTML = digBoostGridHtml();
  digRenderToolCfg();
  $("digDugList").innerHTML = digDugTreasuresHtml(dug, pct);
  const streakInfo = digStreakInfo(g);
  $("digStreakDug").innerHTML = digStreakDugHtml(streakInfo, pct);
  $("digDugTotals").innerHTML = digTotalsHtml(dug, pct, digStreakBonusItems(streakInfo));
  $("digPriceList").innerHTML = digTreasurePriceHtml(digDataLastSolved, pct);
  $("digStreakList").innerHTML = digStreakTiersHtml();
}

function digWireDataPanel() {
  if (digDataWired) return;
  const card = $("digDataCard");
  if (!card || !card.isConnected) return;
  digDataWired = true;
  card.addEventListener("change", ev => {
    const el = ev.target;
    if (!el || !el.matches || !el.matches("input[data-dig-boost]")) return;
    digDataLoadState().boosts[el.getAttribute("data-dig-boost")] = el.checked;
    digDataSaveState();
    renderDigDataPanel();
  });
  card.addEventListener("click", ev => {
    const t = ev.target && ev.target.closest ? ev.target.closest("#digToolCfgBtn, [data-dig-mat-mode], [data-dig-streak-pick], [data-dig-streak-edit]") : null;
    if (!t) return;
    if (t.hasAttribute("data-dig-streak-pick") || t.hasAttribute("data-dig-streak-edit")) {
      digStreakSetManual(t);
      renderDigDataPanel();
      return;
    }
    const st = digDataLoadState();
    if (t.id === "digToolCfgBtn") {
      st.toolsOpen = !st.toolsOpen;
    } else {
      st.mats[t.getAttribute("data-dig-mat-owner") + ":" + t.getAttribute("data-dig-mat-name")] = t.getAttribute("data-dig-mat-mode");
    }
    digDataSaveState();
    renderDigDataPanel();
  });
}

