let potionDataState = null;

let potionDataWired = false;

function potionDataLoadState() {
  if (potionDataState) return potionDataState;
  let raw = null;
  try {
    raw = JSON.parse(localStorage.getItem(POTION_DATA_STORE_KEY) || "null");
  } catch (e) {
    raw = null;
  }
  const s = raw && typeof raw === "object" ? raw : {};
  const obj = v => v && typeof v === "object" && !Array.isArray(v) ? v : {};
  potionDataState = {
    boosts: obj(s.boosts),
    detected: obj(s.detected)
  };
  return potionDataState;
}

function potionDataSaveState() {
  try {
    localStorage.setItem(POTION_DATA_STORE_KEY, JSON.stringify(potionDataLoadState()));
  } catch (e) {}
}

function potionBoostOn(id) {
  return potionDataLoadState().boosts[id] === true;
}

function potionApplyDetectedBoosts(g) {
  if (!g || typeof g !== "object" || !(g.bumpkin || g.collectibles || g.inventory)) return;
  const st = potionDataLoadState();
  const placed = farmSyncCollectEquippedAndPlacedNames(g);
  let changed = false;
  POTION_BOOST_DEFS.forEach(b => {
    const now = placed.has(b.name);
    if (st.detected[b.id] !== now) {
      st.detected[b.id] = now;
      st.boosts[b.id] = now;
      changed = true;
    }
  });
  if (changed) potionDataSaveState();
}

function potionIconHtml(name, cls) {
  const src = POTION_STORE_ICONS[name] || IMAGE_ICONS[name] || IMAGE_ICON_FALLBACK;
  return `<img class="${cls || "dig-ico"}" src="${src}" alt="${escapeHtml(name)}" title="${escapeHtml(name)}" decoding="async">`;
}

function potionFmtInt(n) {
  return Math.floor(Number(n) || 0).toLocaleString();
}

function potionTicketBalance(g) {
  const inv = g && g.inventory && typeof g.inventory === "object" ? g.inventory : null;
  const v = inv ? Number(inv["Potion Ticket"]) : 0;
  return isFinite(v) && v > 0 ? Math.floor(v) : 0;
}

function potionFeeMult() {
  let m = 1;
  POTION_BOOST_DEFS.forEach(b => {
    if (potionBoostOn(b.id)) m *= b.feeMult;
  });
  return m;
}

